window.CHAPTER_DATA = {"1":"<section class=\"chapter-section\" id=\"ch1\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">1</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 1: Integers</h2>\r\n      <p>NCERT Exercise 1.1 to 1.3 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"concept-card\">\r\n    <div class=\"concept-header\">📌 Key Concepts &amp; Properties Summary</div>\r\n    <ul class=\"concept-list\">\r\n      <li><strong>Integers (ℤ (Integers)):</strong> The set {..., -3, -2, -1, 0, 1, 2, 3, ...} containing whole numbers and their negatives.</li>\r\n      <li><strong>Addition &amp; Subtraction Properties:</strong>\r\n        <ul>\r\n          <li><em>Closure:</em> a + b and a - b are always integers.</li>\r\n          <li><em>Commutative:</em> a + b = b + a. (Note: a - b ≠ b - a).</li>\r\n          <li><em>Associative:</em> (a + b) + c = a + (b + c).</li>\r\n          <li><em>Additive Identity:</em> a + 0 = a = 0 + a. Additive inverse of a is -a.</li>\r\n        </ul>\r\n      </li>\r\n      <li><strong>Multiplication Properties:</strong>\r\n        <ul>\r\n          <li><em>Rules of Signs:</em> (+) × (+) = (+), (-) × (-) = (+), (+) × (-) = (-), (-) × (+) = (-).</li>\r\n          <li><em>Distributive Property over Addition:</em> a × (b + c) = (a × b) + (a × c).</li>\r\n          <li><em>Distributive Property over Subtraction:</em> a × (b - c) = (a × b) - (a × c).</li>\r\n          <li><em>Multiplicative Identity:</em> a × 1 = a. Product with zero: a × 0 = 0.</li>\r\n        </ul>\r\n      </li>\r\n      <li><strong>Division of Integers:</strong>\r\n        <ul>\r\n          <li>(-a) ÷ b = a ÷ (-b) = -(a ÷ b) when b ≠ 0.</li>\r\n          <li>(-a) ÷ (-b) = a ÷ b.</li>\r\n          <li>Division by 0 is meaningless (a ÷ 0 is undefined); 0 ÷ a = 0 (a ≠ 0); a ÷ 1 = a.</li>\r\n        </ul>\r\n      </li>\r\n    </ul>\r\n  </div>\r\n\r\n  <!-- EXERCISE 1.1 -->\r\n  <div class=\"ex-div\">Exercise 1.1</div>\r\n\r\n  <div class=\"q-card\" id=\"q1_1_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_1_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Write down a pair of integers whose: (a) sum is −7, (b) difference is −10, (c) sum is 0.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) Sum is −7:</strong><br>\r\n            Let the two integers be <span class=\"math\">−4</span> and <span class=\"math\">−3</span>.<br>\r\n            Verification: <span class=\"math\">(−4) + (−3) = −4 − 3 = −7</span>.<br>\r\n            <em>(Another valid pair: −10 and 3, since −10 + 3 = −7).</em>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) Difference is −10:</strong><br>\r\n            Let the two integers be <span class=\"math\">−12</span> and <span class=\"math\">−2</span>.<br>\r\n            Verification: <span class=\"math\">(−12) − (−2) = −12 + 2 = −10</span>.<br>\r\n            <em>(Another valid pair: 2 and 12, since 2 − 12 = −10).</em>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) Sum is 0:</strong><br>\r\n            Any integer and its additive inverse.<br>\r\n            Let the integers be <span class=\"math\">5</span> and <span class=\"math\">−5</span>.<br>\r\n            Verification: <span class=\"math\">5 + (−5) = 5 − 5 = 0</span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): Stating a valid pair with verification</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): Stating a valid pair with subtraction step</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (c): Stating additive inverse pair with sum verification</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q1_1_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_1_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">(a) Write a pair of negative integers whose difference gives 8.<br>(b) Write a negative integer and a positive integer whose sum is −5.<br>(c) Write a negative integer and a positive integer whose difference is −3.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) Pair of negative integers with difference 8:</strong><br>\r\n            Let the negative integers be <span class=\"math\">−2</span> and <span class=\"math\">−10</span>.<br>\r\n            Calculation: <span class=\"math\">(−2) − (−10) = −2 + 10 = 8</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) Negative integer and positive integer with sum −5:</strong><br>\r\n            Let the negative integer be <span class=\"math\">−7</span> and the positive integer be <span class=\"math\">2</span>.<br>\r\n            Calculation: <span class=\"math\">(−7) + 2 = −5</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) Negative integer and positive integer with difference −3:</strong><br>\r\n            Let the negative integer be <span class=\"math\">−1</span> and the positive integer be <span class=\"math\">2</span>.<br>\r\n            Calculation: <span class=\"math\">(−1) − (+2) = −1 − 2 = −3</span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): (−2) − (−10) = 8 with signs shown</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): (−7) + 2 = −5</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (c): (−1) − 2 = −3</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q1_1_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_1_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">In a quiz, team A scored −40, 10, 0 and team B scored 10, 0, −40 in three successive rounds. Which team scored more? Can we say that we can add integers in any order?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Total score of Team A:</strong><br>\r\n            <span class=\"math\">Total score of Team A = (−40) + 10 + 0 = −30</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Total score of Team B:</strong><br>\r\n            <span class=\"math\">Total score of Team B = 10 + 0 + (−40) = 10 − 40 = −30</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 3: Comparison &amp; Order Property:</strong><br>\r\n            Both teams scored <span class=\"math\">−30</span>. Hence, both teams scored equally; neither team scored more.<br>\r\n            <strong>Yes</strong>, we can add integers in any order due to the <strong>Commutative and Associative Properties of addition</strong>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating both total scores accurately (−30 each)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmative answer stating commutative property</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q1_1_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_1_4')\">\r\n      <div class=\"q-num\">Q4</div>\r\n      <div class=\"q-text\">Fill in the blanks to make the following statements true:<br>(i) (−5) + (−8) = (−8) + (.....)<br>(ii) −53 + ..... = −53<br>(iii) 17 + ..... = 0<br>(iv) [13 + (−12)] + (.....) = 13 + [(−12) + (−7)]<br>(v) (−4) + [15 + (−3)] = [(−4) + 15] + (.....)</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) (−5) + (−8) = (−8) + (−5)</strong> &nbsp;&nbsp;<em>[Commutative property: a + b = b + a]</em><br>\r\n            <strong>(ii) −53 + 0 = −53</strong> &nbsp;&nbsp;<em>[Additive identity: a + 0 = a]</em><br>\r\n            <strong>(iii) 17 + (−17) = 0</strong> &nbsp;&nbsp;<em>[Additive inverse: a + (-a) = 0]</em><br>\r\n            <strong>(iv) [13 + (−12)] + (−7) = 13 + [(−12) + (−7)]</strong> &nbsp;&nbsp;<em>[Associative property]</em><br>\r\n            <strong>(v) (−4) + [15 + (−3)] = [(−4) + 15] + (−3)</strong> &nbsp;&nbsp;<em>[Associative property]</em>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct fill-in-the-blank with underlying property</span><span class=\"marking-marks\">0.6 Mark each (Total 3 Marks)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 1.2 -->\r\n  <div class=\"ex-div\">Exercise 1.2</div>\r\n\r\n  <div class=\"q-card\" id=\"q1_2_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_2_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Find each of the following products:<br>(a) 3 × (−1)<br>(b) (−1) × 225<br>(c) (−21) × (−30)<br>(d) (−316) × (−1)<br>(e) (−15) × 0 × (−18)<br>(f) (−12) × (−11) × (10)<br>(g) 9 × (−3) × (−6)<br>(h) (−18) × (−5) × (−4)<br>(i) (−1) × (−2) × (−3) × 4<br>(j) (−3) × (−6) × (−2) × (−1)</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) <span class=\"math\">3 × (−1) = −3</span></strong> &nbsp;<em>[(+) × (−) = (−)]</em><br>\r\n            <strong>(b) <span class=\"math\">(−1) × 225 = −225</span></strong><br>\r\n            <strong>(c) <span class=\"math\">(−21) × (−30) = +(21 × 30) = <strong>630</strong></span></strong> &nbsp;<em>[(−) × (−) = (+)]</em><br>\r\n            <strong>(d) <span class=\"math\">(−316) × (−1) = <strong>316</strong></span></strong><br>\r\n            <strong>(e) <span class=\"math\">(−15) × 0 × (−18) = <strong>0</strong></span></strong> &nbsp;<em>[Any number multiplied by 0 is 0]</em><br>\r\n            <strong>(f) <span class=\"math\">(−12) × (−11) × 10 = 132 × 10 = <strong>1320</strong></span></strong><br>\r\n            <strong>(g) <span class=\"math\">9 × (−3) × (−6) = 9 × 18 = <strong>162</strong></span></strong><br>\r\n            <strong>(h) <span class=\"math\">(−18) × (−5) × (−4) = 90 × (−4) = <strong>−360</strong></span></strong> &nbsp;<em>[3 negative signs ⇒ result is negative]</em><br>\r\n            <strong>(i) <span class=\"math\">(−1) × (−2) × (−3) × 4 = [2] × [−12] = <strong>−24</strong></span></strong><br>\r\n            <strong>(j) <span class=\"math\">(−3) × (−6) × (−2) × (−1) = 18 × 2 = <strong>36</strong></span></strong> &nbsp;<em>[4 negative signs ⇒ result is positive]</em>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Sign rule correct application</span><span class=\"marking-marks\">2 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">All 10 numerical values accurately computed</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q1_2_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_2_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Verify the following:<br>(a) 18 × [7 + (−3)] = [18 × 7] + [18 × (−3)]<br>(b) (−21) × [(−4) + (−6)] = [(−21) × (−4)] + [(−21) × (−6)]</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) Verification of Distributive Property:</strong><br>\r\n            <span class=\"math\">LHS = 18 × [7 + (−3)] = 18 × [7 − 3] = 18 × 4 = <strong>72</strong></span>.<br>\r\n            <span class=\"math\">RHS = [18 × 7] + [18 × (−3)] = 126 + (−54) = 126 − 54 = <strong>72</strong></span>.<br>\r\n            Since <span class=\"math\">LHS = RHS = 72</span>, the statement is <strong>verified</strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) Verification:</strong><br>\r\n            <span class=\"math\">LHS = (−21) × [(−4) + (−6)] = (−21) × [−10] = <strong>210</strong></span>.<br>\r\n            <span class=\"math\">RHS = [(−21) × (−4)] + [(−21) × (−6)] = 84 + 126 = <strong>210</strong></span>.<br>\r\n            Since <span class=\"math\">LHS = RHS = 210</span>, the statement is <strong>verified</strong>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): LHS = 72 and RHS = 72 shown with conclusion</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): LHS = 210 and RHS = 210 shown with conclusion</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q1_2_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_2_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">Find the product using suitable properties:<br>(a) 26 × (−48) + (−48) × (−36)<br>(b) 8 × 53 × (−125)<br>(c) 15 × (−25) × (−4) × (−10)<br>(d) (−41) × 102<br>(e) 625 × (−35) + (−625) × 65<br>(f) 7 × (50 − 2)<br>(g) (−17) × (−29)<br>(h) (−57) × (−19) + 57</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) <span class=\"math\">26 × (−48) + (−48) × (−36)</span>:</strong><br>\r\n            Take common factor <span class=\"math\">(−48)</span> using Distributive Property:<br>\r\n            <span class=\"math\">= (−48) × [26 + (−36)] = (−48) × (−10) = <strong>480</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) <span class=\"math\">8 × 53 × (−125)</span>:</strong><br>\r\n            Regroup using Associative &amp; Commutative Property:<br>\r\n            <span class=\"math\">= [8 × (−125)] × 53 = (−1000) × 53 = <strong>−53000</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) <span class=\"math\">15 × (−25) × (−4) × (−10)</span>:</strong><br>\r\n            Group <span class=\"math\">(−25) × (−4) = 100</span>:<br>\r\n            <span class=\"math\">= 15 × 100 × (−10) = 1500 × (−10) = <strong>−15000</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(d) <span class=\"math\">(−41) × 102</span>:</strong><br>\r\n            Write <span class=\"math\">102 = 100 + 2</span>:<br>\r\n            <span class=\"math\">= (−41) × (100 + 2) = (−41 × 100) + (−41 × 2) = −4100 − 82 = <strong>−4182</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(e) <span class=\"math\">625 × (−35) + (−625) × 65</span>:</strong><br>\r\n            Rewrite <span class=\"math\">(−625) × 65 = 625 × (−65)</span>:<br>\r\n            <span class=\"math\">= 625 × [(−35) + (−65)] = 625 × (−100) = <strong>−62500</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(f) <span class=\"math\">7 × (50 − 2)</span>:</strong><br>\r\n            <span class=\"math\">= (7 × 50) − (7 × 2) = 350 − 14 = <strong>336</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(g) <span class=\"math\">(−17) × (−29)</span>:</strong><br>\r\n            Write <span class=\"math\">−29 = −30 + 1</span>:<br>\r\n            <span class=\"math\">= (−17) × (−30 + 1) = [(−17) × (−30)] + [(−17) × 1] = 510 − 17 = <strong>493</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(h) <span class=\"math\">(−57) × (−19) + 57</span>:</strong><br>\r\n            Note that <span class=\"math\">(−57) × (−19) = 57 × 19</span> and <span class=\"math\">57 = 57 × 1</span>:<br>\r\n            <span class=\"math\">= 57 × [19 + 1] = 57 × 20 = <strong>1140</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating property name (Distributive / Regrouping)</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate step-by-step simplification for all parts</span><span class=\"marking-marks\">2.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 1.3 -->\r\n  <div class=\"ex-div\">Exercise 1.3</div>\r\n\r\n  <div class=\"q-card\" id=\"q1_3_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_3_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Evaluate each of the following:<br>(a) (−30) ÷ 10<br>(b) 50 ÷ (−5)<br>(c) (−36) ÷ (−9)<br>(d) (−49) ÷ (49)<br>(e) 13 ÷ [(−2) + 1]<br>(f) 0 ÷ (−12)<br>(g) (−31) ÷ [(−30) + (−1)]<br>(h) [(−36) ÷ 12] ÷ 3<br>(i) [(−6) + 5] ÷ [(−2) + 1]</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) <span class=\"math\">(−30) ÷ 10 = −30/10 = <strong>−3</strong></span></strong><br>\r\n            <strong>(b) <span class=\"math\">50 ÷ (−5) = −50/5 = <strong>−10</strong></span></strong><br>\r\n            <strong>(c) <span class=\"math\">(−36) ÷ (−9) = +36/9 = <strong>4</strong></span></strong><br>\r\n            <strong>(d) <span class=\"math\">(−49) ÷ 49 = <strong>−1</strong></span></strong><br>\r\n            <strong>(e) <span class=\"math\">13 ÷ [(−2) + 1] = 13 ÷ (−1) = <strong>−13</strong></span></strong><br>\r\n            <strong>(f) <span class=\"math\">0 ÷ (−12) = <strong>0</strong></span></strong> &nbsp;<em>[Zero divided by any non-zero integer is 0]</em><br>\r\n            <strong>(g) <span class=\"math\">(−31) ÷ [(−30) + (−1)] = (−31) ÷ (−31) = <strong>1</strong></span></strong><br>\r\n            <strong>(h) <span class=\"math\">[(−36) ÷ 12] ÷ 3 = (−3) ÷ 3 = <strong>−1</strong></span></strong><br>\r\n            <strong>(i) <span class=\"math\">[(−6) + 5] ÷ [(−2) + 1] = (−1) ÷ (−1) = <strong>1</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Sign rule in division accurately applied</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct evaluation of nested brackets</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q1_3_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_3_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Verify that a ÷ (b + c) ≠ (a ÷ b) + (a ÷ c) for each of the following values of a, b and c:<br>(a) a = 12, b = −4, c = 2<br>(b) a = (−10), b = 1, c = 1</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) When a = 12, b = −4, c = 2:</strong><br>\r\n            <span class=\"math\">LHS = a ÷ (b + c) = 12 ÷ [(−4) + 2] = 12 ÷ (−2) = <strong>−6</strong></span>.<br>\r\n            <span class=\"math\">RHS = (a ÷ b) + (a ÷ c) = [12 ÷ (−4)] + [12 ÷ 2] = (−3) + 6 = <strong>3</strong></span>.<br>\r\n            Since <span class=\"math\">−6 ≠ 3</span>, <span class=\"math\">LHS ≠ RHS</span>. Verified that division is not distributive over addition!\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) When a = −10, b = 1, c = 1:</strong><br>\r\n            <span class=\"math\">LHS = (−10) ÷ (1 + 1) = (−10) ÷ 2 = <strong>−5</strong></span>.<br>\r\n            <span class=\"math\">RHS = [(−10) ÷ 1] + [(−10) ÷ 1] = (−10) + (−10) = <strong>−20</strong></span>.<br>\r\n            Since <span class=\"math\">−5 ≠ −20</span>, <span class=\"math\">LHS ≠ RHS</span>. Verified!\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): LHS = −6, RHS = 3, LHS ≠ RHS</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): LHS = −5, RHS = −20, LHS ≠ RHS</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q1_3_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q1_3_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">An elevator descends into a mine shaft at the rate of 6 m/min. If the descent starts from 10 m above the ground level, how long will it take to reach −350 m?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Determine total distance to descend:</strong><br>\r\n            Initial position = <span class=\"math\">+10 m</span> (above ground).<br>\r\n            Final position = <span class=\"math\">−350 m</span> (below ground).<br>\r\n            Total distance = <span class=\"math\">10 − (−350) = 10 + 350 = <strong>360 m</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Calculate time taken:</strong><br>\r\n            Speed of descent = <span class=\"math\">6 m/min</span>.<br>\r\n            <span class=\"math\">Time taken = Distance/Speed = 360/6 = <strong>60 minutes</strong> = <strong>1 hour</strong></span>.\r\n          </div>\r\n          <p><strong>Final Answer:</strong> The elevator will take <strong>1 hour (60 minutes)</strong> to reach −350 m.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Distance formulation: 10 − (−350) = 360 m</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Time = 360/6 = 60 min = 1 hour with unit</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n    <div class=\"q-card\" id=\"q1_2_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_2_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Starting from (−1) × 5, write various products showing some pattern to show (−1) × (−1) = 1.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Observe the pattern decreasing the multiplier by 1 at each step:</strong><br>\n            <span class=\"math\">(−1) × 5 = −5</span><br>\n            <span class=\"math\">(−1) × 4 = −4 = (−5) + 1</span><br>\n            <span class=\"math\">(−1) × 3 = −3 = (−4) + 1</span><br>\n            <span class=\"math\">(−1) × 2 = −2 = (−3) + 1</span><br>\n            <span class=\"math\">(−1) × 1 = −1 = (−2) + 1</span><br>\n            <span class=\"math\">(−1) × 0 = 0 = (−1) + 1</span><br>\n            <span class=\"math\">(−1) × (−1) = 0 + 1 = <strong>1</strong></span>\n          </div>\n          <p>This systematic pattern proves that the product of two negative integers is a positive integer: <span class=\"math\">(−) × (−) = (+)</span>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing steps from (−1) × 5 down to 0 with +1 pattern</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Concluding (−1) × (−1) = 1 with property</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q1_3_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_3_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Fill in the blanks to make the statements true:<br>(a) 369 ÷ _____ = 369<br>(b) (−75) ÷ _____ = −1<br>(c) (−206) ÷ _____ = 1<br>(d) −87 ÷ _____ = 87<br>(e) _____ ÷ 1 = −87<br>(f) _____ ÷ 48 = −1<br>(g) 20 ÷ _____ = −2<br>(h) _____ ÷ (4) = −3</div>\n      <div class=\"q-marks\">4 Marks (1/2 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a)</strong> <span class=\"math\">369 ÷ <strong>1</strong> = 369</span> &nbsp;<em>[Identity element of division]</em><br>\n            <strong>(b)</strong> <span class=\"math\">(−75) ÷ <strong>75</strong> = −1</span><br>\n            <strong>(c)</strong> <span class=\"math\">(−206) ÷ <strong>(−206)</strong> = 1</span><br>\n            <strong>(d)</strong> <span class=\"math\">−87 ÷ <strong>(−1)</strong> = 87</span><br>\n            <strong>(e)</strong> <span class=\"math\"><strong>(−87)</strong> ÷ 1 = −87</span><br>\n            <strong>(f)</strong> <span class=\"math\"><strong>(−48)</strong> ÷ 48 = −1</span><br>\n            <strong>(g)</strong> <span class=\"math\">20 ÷ <strong>(−10)</strong> = −2</span><br>\n            <strong>(h)</strong> <span class=\"math\"><strong>(−12)</strong> ÷ 4 = −3</span>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct integer with accurate sign</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q1_3_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_3_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Write five pairs of integers (a, b) such that a ÷ b = −3. (One such pair is (6, −2) because 6 ÷ (−2) = −3).</div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Five pairs of integers <span class=\"math\">(a, b)</span> satisfying <span class=\"math\">a ÷ b = −3</span>:<br>\n            1. <strong>(−6, 2)</strong> since <span class=\"math\">(−6) ÷ 2 = −3</span>.<br>\n            2. <strong>(9, −3)</strong> since <span class=\"math\">9 ÷ (−3) = −3</span>.<br>\n            3. <strong>(−9, 3)</strong> since <span class=\"math\">(−9) ÷ 3 = −3</span>.<br>\n            4. <strong>(12, −4)</strong> since <span class=\"math\">12 ÷ (−4) = −3</span>.<br>\n            5. <strong>(−15, 5)</strong> since <span class=\"math\">(−15) ÷ 5 = −3</span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each valid pair with accurate verification</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q1_3_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_3_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">The temperature at 12 noon was 10°C above zero. If it decreases at the rate of 2°C per hour until midnight, at what time would the temperature be 8°C below zero? What would be the temperature at midnight?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) Time when temperature is 8°C below zero (−8°C):</strong><br>\n            Initial temperature at 12 noon = <span class=\"math\">+10°C</span>.<br>\n            Target temperature = <span class=\"math\">−8°C</span>.<br>\n            Total change in temperature = <span class=\"math\">10°C − (−8°C) = 18°C</span>.<br>\n            Rate of decrease = <span class=\"math\">2°C per hour</span>.<br>\n            Time taken = <span class=\"math\">18 ÷ 2 = 9 hours</span>.<br>\n            Time = 12 noon + 9 hours = <strong>9:00 PM</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) Temperature at midnight (12:00 AM):</strong><br>\n            Time duration from 12 noon to midnight = 12 hours.<br>\n            Total temperature decrease = <span class=\"math\">12 × 2°C = 24°C</span>.<br>\n            Temperature at midnight = <span class=\"math\">10°C − 24°C = <strong>−14°C</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The temperature will be 8°C below zero at <strong>9:00 PM</strong>, and the temperature at midnight will be <strong>−14°C</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating time taken = 9 hours, giving 9:00 PM</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculating midnight temperature = 10 − 24 = −14°C</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q1_3_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_3_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">In a class test (+3) marks are given for every correct answer and (−2) marks are given for every incorrect answer and no marks for not attempting any question.<br>(i) Radhika scored 20 marks. If she has got 12 correct answers, how many questions has she attempted incorrectly?<br>(ii) Mohini scores −5 marks in this test, though she has got 7 correct answers. How many questions has she attempted incorrectly?</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) For Radhika:</strong><br>\n            Marks given for 1 correct answer = +3.<br>\n            Marks for 12 correct answers = <span class=\"math\">12 × 3 = 36</span>.<br>\n            Total score obtained = 20.<br>\n            Marks obtained for incorrect answers = <span class=\"math\">20 − 36 = −16</span>.<br>\n            Marks deducted for each incorrect answer = −2.<br>\n            Number of incorrect answers = <span class=\"math\">(−16) ÷ (−2) = <strong>8</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) For Mohini:</strong><br>\n            Marks for 7 correct answers = <span class=\"math\">7 × 3 = 21</span>.<br>\n            Total score obtained = −5.<br>\n            Marks obtained for incorrect answers = <span class=\"math\">−5 − 21 = −26</span>.<br>\n            Number of incorrect answers = <span class=\"math\">(−26) ÷ (−2) = <strong>13</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> Radhika attempted <strong>8 questions incorrectly</strong>, and Mohini attempted <strong>13 questions incorrectly</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): Formulating (20 − 36)/(-2) = 8 incorrect answers</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): Formulating (-5 − 21)/(-2) = 13 incorrect answers</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\">\r\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\r\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\r\n    </div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">Case Study: Temperature Variation</div>\r\n        <div class=\"cbq-question\"><strong>Scenario:</strong> In a cold storage plant, the temperature at 12:00 noon was 10°C above zero. It decreases at a rate of 2°C per hour until midnight. (i) At what time would the temperature be 8°C below zero? (ii) What would be the temperature at midnight?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <p><strong>(i) Time when temperature is 8°C below zero (−8°C):</strong><br>\r\n          Initial temp = +10°C; Target temp = −8°C.<br>\r\n          Total drop in temp = <span class=\"math\">10 − (−8) = 18°C</span>.<br>\r\n          Rate of drop = <span class=\"math\">2°C/hour</span>.<br>\r\n          Time taken = <span class=\"math\">18 ÷ 2 = 9 hours</span>.<br>\r\n          Time = 12 noon + 9 hours = <strong>9:00 PM</strong>.</p>\r\n          <p><strong>(ii) Temperature at midnight (12:00 AM):</strong><br>\r\n          Time duration from 12 noon to 12 midnight = 12 hours.<br>\r\n          Drop in temperature = <span class=\"math\">12 × 2°C = 24°C</span>.<br>\r\n          Temp at midnight = <span class=\"math\">10 − 24 = <strong>−14°C</strong></span>.</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#10b981;\">⚡ Assertion &amp; Reason</div>\r\n        <div class=\"cbq-question\">\r\n          <strong>Assertion (A):</strong> The product of an odd number of negative integers is always negative.<br>\r\n          <strong>Reason (R):</strong> Two negative signs pair up to produce a positive sign, leaving one unpaired negative sign when the count is odd.<br>\r\n          Choose: (a) Both A and R are true and R is correct explanation of A. (b) Both A and R are true, but R is not correct explanation. (c) A is true, R is false. (d) A is false, R is true.\r\n        </div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <strong>Answer: (a) Both A and R are true and R is the correct explanation of A.</strong><br>\r\n          <em>Explanation:</em> Every pair of negative integers gives a positive product: <span class=\"math\">(−) × (−) = (+)</span>. For an odd count <span class=\"math\">2k + 1</span>, the <span class=\"math\">k</span> pairs give <span class=\"math\">(+)</span>, and multiplying with the remaining negative integer yields <span class=\"math\">(+) × (−) = (−)</span>.\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn\" disabled style=\"opacity:.35;\">← Previous</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(2)\">Chapter 2: Fractions &amp; Decimals →</button>\r\n  </div>\r\n</section>\r\n","2":"<section class=\"chapter-section\" id=\"ch2\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">2</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 2: Fractions and Decimals</h2>\r\n      <p>NCERT Exercise 2.1 to 2.5 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"concept-card\">\r\n    <div class=\"concept-header\">📌 Key Concepts &amp; Formulas Summary</div>\r\n    <ul class=\"concept-list\">\r\n      <li><strong>Types of Fractions:</strong>\r\n        <ul>\r\n          <li><em>Proper Fraction:</em> Numerator &lt; Denominator (e.g. 3/5). Value &lt; 1.</li>\r\n          <li><em>Improper Fraction:</em> Numerator ≥ Denominator (e.g. 7/4). Value ≥ 1. Can be written as Mixed Fraction: 1 3/4.</li>\r\n        </ul>\r\n      </li>\r\n      <li><strong>Multiplication of Fractions:</strong>\r\n        (Numerator₁ × Numerator₂)/(Denominator₁ × Denominator₂)\r\n        The operator 'of' signifies multiplication: 1/2 of  24 = 1/2 × 24 = 12.\r\n      </li>\r\n      <li><strong>Reciprocal of a Fraction:</strong> The non-zero number obtained by interchanging numerator and denominator. Product with original fraction equals 1: a/b × b/a = 1.</li>\r\n      <li><strong>Division of Fractions:</strong> Multiply by the reciprocal of the divisor: a/b ÷ c/d = a/b × d/c.</li>\r\n      <li><strong>Decimal Operations:</strong>\r\n        <ul>\r\n          <li>Multiplying by 10, 100, 1000: Shift decimal point to the right by as many places as there are zeros.</li>\r\n          <li>Dividing by 10, 100, 1000: Shift decimal point to the left by as many places as there are zeros.</li>\r\n          <li>Division by decimal: Multiply both dividend and divisor by suitable powers of 10 to make divisor a whole number.</li>\r\n        </ul>\r\n      </li>\r\n    </ul>\r\n  </div>\r\n\r\n  <!-- EXERCISE 2.1 -->\r\n  <div class=\"ex-div\">Exercise 2.1</div>\r\n\r\n  <div class=\"q-card\" id=\"q2_1_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_1_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Solve the following fractions:<br>(i) 2 − 3/5<br>(ii) 4 + 7/8<br>(iii) 3/5 + 2/7<br>(iv) 9/11 − 4/15<br>(v) 7/10 + 2/5 + 3/2<br>(vi) 2⅔ + 3½<br>(vii) 8½ − 3⅝</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">2 − 3/5</span>:</strong><br>\r\n            <span class=\"math\">= 2/1 − 3/5 = (2 × 5 − 3)/5 = (10 − 3)/5 = <strong>7/5</strong> = <strong>1 2/5</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) <span class=\"math\">4 + 7/8</span>:</strong><br>\r\n            <span class=\"math\">= (4 × 8 + 7)/8 = (32 + 7)/8 = <strong>39/8</strong> = <strong>4 7/8</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) <span class=\"math\">3/5 + 2/7</span>:</strong><br>\r\n            LCM of 5 and 7 is 35.<br>\r\n            <span class=\"math\">= (3 × 7 + 2 × 5)/35 = (21 + 10)/35 = <strong>31/35</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iv) <span class=\"math\">9/11 − 4/15</span>:</strong><br>\r\n            LCM of 11 and 15 is 165.<br>\r\n            <span class=\"math\">= (9 × 15 − 4 × 11)/165 = (135 − 44)/165 = <strong>91/165</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(v) <span class=\"math\">7/10 + 2/5 + 3/2</span>:</strong><br>\r\n            LCM of 10, 5, 2 is 10.<br>\r\n            <span class=\"math\">= (7 + (2 × 2) + (3 × 5))/10 = (7 + 4 + 15)/10 = 26/10 = <strong>13/5</strong> = <strong>2 3/5</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(vi) <span class=\"math\">2 2/3 + 3 1/2</span>:</strong><br>\r\n            Convert to improper fractions: <span class=\"math\">8/3 + 7/2</span>. LCM of 3, 2 is 6.<br>\r\n            <span class=\"math\">= (8 × 2 + 7 × 3)/6 = (16 + 21)/6 = <strong>37/6</strong> = <strong>6 1/6</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(vii) <span class=\"math\">8 1/2 − 3 5/8</span>:</strong><br>\r\n            Convert to improper fractions: <span class=\"math\">17/2 − 29/8</span>. LCM of 2, 8 is 8.<br>\r\n            <span class=\"math\">= (17 × 4 − 29)/8 = (68 − 29)/8 = <strong>39/8</strong> = <strong>4 7/8</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">LCM determination and equivalent fractions</span><span class=\"marking-marks\">2 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Correctly evaluated and simplified final fractions</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q2_1_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_1_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Arrange the following in descending order:<br>(i) 2/9, 2/3, 8/21<br>(ii) 1/5, 3/7, 7/10</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) 2/9, 2/3, 8/21:</strong><br>\r\n            LCM of denominators 9, 3, 21 is 63.<br>\r\n            Convert each to like fractions:<br>\r\n            <span class=\"math\">2/9 = (2 × 7)/63 = 14/63</span><br>\r\n            <span class=\"math\">2/3 = (2 × 21)/63 = 42/63</span><br>\r\n            <span class=\"math\">8/21 = (8 × 3)/63 = 24/63</span><br>\r\n            Comparing numerators: <span class=\"math\">42 > 24 > 14</span>.<br>\r\n            <strong>Descending order: <span class=\"math\"><strong>2/3 > 8/21 > 2/9</strong></span></strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) 1/5, 3/7, 7/10:</strong><br>\r\n            LCM of 5, 7, 10 is 70.<br>\r\n            <span class=\"math\">1/5 = (1 × 14)/70 = 14/70</span><br>\r\n            <span class=\"math\">3/7 = (3 × 10)/70 = 30/70</span><br>\r\n            <span class=\"math\">7/10 = (7 × 7)/70 = 49/70</span><br>\r\n            Comparing numerators: <span class=\"math\">49 > 30 > 14</span>.<br>\r\n            <strong>Descending order: <span class=\"math\"><strong>7/10 > 3/7 > 1/5</strong></span></strong>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): LCM = 63 and correct descending order</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): LCM = 70 and correct descending order</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 2.2 -->\r\n  <div class=\"ex-div\">Exercise 2.2</div>\r\n\r\n  <div class=\"q-card\" id=\"q2_2_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_2_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Multiply and reduce to lowest form and convert into a mixed fraction:<br>(i) 7 × 3/5<br>(ii) 4 × 1/3<br>(iii) 2 × 6/7<br>(iv) 5 × 2/9<br>(v) 2/3 × 4<br>(vi) 5/2 × 6<br>(vii) 11 × 4/7</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">7 × 3/5 = 21/5 = <strong>4 1/5</strong></span></strong><br>\r\n            <strong>(ii) <span class=\"math\">4 × 1/3 = 4/3 = <strong>1 1/3</strong></span></strong><br>\r\n            <strong>(iii) <span class=\"math\">2 × 6/7 = 12/7 = <strong>1 5/7</strong></span></strong><br>\r\n            <strong>(iv) <span class=\"math\">5 × 2/9 = 10/9 = <strong>1 1/9</strong></span></strong><br>\r\n            <strong>(v) <span class=\"math\">2/3 × 4 = 8/3 = <strong>2 2/3</strong></span></strong><br>\r\n            <strong>(vi) <span class=\"math\">5/2 × 6 = 5 × 3 = <strong>15</strong></span></strong><br>\r\n            <strong>(vii) <span class=\"math\">11 × 4/7 = 44/7 = <strong>6 2/7</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Numerator multiplication and conversion to mixed fraction</span><span class=\"marking-marks\">3 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q2_2_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_2_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Find: (a) ½ of (i) 24 (ii) 46<br>(b) ⅔ of (i) 18 (ii) 27<br>(c) ¾ of (i) 16 (ii) 36</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) ½ of:</strong><br>\r\n            (i) <span class=\"math\">1/2 × 24 = <strong>12</strong></span><br>\r\n            (ii) <span class=\"math\">1/2 × 46 = <strong>23</strong></span>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) ⅔ of:</strong><br>\r\n            (i) <span class=\"math\">2/3 × 18 = 2 × 6 = <strong>12</strong></span><br>\r\n            (ii) <span class=\"math\">2/3 × 27 = 2 × 9 = <strong>18</strong></span>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) ¾ of:</strong><br>\r\n            (i) <span class=\"math\">3/4 × 16 = 3 × 4 = <strong>12</strong></span><br>\r\n            (ii) <span class=\"math\">3/4 × 36 = 3 × 9 = <strong>27</strong></span>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with multiplication setup</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q2_2_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_2_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">A car runs 16 km using 1 litre of petrol. How much distance will it cover using 2¾ litres of petrol?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Quantity of petrol given:</strong><br>\r\n            <span class=\"math\">2 3/4 litres = (2 × 4 + 3)/4 = 11/4 litres</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Calculate total distance:</strong><br>\r\n            Distance covered in 1 litre = <span class=\"math\">16 km</span>.<br>\r\n            Total distance = <span class=\"math\">16 × 11/4 = (16 × 11)/4 = 4 × 11 = <strong>44 km</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> The car will cover <strong>44 km</strong> using 2¾ litres of petrol.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Improper fraction conversion: 11/4 litres</span><span class=\"marking-marks\">0.5 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Multiplication 16 × (11/4) = 44 km with statement</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 2.3 -->\r\n  <div class=\"ex-div\">Exercise 2.3</div>\r\n\r\n  <div class=\"q-card\" id=\"q2_3_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_3_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Find the reciprocal of each of the following fractions. Classify the reciprocals as proper fractions, improper fractions and whole numbers:<br>(i) 3/7 (ii) 5/8 (iii) 9/7 (iv) 6/5 (v) 12/7 (vi) 1/8 (vii) 1/11</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            (i) Reciprocal of <span class=\"math\">3/7</span> is <span class=\"math\"><strong>7/3</strong></span> ⇒ <strong>Improper fraction</strong>.<br>\r\n            (ii) Reciprocal of <span class=\"math\">5/8</span> is <span class=\"math\"><strong>8/5</strong></span> ⇒ <strong>Improper fraction</strong>.<br>\r\n            (iii) Reciprocal of <span class=\"math\">9/7</span> is <span class=\"math\"><strong>7/9</strong></span> ⇒ <strong>Proper fraction</strong>.<br>\r\n            (iv) Reciprocal of <span class=\"math\">6/5</span> is <span class=\"math\"><strong>5/6</strong></span> ⇒ <strong>Proper fraction</strong>.<br>\r\n            (v) Reciprocal of <span class=\"math\">12/7</span> is <span class=\"math\"><strong>7/12</strong></span> ⇒ <strong>Proper fraction</strong>.<br>\r\n            (vi) Reciprocal of <span class=\"math\">1/8</span> is <span class=\"math\">8/1 = <strong>8</strong></span> ⇒ <strong>Whole number</strong>.<br>\r\n            (vii) Reciprocal of <span class=\"math\">1/11</span> is <span class=\"math\">11/1 = <strong>11</strong></span> ⇒ <strong>Whole number</strong>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Reciprocal values correctly found</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate classification (Proper / Improper / Whole)</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q2_3_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_3_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Find: (i) 7/3 ÷ 2, (ii) 4/9 ÷ 5, (iii) 4⅓ ÷ 3, (iv) 2/5 ÷ 1/2, (v) 3½ ÷ 8/7, (vi) 2⅕ ÷ 1⅕.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">7/3 ÷ 2 = 7/3 × 1/2 = <strong>7/6</strong> = <strong>1 1/6</strong></span></strong><br>\r\n            <strong>(ii) <span class=\"math\">4/9 ÷ 5 = 4/9 × 1/5 = <strong>4/45</strong></span></strong><br>\r\n            <strong>(iii) <span class=\"math\">4 1/3 ÷ 3 = 13/3 × 1/3 = <strong>13/9</strong> = <strong>1 4/9</strong></span></strong><br>\r\n            <strong>(iv) <span class=\"math\">2/5 ÷ 1/2 = 2/5 × 2/1 = <strong>4/5</strong></span></strong><br>\r\n            <strong>(v) <span class=\"math\">3 1/2 ÷ 8/7 = 7/2 × 7/8 = <strong>49/16</strong> = <strong>3 1/16</strong></span></strong><br>\r\n            <strong>(vi) <span class=\"math\">2 1/5 ÷ 1 1/5 = 11/5 ÷ 6/5 = 11/5 × 5/6 = <strong>11/6</strong> = <strong>1 5/6</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Reciprocal multiplication rule application</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate simplified fraction values</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 2.4 & 2.5 -->\r\n  <div class=\"ex-div\">Exercise 2.4 &amp; 2.5 (Decimals Operations)</div>\r\n\r\n  <div class=\"q-card\" id=\"q2_4_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_4_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Find the product:<br>(i) 0.2 × 6<br>(ii) 8 × 4.6<br>(iii) 2.71 × 5<br>(iv) 20.1 × 4<br>(v) 0.05 × 7<br>(vi) 211.02 × 4<br>(vii) 2 × 0.86</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">0.2 × 6 = <strong>1.2</strong></span></strong><br>\r\n            <strong>(ii) <span class=\"math\">8 × 4.6 = <strong>36.8</strong></span></strong><br>\r\n            <strong>(iii) <span class=\"math\">2.71 × 5 = <strong>13.55</strong></span></strong><br>\r\n            <strong>(iv) <span class=\"math\">20.1 × 4 = <strong>80.4</strong></span></strong><br>\r\n            <strong>(v) <span class=\"math\">0.05 × 7 = <strong>0.35</strong></span></strong><br>\r\n            <strong>(vi) <span class=\"math\">211.02 × 4 = <strong>844.08</strong></span></strong><br>\r\n            <strong>(vii) <span class=\"math\">2 × 0.86 = <strong>1.72</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Count of decimal places correctly maintained</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate multiplication arithmetic</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q2_5_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q2_5_1')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Find:<br>(a) 7.75 ÷ 0.25<br>(b) 76.5 ÷ 0.15<br>(c) 37.8 ÷ 1.4<br>(d) 2.7 ÷ 100<br>(e) 0.5 ÷ 1000<br>(f) 7 ÷ 3.5</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) <span class=\"math\">7.75 ÷ 0.25 = 775/25 = <strong>31</strong></span></strong><br>\r\n            <strong>(b) <span class=\"math\">76.5 ÷ 0.15 = 7650/15 = <strong>510</strong></span></strong><br>\r\n            <strong>(c) <span class=\"math\">37.8 ÷ 1.4 = 378/14 = <strong>27</strong></span></strong><br>\r\n            <strong>(d) <span class=\"math\">2.7 ÷ 100 = <strong>0.027</strong></span></strong> &nbsp;<em>[Shift decimal 2 places left]</em><br>\r\n            <strong>(e) <span class=\"math\">0.5 ÷ 1000 = <strong>0.0005</strong></span></strong> &nbsp;<em>[Shift decimal 3 places left]</em><br>\r\n            <strong>(f) <span class=\"math\">7 ÷ 3.5 = 70/35 = <strong>2</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with step</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n    <div class=\"q-card\" id=\"q2_1_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_1_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Multiply and reduce to lowest form and convert into a mixed fraction:<br>(i) 7 × 3/5 &nbsp;&nbsp; (ii) 4 × 1/3 &nbsp;&nbsp; (iii) 2 × 6/7 &nbsp;&nbsp; (iv) 5 × 2/9 &nbsp;&nbsp; (v) 2/3 × 4<br>(vi) 5/2 × 6 &nbsp;&nbsp; (vii) 11 × 4/7 &nbsp;&nbsp; (viii) 20 × 4/5 &nbsp;&nbsp; (ix) 13 × 1/3 &nbsp;&nbsp; (x) 15 × 3/5</div>\n      <div class=\"q-marks\">5 Marks (1/2 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> <span class=\"math\">7 × 3/5 = 21/5 = <strong>4 1/5</strong></span><br>\n            <strong>(ii)</strong> <span class=\"math\">4 × 1/3 = 4/3 = <strong>1 1/3</strong></span><br>\n            <strong>(iii)</strong> <span class=\"math\">2 × 6/7 = 12/7 = <strong>1 5/7</strong></span><br>\n            <strong>(iv)</strong> <span class=\"math\">5 × 2/9 = 10/9 = <strong>1 1/9</strong></span><br>\n            <strong>(v)</strong> <span class=\"math\">2/3 × 4 = 8/3 = <strong>2 2/3</strong></span><br>\n            <strong>(vi)</strong> <span class=\"math\">5/2 × 6 = 30/2 = <strong>15</strong></span><br>\n            <strong>(vii)</strong> <span class=\"math\">11 × 4/7 = 44/7 = <strong>6 2/7</strong></span><br>\n            <strong>(viii)</strong> <span class=\"math\">20 × 4/5 = 4 × 4 = <strong>16</strong></span><br>\n            <strong>(ix)</strong> <span class=\"math\">13 × 1/3 = 13/3 = <strong>4 1/3</strong></span><br>\n            <strong>(x)</strong> <span class=\"math\">15 × 3/5 = 3 × 3 = <strong>9</strong></span>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct multiplication and conversion to mixed fraction/integer</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Find:<br>(a) 1/2 of (i) 24 (ii) 46<br>(b) 2/3 of (i) 18 (ii) 27<br>(c) 3/4 of (i) 16 (ii) 36<br>(d) 4/5 of (i) 20 (ii) 35</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a)</strong> (i) <span class=\"math\">1/2 × 24 = <strong>12</strong></span>, (ii) <span class=\"math\">1/2 × 46 = <strong>23</strong></span><br>\n            <strong>(b)</strong> (i) <span class=\"math\">2/3 × 18 = 2 × 6 = <strong>12</strong></span>, (ii) <span class=\"math\">2/3 × 27 = 2 × 9 = <strong>18</strong></span><br>\n            <strong>(c)</strong> (i) <span class=\"math\">3/4 × 16 = 3 × 4 = <strong>12</strong></span>, (ii) <span class=\"math\">3/4 × 36 = 3 × 9 = <strong>27</strong></span><br>\n            <strong>(d)</strong> (i) <span class=\"math\">4/5 × 20 = 4 × 4 = <strong>16</strong></span>, (ii) <span class=\"math\">4/5 × 35 = 4 × 7 = <strong>28</strong></span>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with simplified product</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_1_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_1_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Multiply and express as a mixed fraction:<br>(a) 3 × 5 1/5 &nbsp;&nbsp; (b) 5 × 6 3/4 &nbsp;&nbsp; (c) 7 × 2 1/4 &nbsp;&nbsp; (d) 4 × 6 1/3 &nbsp;&nbsp; (e) 3 1/4 × 6 &nbsp;&nbsp; (f) 3 2/5 × 8</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a)</strong> <span class=\"math\">3 × 26/5 = 78/5 = <strong>15 3/5</strong></span><br>\n            <strong>(b)</strong> <span class=\"math\">5 × 27/4 = 135/4 = <strong>33 3/4</strong></span><br>\n            <strong>(c)</strong> <span class=\"math\">7 × 9/4 = 63/4 = <strong>15 3/4</strong></span><br>\n            <strong>(d)</strong> <span class=\"math\">4 × 19/3 = 76/3 = <strong>25 1/3</strong></span><br>\n            <strong>(e)</strong> <span class=\"math\">13/4 × 6 = 39/2 = <strong>19 1/2</strong></span><br>\n            <strong>(f)</strong> <span class=\"math\">17/5 × 8 = 136/5 = <strong>27 1/5</strong></span>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct improper fraction and final mixed fraction</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_1_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_1_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Find:<br>(a) 1/2 of (i) 2 3/4 (ii) 4 2/9<br>(b) 5/8 of (i) 3 5/6 (ii) 9 2/3</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) (i)</strong> <span class=\"math\">1/2 × 11/4 = 11/8 = <strong>1 3/8</strong></span><br>\n            <strong>(a) (ii)</strong> <span class=\"math\">1/2 × 38/9 = 19/9 = <strong>2 1/9</strong></span><br>\n            <strong>(b) (i)</strong> <span class=\"math\">5/8 × 23/6 = 115/48 = <strong>2 19/48</strong></span><br>\n            <strong>(b) (ii)</strong> <span class=\"math\">5/8 × 29/3 = 145/24 = <strong>6 1/24</strong></span>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each conversion and reduced mixed fraction</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_1_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_1_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">Vidya and Pratap went for a picnic. Their mother gave them a water bottle that contained 5 litres of water. Vidya consumed 2/5 of the water. Pratap consumed the remaining water.<br>(i) How much water did Vidya drink?<br>(ii) What fraction of the total quantity of water did Pratap drink?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Total quantity of water in the bottle = 5 litres.<br>\n            <strong>(i) Water consumed by Vidya:</strong><br>\n            <span class=\"math\">2/5 of 5 litres = (2/5) × 5 = <strong>2 litres</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) Fraction of water consumed by Pratap:</strong><br>\n            Remaining fraction = <span class=\"math\">1 − 2/5 = <strong>3/5</strong></span>.<br>\n            <em>(In volume: 5 litres − 2 litres = 3 litres, which is 3/5 of 5 litres).</em>\n          </div>\n          <p><strong>Final Answer:</strong> Vidya drank <strong>2 litres</strong> of water, and Pratap drank <strong>3/5</strong> of the total quantity of water.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): Calculating 2/5 × 5 = 2 litres</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): Calculating 1 − 2/5 = 3/5</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_2_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_2_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Find:<br>(i) 2/5 ÷ 1/2 &nbsp;&nbsp; (ii) 4/9 ÷ 2/3 &nbsp;&nbsp; (iii) 3/7 ÷ 8/7 &nbsp;&nbsp; (iv) 2 1/3 ÷ 3/5<br>(v) 3 1/2 ÷ 8/3 &nbsp;&nbsp; (vi) 2/5 ÷ 1 1/2 &nbsp;&nbsp; (vii) 3 1/5 ÷ 1 2/3 &nbsp;&nbsp; (viii) 2 1/5 ÷ 1 1/5</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> <span class=\"math\">2/5 × 2/1 = <strong>4/5</strong></span><br>\n            <strong>(ii)</strong> <span class=\"math\">4/9 × 3/2 = 12/18 = <strong>2/3</strong></span><br>\n            <strong>(iii)</strong> <span class=\"math\">3/7 × 7/8 = <strong>3/8</strong></span><br>\n            <strong>(iv)</strong> <span class=\"math\">7/3 × 5/3 = 35/9 = <strong>3 8/9</strong></span><br>\n            <strong>(v)</strong> <span class=\"math\">7/2 × 3/8 = 21/16 = <strong>1 5/16</strong></span><br>\n            <strong>(vi)</strong> <span class=\"math\">2/5 ÷ 3/2 = 2/5 × 2/3 = <strong>4/15</strong></span><br>\n            <strong>(vii)</strong> <span class=\"math\">16/5 ÷ 5/3 = 16/5 × 3/5 = 48/25 = <strong>1 23/25</strong></span><br>\n            <strong>(viii)</strong> <span class=\"math\">11/5 ÷ 6/5 = 11/5 × 5/6 = <strong>11/6 = 1 5/6</strong></span>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with accurate reciprocal and simplification</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_3_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_3_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">A two-wheeler covers a distance of 55.3 km in 1 litre of petrol. How much distance will it cover in 10 litres of petrol?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Distance covered in 1 litre of petrol = 55.3 km.<br>\n            Distance covered in 10 litres of petrol = <span class=\"math\">55.3 × 10 = <strong>553.0 km = 553 km</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The two-wheeler will cover <strong>553 km</strong> in 10 litres of petrol.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Statement and multiplication formulation: 55.3 × 10</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct answer: 553 km with unit</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_4_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_4_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">A vehicle covers a distance of 43.2 km in 2.4 litres of petrol. How much distance will it cover in one litre of petrol?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Total distance covered = 43.2 km.<br>\n            Quantity of petrol consumed = 2.4 litres.<br>\n            Distance covered in 1 litre = <span class=\"math\">43.2 ÷ 2.4 = 432 / 24 = <strong>18 km</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The vehicle will cover <strong>18 km</strong> in 1 litre of petrol.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formulating division: 43.2 ÷ 2.4 = 432/24</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct evaluation: 18 km with units</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_4_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_4_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Find:<br>(i) 7 ÷ 3.5 &nbsp;&nbsp; (ii) 36 ÷ 0.2 &nbsp;&nbsp; (iii) 3.25 ÷ 0.5 &nbsp;&nbsp; (iv) 30.94 ÷ 0.7<br>(v) 0.5 ÷ 0.25 &nbsp;&nbsp; (vi) 7.75 ÷ 0.25 &nbsp;&nbsp; (vii) 76.5 ÷ 0.15 &nbsp;&nbsp; (viii) 37.8 ÷ 1.4 &nbsp;&nbsp; (ix) 2.73 ÷ 1.3</div>\n      <div class=\"q-marks\">4.5 Marks (1/2 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> <span class=\"math\">7 ÷ 3.5 = 70 / 35 = <strong>2</strong></span><br>\n            <strong>(ii)</strong> <span class=\"math\">36 ÷ 0.2 = 360 / 2 = <strong>180</strong></span><br>\n            <strong>(iii)</strong> <span class=\"math\">3.25 ÷ 0.5 = 32.5 / 5 = <strong>6.5</strong></span><br>\n            <strong>(iv)</strong> <span class=\"math\">30.94 ÷ 0.7 = 309.4 / 7 = <strong>44.2</strong></span><br>\n            <strong>(v)</strong> <span class=\"math\">0.5 ÷ 0.25 = 50 / 25 = <strong>2</strong></span><br>\n            <strong>(vi)</strong> <span class=\"math\">7.75 ÷ 0.25 = 775 / 25 = <strong>31</strong></span><br>\n            <strong>(vii)</strong> <span class=\"math\">76.5 ÷ 0.15 = 7650 / 15 = <strong>510</strong></span><br>\n            <strong>(viii)</strong> <span class=\"math\">37.8 ÷ 1.4 = 378 / 14 = <strong>27</strong></span><br>\n            <strong>(ix)</strong> <span class=\"math\">2.73 ÷ 1.3 = 27.3 / 13 = <strong>2.1</strong></span>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Shift decimal places correctly and divide</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n    <div class=\"q-card\" id=\"q2_1_4_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_1_4_def')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">A rectangular sheet of paper is 12 ½ cm long and 10 ⅔ cm wide. Find its perimeter.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Length of the sheet (<span class=\"math\">l</span>) = <span class=\"math\">12 \\frac{1}{2}\\text{ cm} = \\frac{25}{2}\\text{ cm}</span>.<br>\n            Breadth of the sheet (<span class=\"math\">b</span>) = <span class=\"math\">10 \\frac{2}{3}\\text{ cm} = \\frac{32}{3}\\text{ cm}</span>.<br><br>\n            Perimeter of a rectangle = <span class=\"math\">2(l + b)</span><br>\n            <span class=\"math\">= 2 × \\left(\\frac{25}{2} + \\frac{32}{3}\\right)</span><br>\n            LCM of 2 and 3 is 6.<br>\n            <span class=\"math\">= 2 × \\left(\\frac{25 × 3 + 32 × 2}{6}\\right) = 2 × \\left(\\frac{75 + 64}{6}\\right) = 2 × \\frac{139}{6} = \\frac{139}{3} = <strong>46 \\frac{1}{3}\\text{ cm}</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula 2(l + b) and conversion to improper fractions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">LCM and fraction addition</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final perimeter 46 1/3 cm (or 139/3 cm)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_1_5_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_1_5_def')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Find the perimeters of (i) ΔABE with sides 5/2 cm, 3 3/5 cm, 2 3/4 cm (ii) the rectangle BCDE in this figure with sides 2 3/4 cm and 7/6 cm. Whose perimeter is greater?</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) Perimeter of ΔABE:</strong><br>\n            <span class=\"math\">AB = 5/2\\text{ cm}, BE = 2 \\frac{3}{4} = \\frac{11}{4}\\text{ cm}, AE = 3 \\frac{3}{5} = \\frac{18}{5}\\text{ cm}</span>.<br>\n            Perimeter = <span class=\"math\">\\frac{5}{2} + \\frac{11}{4} + \\frac{18}{5}</span>. LCM(2, 4, 5) = 20.<br>\n            <span class=\"math\">= \\frac{50 + 55 + 72}{20} = \\frac{177}{20} = <strong>8 \\frac{17}{20}\\text{ cm} = 8.85\\text{ cm}</strong></span>.<br><br>\n            <strong>(ii) Perimeter of rectangle BCDE:</strong><br>\n            Length = <span class=\"math\">11/4\\text{ cm}</span>, Breadth = <span class=\"math\">7/6\\text{ cm}</span>.<br>\n            Perimeter = <span class=\"math\">2 × \\left(\\frac{11}{4} + \\frac{7}{6}\\right) = 2 × \\left(\\frac{33 + 14}{12}\\right) = 2 × \\frac{47}{12} = \\frac{47}{6} = <strong>7 \\frac{5}{6}\\text{ cm} ≈ 7.83\\text{ cm}</strong></span>.<br><br>\n            <strong>Comparison:</strong> Since <span class=\"math\">8.85 > 7.83</span>, <strong>the perimeter of ΔABE is greater</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Perimeter of triangle calculation (177/20 cm)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Perimeter of rectangle calculation (47/6 cm)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Comparison and deduction</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_3_8_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_3_8_def')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">(a) (i) Provide the number in the box [ ], such that 2/3 × [ ] = 10/30. (ii) The simplest form of the number obtained in [ ] is _____.<br>(b) (i) Provide the number in the box [ ], such that 3/5 × [ ] = 24/75. (ii) The simplest form of the number obtained in [ ] is _____.</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a)</strong><br>\n            (i) <span class=\"math\">\\frac{2}{3} × \\left[\\frac{5}{10}\\right] = \\frac{10}{30}</span>. So the number in [ ] is <strong>5/10</strong>.<br>\n            (ii) The simplest form of <span class=\"math\">\\frac{5}{10}</span> is <strong>1/2</strong>.<br><br>\n            <strong>(b)</strong><br>\n            (i) <span class=\"math\">\\frac{3}{5} × \\left[\\frac{8}{15}\\right] = \\frac{24}{75}</span>. So the number in [ ] is <strong>8/15</strong>.<br>\n            (ii) The simplest form of <span class=\"math\">\\frac{8}{15}</span> is <strong>8/15</strong> (coprime numbers, already in simplest form).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct fraction in box for (a)(i) and (b)(i)</span><span class=\"marking-marks\">1 Mark each</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Simplest form for (a)(ii) and (b)(ii)</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\">\r\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\r\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\r\n    </div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">Case Study: Uniform Tailoring</div>\r\n        <div class=\"cbq-question\"><strong>Scenario:</strong> A school needs 1.8 metres of cloth to stitch one uniform shirt. A roll of fabric contains 45 metres of cloth. (i) How many complete shirts can be tailored from this roll? (ii) What length of fabric will be left? (iii) If each shirt requires 6 buttons, how many buttons will be needed in total?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <p><strong>(i) Number of shirts:</strong><br>\r\n          <span class=\"math\">Number of shirts = (Total cloth)/(Cloth per shirt) = 45 ÷ 1.8 = 450/18 = <strong>25 complete shirts</strong></span>.</p>\r\n          <p><strong>(ii) Leftover fabric:</strong><br>\r\n          Total used = <span class=\"math\">25 × 1.8 = 45 m</span>. Leftover = <span class=\"math\">45 − 45 = <strong>0 metres</strong></span>.</p>\r\n          <p><strong>(iii) Total buttons needed:</strong><br>\r\n          <span class=\"math\">25 × 6 = <strong>150 buttons</strong></span>.</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#10b981;\">⚡ HOTS Question</div>\r\n        <div class=\"cbq-question\">Each side of a regular polygon is 2.5 cm in length. The perimeter of the polygon is 12.5 cm. How many sides does the polygon have?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <p>Let number of sides be <span class=\"math\">n</span>.<br>\r\n          In a regular polygon, all sides are equal. Perimeter = <span class=\"math\">n × side</span>.<br>\r\n          <span class=\"math\">n × 2.5 = 12.5 ⇒ n = 12.5/2.5 = 125/25 = <strong>5</strong></span>.<br>\r\n          Therefore, the polygon has <strong>5 sides</strong> (it is a regular pentagon).</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(1)\">← Chapter 1: Integers</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(3)\">Chapter 3: Data Handling →</button>\r\n  </div>\r\n</section>\r\n","3":"<section class=\"chapter-section\" id=\"ch3\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">3</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 3: Data Handling</h2>\r\n      <p>NCERT Exercise 3.1 to 3.4 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"concept-card\">\r\n    <div class=\"concept-header\">📌 Key Concepts &amp; Formulas Summary</div>\r\n    <ul class=\"concept-list\">\r\n      <li><strong>Data &amp; Range:</strong>\r\n        Range = Highest Value - Lowest Value\r\n      </li>\r\n      <li><strong>Arithmetic Mean (Average):</strong>\r\n        Mean = (Sum of all observations)/(Number of observations)\r\n      </li>\r\n      <li><strong>Mode:</strong> The observation that occurs most frequently in the given data. A data set can have more than one mode (multimodal).</li>\r\n      <li><strong>Median:</strong> The middle observation when data is arranged in ascending or descending order.\r\n        <ul>\r\n          <li>For odd n: Median = ((n+1)/2)th observation.</li>\r\n        </ul>\r\n      </li>\r\n      <li><strong>Bar Graphs:</strong> Representation of numbers using bars of uniform width where lengths/heights are proportional to the frequencies. Double bar graphs compare two sets of data simultaneously.</li>\r\n      <li><strong>Probability (P):</strong> Measure of chance of an event happening:\r\n        P(Event) = (Number of favourable outcomes)/(Total number of possible outcomes)\r\n        0 ≤ P ≤ 1. Impossible event = 0, Certain event = 1.\r\n      </li>\r\n    </ul>\r\n  </div>\r\n\r\n  <!-- EXERCISE 3.1 -->\r\n  <div class=\"ex-div\">Exercise 3.1</div>\r\n\r\n  <div class=\"q-card\" id=\"q3_1_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_1_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Find the range of heights of any ten students of your class.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Sample Data (Heights in cm):</strong><br>\r\n            Let the heights of 10 students be: <span class=\"math\">128, 132, 135, 139, 140, 142, 145, 148, 150, 152 cm</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Calculation of Range:</strong><br>\r\n            Highest height = <span class=\"math\">152 cm</span><br>\r\n            Lowest height = <span class=\"math\">128 cm</span><br>\r\n            <span class=\"math\">Range = Highest height − Lowest height = 152 − 128 = <strong>24 cm</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing observations &amp; identifying max/min values</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying Range formula and correct result</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q3_1_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_1_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Find the mean of the first five whole numbers.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Identify whole numbers:</strong><br>\r\n            The first five whole numbers are: <span class=\"math\">0, 1, 2, 3, 4</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Calculate sum and mean:</strong><br>\r\n            Sum = <span class=\"math\">0 + 1 + 2 + 3 + 4 = 10</span>.<br>\r\n            Number of observations = <span class=\"math\">5</span>.<br>\r\n            <span class=\"math\">Mean = (Sum of observations)/(Number of observations) = 10/5 = <strong>2</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> The mean of the first five whole numbers is <strong>2</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing correct numbers starting from 0</span><span class=\"marking-marks\">0.5 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mean formula &amp; final answer 2</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q3_1_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_1_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">A cricketer scores the following runs in eight innings: 58, 76, 40, 35, 46, 45, 0, 100. Find the mean score.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Sum of runs:</strong><br>\r\n            <span class=\"math\">Total runs = 58 + 76 + 40 + 35 + 46 + 45 + 0 + 100 = <strong>400</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Number of innings:</strong><br>\r\n            <span class=\"math\">n = 8</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 3: Mean score:</strong><br>\r\n            <span class=\"math\">Mean = (Total runs)/(Number of innings) = 400/8 = <strong>50</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> The mean score of the cricketer is <strong>50 runs</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Sum of observations = 400</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Mean = 400/8 = 50 runs</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 3.2 -->\r\n  <div class=\"ex-div\">Exercise 3.2</div>\r\n\r\n  <div class=\"q-card\" id=\"q3_2_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_2_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">The scores in mathematics test (out of 25) of 15 students is as follows: 19, 25, 23, 20, 9, 20, 15, 10, 5, 16, 25, 20, 24, 12, 20. Find the mode and median of this data. Are they same?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Arrange data in ascending order:</strong><br>\r\n            <span class=\"math\">5, 9, 10, 12, 15, 16, 19, <strong>20</strong>, 20, 20, 20, 23, 24, 25, 25</span>.<br>\r\n            Total students, <span class=\"math\">n = 15</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Find Mode:</strong><br>\r\n            The score 20 occurs 4 times (highest frequency).<br>\r\n            Therefore, <strong>Mode = 20</strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 3: Find Median:</strong><br>\r\n            Since <span class=\"math\">n = 15</span> is odd:<br>\r\n            <span class=\"math\">Median = ((15+1)/2)th observation = 8th observation = <strong>20</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Conclusion:</strong><br>\r\n            <strong>Yes</strong>, the mode and median are the same (both equal 20).\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Ascending order + Mode = 20</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Median = 8th value = 20</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Affirmative conclusion stating both are equal</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q3_2_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_2_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">The weights (in kg) of 15 students of a class are: 38, 42, 35, 37, 45, 50, 32, 43, 43, 40, 36, 38, 43, 38, 47.<br>(i) Find the mode and median of this data.<br>(ii) Is there more than one mode?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Arranging in ascending order:</strong><br>\r\n            <span class=\"math\">32, 35, 36, 37, 38, 38, 38, <strong>40</strong>, 42, 43, 43, 43, 45, 47, 50</span>.<br>\r\n            Total number of observations, <span class=\"math\">n = 15</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(i) Mode and Median:</strong><br>\r\n            • Both <strong>38</strong> and <strong>43</strong> occur 3 times each (highest frequency).<br>\r\n            Therefore, <strong>Modes = 38 kg and 43 kg</strong> (bimodal).<br>\r\n            • <span class=\"math\">Median = ((15+1)/2)th observation = 8th observation = <strong>40 kg</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) Is there more than one mode?</strong><br>\r\n            <strong>Yes</strong>, there are two modes (38 kg and 43 kg).\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Modes: 38 and 43 kg</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Median: 40 kg</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Yes, with two modes mentioned</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 3.3 & 3.4 -->\r\n  <div class=\"ex-div\">Exercise 3.3 &amp; 3.4 (Graphs &amp; Probability)</div>\r\n\r\n  <div class=\"q-card\" id=\"q3_3_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_3_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Consider this data collected from a survey of a colony:<br>Cricket (Watch: 1240, Participate: 620), Basketball (Watch: 470, Participate: 320), Swimming (Watch: 510, Participate: 320), Hockey (Watch: 430, Participate: 250), Athletics (Watch: 250, Participate: 105).<br>(i) Which sport is most popular?<br>(ii) Which is more preferred, watching or participating in sports?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) Most popular sport:</strong><br>\r\n            Total people interested in Cricket = <span class=\"math\">1240 + 620 = 1860</span>.<br>\r\n            Cricket has the highest bar for both watching and participating.<br>\r\n            <strong>Answer: Cricket is the most popular sport.</strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) Watching vs. Participating preference:</strong><br>\r\n            Total watching = <span class=\"math\">1240 + 470 + 510 + 430 + 250 = <strong>2900</strong></span>.<br>\r\n            Total participating = <span class=\"math\">620 + 320 + 320 + 250 + 105 = <strong>1615</strong></span>.<br>\r\n            Since <span class=\"math\">2900 > 1615</span>, <strong>watching sports is preferred more</strong> than participating.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): Identifying Cricket with total count</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): Calculating totals (2900 vs 1615) &amp; conclusion</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q3_4_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q3_4_1')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">There are 6 marbles in a box with numbers from 1 to 6 marked on each of them.<br>(i) What is the probability of drawing a marble with number 2?<br>(ii) What is the probability of drawing a marble with number 5?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Sample Space:</strong><br>\r\n            Total number of marbles = <span class=\"math\">{1, 2, 3, 4, 5, 6} ⇒ n(S) = 6</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(i) Probability of drawing marble number 2:</strong><br>\r\n            Number 2 appears on only 1 marble ⇒ n(E) = 1.<br>\r\n            <span class=\"math\">P(Number 2) = n(E)/n(S) = <strong>1/6</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) Probability of drawing marble number 5:</strong><br>\r\n            Number 5 appears on only 1 marble ⇒ n(E) = 1.<br>\r\n            <span class=\"math\">P(Number 5) = n(E)/n(S) = <strong>1/6</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula P = Favourable / Total outcomes</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Answers 1/6 for both parts</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n    <div class=\"q-card\" id=\"q3_1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">A cricketer scores the following runs in eight innings: 58, 76, 40, 35, 46, 45, 0, 100. Find the mean score.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Total number of innings = 8.<br>\n            Total runs scored = <span class=\"math\">58 + 76 + 40 + 35 + 46 + 45 + 0 + 100 = <strong>400</strong></span>.<br>\n            <span class=\"math\">Mean score = Total runs / Number of innings = 400 / 8 = <strong>50 runs</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The mean score of the cricketer is <strong>50 runs</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sum of runs = 400</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mean = 400/8 = 50 with units</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_1_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_1_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">The marks (out of 100) obtained by a group of students in a science test are 85, 76, 90, 85, 39, 48, 56, 95, 81 and 75. Find the:<br>(i) Highest and the lowest marks obtained by the students.<br>(ii) Range of the marks obtained.<br>(iii) Mean marks obtained by the group.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Arranging marks in ascending order: 39, 48, 56, 75, 76, 81, 85, 85, 90, 95.<br>\n            <strong>(i)</strong> Highest marks = <strong>95</strong>; Lowest marks = <strong>39</strong>.<br>\n            <strong>(ii)</strong> Range = <span class=\"math\">95 − 39 = <strong>56</strong></span>.<br>\n            <strong>(iii)</strong> Mean marks = <span class=\"math\">(39 + 48 + 56 + 75 + 76 + 81 + 85 + 85 + 90 + 95) / 10 = 730 / 10 = <strong>73</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> (i) Highest: 95, Lowest: 39; (ii) Range: 56; (iii) Mean: <strong>73</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): Highest = 95, Lowest = 39</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): Range = 56</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (iii): Mean = 730/10 = 73</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_1_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_1_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">The enrolment in a school during six consecutive years was as follows: 1555, 1670, 1750, 2013, 2540, 2820. Find the mean enrolment of the school for this period.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Total enrolment over 6 years = <span class=\"math\">1555 + 1670 + 1750 + 2013 + 2540 + 2820 = <strong>12348</strong></span>.<br>\n            Number of years = 6.<br>\n            <span class=\"math\">Mean enrolment = 12348 / 6 = <strong>2058</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The mean enrolment of the school for this period is <strong>2058</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sum of enrolments = 12348</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mean = 12348/6 = 2058</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_1_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_1_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">The heights of 10 girls were measured in cm and the results are as follows: 135, 150, 139, 128, 151, 132, 146, 149, 143, 141.<br>(i) What is the height of the tallest girl?<br>(ii) What is the height of the shortest girl?<br>(iii) What is the range of the data?<br>(iv) What is the mean height of the girls?<br>(v) How many girls have heights more than the mean height?</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Arranging heights in ascending order: 128, 132, 135, 139, 141, 143, 146, 149, 150, 151 cm.<br>\n            <strong>(i) Height of tallest girl:</strong> <span class=\"math\"><strong>151 cm</strong></span>.<br>\n            <strong>(ii) Height of shortest girl:</strong> <span class=\"math\"><strong>128 cm</strong></span>.<br>\n            <strong>(iii) Range:</strong> <span class=\"math\">151 − 128 = <strong>23 cm</strong></span>.<br>\n            <strong>(iv) Mean height:</strong><br>\n            <span class=\"math\">(128 + 132 + 135 + 139 + 141 + 143 + 146 + 149 + 150 + 151) / 10 = 1414 / 10 = <strong>141.4 cm</strong></span>.<br>\n            <strong>(v) Girls with height &gt; 141.4 cm:</strong><br>\n            The heights greater than 141.4 cm are 143, 146, 149, 150, 151 (total <strong>5 girls</strong>).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Parts (i), (ii), (iii): 151 cm, 128 cm, Range = 23 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (iv): Mean = 1414/10 = 141.4 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (v): Count = 5 girls</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_2_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_2_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">The weights (in kg) of 15 students of a class are: 38, 42, 35, 37, 45, 50, 32, 43, 43, 40, 36, 38, 43, 38, 47.<br>(i) Find the mode and median of this data.<br>(ii) Is there more than one mode?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Arranging data in ascending order:<br>\n            32, 35, 36, 37, 38, 38, 38, 40, 42, 43, 43, 43, 45, 47, 50.<br>\n            <strong>(i) Mode:</strong> Both 38 and 43 occur 3 times (highest frequency).<br>\n            <span class=\"math\">Mode = <strong>38 kg</strong> and <strong>43 kg</strong></span> (Bimodal).<br>\n            <strong>Median:</strong> Middle observation out of <span class=\"math\">n = 15</span> is the <span class=\"math\">(15 + 1)/2 = 8</span>th term.<br>\n            8th term = <span class=\"math\"><strong>40 kg</strong></span>.<br>\n            <strong>(ii)</strong> Yes, there are <strong>two modes (38 kg and 43 kg)</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mode = 38 and 43</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Median = 40 kg</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Confirming two modes exist</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_2_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_2_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Tell whether the statement is true or false:<br>(i) The mode is always one of the numbers in a data.<br>(ii) The mean is one of the numbers in a data.<br>(iii) The median is always one of the numbers in a data.<br>(iv) The data 6, 4, 3, 8, 9, 12, 13, 9 has mean 9.</div>\n      <div class=\"q-marks\">2 Marks (1/2 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) True:</strong> Mode is the observation with the highest frequency, so it must be from the data.<br>\n            <strong>(ii) False:</strong> Mean is the average sum/count, which can be a fractional or different value not present in the original dataset.<br>\n            <strong>(iii) True:</strong> For an odd number of observations (as standard in Class 7 definition), median is the middle observation from the dataset.<br>\n            <strong>(iv) False:</strong> Sum = 6 + 4 + 3 + 8 + 9 + 12 + 13 + 9 = 64. Mean = 64 / 8 = <strong>8</strong> (not 9).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct True/False statement with justification</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Following table shows the points of each player scored in four games:<br>Player A: Game 1 (14), Game 2 (16), Game 3 (10), Game 4 (10)<br>Player B: Game 1 (0), Game 2 (8), Game 3 (6), Game 4 (4)<br>Player C: Game 1 (8), Game 2 (11), Game 3 (Did not play), Game 4 (13)<br>(i) Find the mean to determine A's average number of points scored per game.<br>(ii) To find the mean number of points per game for C, would you divide the total points by 3 or by 4? Why?<br>(iii) B played in all the four games. How would you find the mean?<br>(iv) Who is the best performer?</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) Mean points scored by A:</strong><br>\n            <span class=\"math\">Mean of A = (14 + 16 + 10 + 10) / 4 = 50 / 4 = <strong>12.5 points</strong></span>.<br>\n            <strong>(ii) For Player C:</strong><br>\n            We should divide the total points by <strong>3</strong> because player C played only 3 games (did not play Game 3).<br>\n            <span class=\"math\">Mean of C = (8 + 11 + 13) / 3 = 32 / 3 = <strong>10.67 points</strong></span>.<br>\n            <strong>(iii) Mean points scored by B:</strong><br>\n            B played all 4 games: <span class=\"math\">Mean of B = (0 + 8 + 6 + 4) / 4 = 18 / 4 = <strong>4.5 points</strong></span>.<br>\n            <strong>(iv) Best performer:</strong><br>\n            Comparing average scores: A (12.5), C (10.67), B (4.5).<br>\n            Player <strong>A is the best performer</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part answered with calculation and reason</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_1_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_1_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">The rainfall (in mm) in a city on 7 days of a certain week was recorded as: Mon (0.0), Tue (12.2), Wed (2.1), Thu (0.0), Fri (20.5), Sat (5.5), Sun (1.0).<br>(i) Find the range of the rainfall in the above data.<br>(ii) Find the mean rainfall for the week.<br>(iii) On how many days was the rainfall less than the mean rainfall?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) Range of rainfall:</strong><br>\n            Highest rainfall = 20.5 mm; Lowest rainfall = 0.0 mm.<br>\n            <span class=\"math\">Range = 20.5 − 0.0 = <strong>20.5 mm</strong></span>.<br>\n            <strong>(ii) Mean rainfall:</strong><br>\n            Total rainfall = <span class=\"math\">0.0 + 12.2 + 2.1 + 0.0 + 20.5 + 5.5 + 1.0 = 41.3 mm</span>.<br>\n            <span class=\"math\">Mean rainfall = 41.3 / 7 = <strong>5.9 mm</strong></span>.<br>\n            <strong>(iii) Days with rainfall &lt; 5.9 mm:</strong><br>\n            On Monday (0.0), Wednesday (2.1), Thursday (0.0), Saturday (5.5), and Sunday (1.0), rainfall was less than 5.9 mm.<br>\n            Total = <strong>5 days</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): Range = 20.5 mm</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): Mean = 5.9 mm</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (iii): 5 days</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_2_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_2_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Find the mode and median of the data: 13, 16, 12, 14, 19, 12, 14, 13, 14.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Arranging data in ascending order: 12, 12, 13, 13, 14, 14, 14, 16, 19.<br>\n            <strong>Mode:</strong> 14 occurs 3 times (maximum frequency). <span class=\"math\">Mode = <strong>14</strong></span>.<br>\n            <strong>Median:</strong> Total observations <span class=\"math\">n = 9</span>. Middle value is the <span class=\"math\">(9 + 1)/2 = 5</span>th observation.<br>\n            5th observation = <strong>14</strong>.\n          </div>\n          <p><strong>Final Answer:</strong> Both Mode and Median are <strong>14</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mode = 14</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Median = 14</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_3_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_3_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">The performance of a student in 1st Term and 2nd Term is given: English (67, 70), Hindi (72, 65), Mathematics (88, 95), Science (81, 85), Social Science (73, 75).<br>(i) In which subject has the child improved his performance the most?<br>(ii) In which subject is the improvement the least?<br>(iii) Has the performance gone down in any subject?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Change in performance (2nd Term − 1st Term):<br>\n            • English: <span class=\"math\">70 − 67 = +3</span><br>\n            • Hindi: <span class=\"math\">65 − 72 = −7</span><br>\n            • Mathematics: <span class=\"math\">95 − 88 = +7</span><br>\n            • Science: <span class=\"math\">85 − 81 = +4</span><br>\n            • Social Science: <span class=\"math\">75 − 73 = +2</span><br><br>\n            <strong>(i)</strong> The child improved the most in <strong>Mathematics</strong> (increase of 7 marks).<br>\n            <strong>(ii)</strong> The improvement is least in <strong>Social Science</strong> (increase of only 2 marks).<br>\n            <strong>(iii)</strong> Yes, in <strong>Hindi</strong> the performance has gone down (decreased by 7 marks).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part answered with correct subject and mark difference</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_4_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_4_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">There are 6 marbles in a box with numbers from 1 to 6 marked on each of them.<br>(i) What is the probability of drawing a marble with number 2?<br>(ii) What is the probability of drawing a marble with number 5?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Total number of possible outcomes = 6 (marbles numbered 1, 2, 3, 4, 5, 6).<br>\n            <em>Formula: Probability P(E) = Number of favourable outcomes / Total number of outcomes</em><br>\n            <strong>(i) Probability of drawing marble with number 2:</strong><br>\n            Number of marbles with number 2 = 1.<br>\n            <span class=\"math\">P(drawing 2) = <strong>1 / 6</strong></span>.<br>\n            <strong>(ii) Probability of drawing marble with number 5:</strong><br>\n            Number of marbles with number 5 = 1.<br>\n            <span class=\"math\">P(drawing 5) = <strong>1 / 6</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): P = 1/6</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): P = 1/6</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n    <div class=\"q-card\" id=\"q3_1_3_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_1_3_def')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Find the mean of the first five whole numbers.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            The first five whole numbers are: <strong>0, 1, 2, 3, 4</strong>.<br><br>\n            Formula: <span class=\"math\">\\text{Mean} = \\frac{\\text{Sum of all observations}}{\\text{Total number of observations}}</span><br>\n            <span class=\"math\">= \\frac{0 + 1 + 2 + 3 + 4}{5} = \\frac{10}{5} = <strong>2</strong></span>.<br><br>\n            Hence, the mean of the first five whole numbers is <strong>2</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing first 5 whole numbers (0, 1, 2, 3, 4)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sum / 5 = 10/5 = 2</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_2_1_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_2_1_def')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">The scores in mathematics test (out of 25) of 15 students is as follows: 19, 25, 23, 20, 9, 20, 15, 10, 5, 16, 25, 20, 24, 12, 20. Find the mode and median of this data. Are they same?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Arranging scores in ascending order:<br>\n            <strong>5, 9, 10, 12, 15, 16, 19, 20, 20, 20, 20, 23, 24, 25, 25</strong>.<br><br>\n            1. <strong>Mode:</strong> The observation with highest frequency is <strong>20</strong> (occurs 4 times). Hence, <span class=\"math\">\\text{Mode} = <strong>20</strong></span>.<br>\n            2. <strong>Median:</strong> Total observations <span class=\"math\">n = 15</span> (odd).<br>\n            Median is the <span class=\"math\">\\frac{n+1}{2}^{\\text{th}} = \\frac{15+1}{2} = 8^{\\text{th}}</span> observation.<br>\n            The 8th observation is <strong>20</strong>. Hence, <span class=\"math\">\\text{Median} = <strong>20</strong></span>.<br><br>\n            <strong>Yes, the mode and median are the same (both equal to 20).</strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ascending order arrangement &amp; Mode = 20</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Median calculation = 20</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Comparison conclusion 'Yes, they are same'</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_2_2_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_2_2_def')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">The runs scored in a cricket match by 11 players is as follows: 6, 15, 120, 50, 100, 80, 10, 15, 8, 10, 15. Find the mean, mode and median of this data. Are the three same?</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Arranging data in ascending order:<br>\n            <strong>6, 8, 10, 10, 15, 15, 15, 50, 80, 100, 120</strong>.<br><br>\n            • <strong>Mean:</strong> <span class=\"math\">\\frac{6 + 8 + 10 + 10 + 15 + 15 + 15 + 50 + 80 + 100 + 120}{11} = \\frac{429}{11} = <strong>39</strong></span>.<br>\n            • <strong>Mode:</strong> 15 occurs most frequently (3 times), so <span class=\"math\">\\text{Mode} = <strong>15</strong></span>.<br>\n            • <strong>Median:</strong> Total <span class=\"math\">n = 11</span>. The <span class=\"math\">\\frac{11+1}{2} = 6^{\\text{th}}</span> term is <strong>15</strong>. So <span class=\"math\">\\text{Median} = <strong>15</strong></span>.<br><br>\n            <strong>No, the three are not same</strong> (Mean = 39, Mode = 15, Median = 15).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mean calculation (39)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mode calculation (15) and Median calculation (15)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Comparison conclusion 'No'</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_3_3_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_3_3_def')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Number of children in six different classes are given below: Class Fifth (135), Sixth (120), Seventh (95), Eighth (100), Ninth (90), Tenth (80).<br>(a) How would you choose a scale?<br>(b) Answer the following: (i) Which class has the maximum number of children? And the minimum? (ii) Find the ratio of students of class sixth to the students of class eight.</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Scale:</strong> Since the values range from 80 to 135, an appropriate scale on the vertical axis is <strong>1 unit length = 10 children</strong> (or 20 children).<br><br>\n            <strong>(b) (i) Maximum &amp; Minimum:</strong><br>\n            • Maximum number of children is in <strong>Class Fifth (135 children)</strong>.<br>\n            • Minimum number of children is in <strong>Class Tenth (80 children)</strong>.<br><br>\n            <strong>(ii) Ratio of Class Sixth to Class Eighth:</strong><br>\n            Number in Class 6 = 120, Number in Class 8 = 100.<br>\n            Ratio = <span class=\"math\">\\frac{120}{100} = \\frac{6}{5} = <strong>6 : 5</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Scale selection explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Maximum and minimum classes identification</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Ratio calculation 6 : 5</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\">\r\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\r\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\r\n    </div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">Case Study: Die Roll Outcomes</div>\r\n        <div class=\"cbq-question\"><strong>Problem:</strong> When a standard 6-faced die is thrown once, list the outcomes and find the probability of an event of getting: (i) a prime number, (ii) not a prime number, (iii) a number greater than 5, (iv) a number not greater than 5.</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <p>Total possible outcomes = <span class=\"math\">{1, 2, 3, 4, 5, 6}</span>, total = 6.</p>\r\n          <p><strong>(i) Prime number:</strong> Outcomes are <span class=\"math\">{2, 3, 5}</span> (3 outcomes) ⇒ P = 3/6 = <strong>1/2</strong>.</p>\r\n          <p><strong>(ii) Not a prime number:</strong> Outcomes are <span class=\"math\">{1, 4, 6}</span> (3 outcomes) ⇒ P = 3/6 = <strong>1/2</strong>. (Note: 1 is neither prime nor composite).</p>\r\n          <p><strong>(iii) Number greater than 5:</strong> Only <span class=\"math\">{6}</span> (1 outcome) ⇒ P = <strong>1/6</strong>.</p>\r\n          <p><strong>(iv) Number not greater than 5:</strong> Outcomes <span class=\"math\">{1, 2, 3, 4, 5}</span> (5 outcomes) ⇒ P = <strong>5/6</strong>.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(2)\">← Chapter 2: Fractions &amp; Decimals</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(4)\">Chapter 4: Simple Equations →</button>\r\n  </div>\r\n</section>\r\n","4":"<section class=\"chapter-section\" id=\"ch4\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">4</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 4: Simple Equations</h2>\r\n      <p>NCERT Exercise 4.1 to 4.4 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"concept-card\">\r\n    <div class=\"concept-header\">📌 Key Concepts &amp; Formulas Summary</div>\r\n    <ul class=\"concept-list\">\r\n      <li><strong>Equation:</strong> A mathematical statement showing that two expressions have equal value (LHS = RHS), involving at least one variable.</li>\r\n      <li><strong>Solution of an Equation:</strong> The value of the variable for which the equation is satisfied (LHS = RHS).</li>\r\n      <li><strong>Rules for Balancing Equations:</strong>\r\n        <ul>\r\n          <li>Add or subtract the same number on both sides.</li>\r\n          <li>Multiply or divide both sides by the same non-zero number.</li>\r\n        </ul>\r\n      </li>\r\n      <li><strong>Transposition Method:</strong>\r\n        Moving a term from one side of the equation to the other changes its sign:\r\n        <ul>\r\n          <li>+  becomes  - &nbsp;|&nbsp; -  becomes  +</li>\r\n          <li>×  becomes  ÷ &nbsp;|&nbsp; ÷  becomes  ×</li>\r\n        </ul>\r\n      </li>\r\n    </ul>\r\n  </div>\r\n\r\n  <!-- EXERCISE 4.1 -->\r\n  <div class=\"ex-div\">Exercise 4.1</div>\r\n\r\n  <div class=\"q-card\" id=\"q4_1_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_1_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Check whether the value given in the brackets is a solution to the given equation or not:<br>(a) n + 5 = 19 (n = 1)<br>(b) 7n + 5 = 19 (n = −2)<br>(c) 7n + 5 = 19 (n = 2)<br>(d) 4p − 3 = 13 (p = 1)<br>(e) 4p − 3 = 13 (p = −4)<br>(f) 4p − 3 = 13 (p = 0)</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) n + 5 = 19 for n = 1:</strong><br>\r\n            <span class=\"math\">LHS = 1 + 5 = 6 ≠ 19 (RHS) ⇒</span> <strong>No, not a solution.</strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) 7n + 5 = 19 for n = −2:</strong><br>\r\n            <span class=\"math\">LHS = 7(−2) + 5 = −14 + 5 = −9 ≠ 19 (RHS) ⇒</span> <strong>No, not a solution.</strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) 7n + 5 = 19 for n = 2:</strong><br>\r\n            <span class=\"math\">LHS = 7(2) + 5 = 14 + 5 = 19 = RHS ⇒</span> <strong>Yes, it is a solution.</strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(d) 4p − 3 = 13 for p = 1:</strong><br>\r\n            <span class=\"math\">LHS = 4(1) − 3 = 4 − 3 = 1 ≠ 13 (RHS) ⇒</span> <strong>No, not a solution.</strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(e) 4p − 3 = 13 for p = −4:</strong><br>\r\n            <span class=\"math\">LHS = 4(−4) − 3 = −16 − 3 = −19 ≠ 13 (RHS) ⇒</span> <strong>No, not a solution.</strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(f) 4p − 3 = 13 for p = 0:</strong><br>\r\n            <span class=\"math\">LHS = 4(0) − 3 = −3 ≠ 13 (RHS) ⇒</span> <strong>No, not a solution.</strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">LHS vs RHS evaluated for each part</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q4_1_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_1_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Write equations for the following statements:<br>(i) The sum of numbers x and 4 is 9.<br>(ii) 2 subtracted from y is 8.<br>(iii) Ten times a is 70.<br>(iv) The number b divided by 5 gives 6.<br>(v) Three-fourth of t is 15.<br>(vi) Seven times m plus 7 gets you 77.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">x + 4 = 9</span></strong><br>\r\n            <strong>(ii) <span class=\"math\">y − 2 = 8</span></strong><br>\r\n            <strong>(iii) <span class=\"math\">10a = 70</span></strong><br>\r\n            <strong>(iv) <span class=\"math\">b/5 = 6</span></strong><br>\r\n            <strong>(v) <span class=\"math\">3/4t = 15</span></strong><br>\r\n            <strong>(vi) <span class=\"math\">7m + 7 = 77</span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct algebraic equation translation</span><span class=\"marking-marks\">0.5 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 4.2 & 4.3 -->\r\n  <div class=\"ex-div\">Exercise 4.2 &amp; 4.3 (Solving Equations)</div>\r\n\r\n  <div class=\"q-card\" id=\"q4_2_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_2_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Solve the following equations:<br>(a) 2y + 5/2 = 37/2<br>(b) 5t + 28 = 10<br>(c) a/5 + 3 = 2<br>(d) q/4 + 7 = 5<br>(e) 5/2 x = −10<br>(f) 5/2 x = 25/4</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) <span class=\"math\">2y + 5/2 = 37/2</span>:</strong><br>\r\n            Transpose <span class=\"math\">5/2</span>: <span class=\"math\">2y = 37/2 − 5/2 = 32/2 = 16 ⇒ y = 16/2 = <strong>8</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) <span class=\"math\">5t + 28 = 10</span>:</strong><br>\r\n            <span class=\"math\">5t = 10 − 28 = −18 ⇒ t = <strong>-18/5</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) <span class=\"math\">a/5 + 3 = 2</span>:</strong><br>\r\n            <span class=\"math\">a/5 = 2 − 3 = −1 ⇒ a = −1 × 5 = <strong>−5</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(d) <span class=\"math\">q/4 + 7 = 5</span>:</strong><br>\r\n            <span class=\"math\">q/4 = 5 − 7 = −2 ⇒ q = −2 × 4 = <strong>−8</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(e) <span class=\"math\">5/2x = −10</span>:</strong><br>\r\n            <span class=\"math\">x = −10 × 2/5 = −2 × 2 = <strong>−4</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(f) <span class=\"math\">5/2x = 25/4</span>:</strong><br>\r\n            <span class=\"math\">x = 25/4 × 2/5 = 5/2 = <strong>2 1/2</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct step-by-step solution</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q4_3_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_3_1')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Solve the following equations with brackets:<br>(a) 2(x + 4) = 12<br>(b) 3(n − 5) = 21<br>(c) 3(n − 5) = −21<br>(d) −4(2 + x) = 8<br>(e) 4(2 − x) = 8</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) <span class=\"math\">2(x + 4) = 12</span>:</strong><br>\r\n            Divide both sides by 2: <span class=\"math\">x + 4 = 6 ⇒ x = 6 − 4 = <strong>2</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) <span class=\"math\">3(n − 5) = 21</span>:</strong><br>\r\n            Divide both sides by 3: <span class=\"math\">n − 5 = 7 ⇒ n = 7 + 5 = <strong>12</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) <span class=\"math\">3(n − 5) = −21</span>:</strong><br>\r\n            Divide both sides by 3: <span class=\"math\">n − 5 = −7 ⇒ n = −7 + 5 = <strong>−2</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(d) <span class=\"math\">−4(2 + x) = 8</span>:</strong><br>\r\n            Divide by −4: <span class=\"math\">2 + x = 8/(−4) = −2 ⇒ x = −2 − 2 = <strong>−4</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(e) <span class=\"math\">4(2 − x) = 8</span>:</strong><br>\r\n            Divide by 4: <span class=\"math\">2 − x = 2 ⇒ −x = 2 − 2 = 0 ⇒ <strong>x = 0</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Bracket expansion/division step &amp; solution</span><span class=\"marking-marks\">0.6 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 4.4 -->\r\n  <div class=\"ex-div\">Exercise 4.4 (Applications &amp; Word Problems)</div>\r\n\r\n  <div class=\"q-card\" id=\"q4_4_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_4_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Set up equations and solve them to find the unknown numbers:<br>(a) Add 4 to eight times a number; you get 60.<br>(b) One-fifth of a number minus 4 gives 3.<br>(c) If I take three-fourths of a number and add 3 to it, I get 21.<br>(d) When I subtracted 11 from twice a number, the result was 15.</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a)</strong> Let the number be <span class=\"math\">x</span>.<br>\r\n            Equation: <span class=\"math\">8x + 4 = 60 ⇒ 8x = 60 − 4 = 56 ⇒ x = 56/8 = <strong>7</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b)</strong> Let the number be <span class=\"math\">y</span>.<br>\r\n            Equation: <span class=\"math\">y/5 − 4 = 3 ⇒ y/5 = 7 ⇒ y = 7 × 5 = <strong>35</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c)</strong> Let the number be <span class=\"math\">z</span>.<br>\r\n            Equation: <span class=\"math\">3/4z + 3 = 21 ⇒ 3/4z = 18 ⇒ z = 18 × 4/3 = 6 × 4 = <strong>24</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(d)</strong> Let the number be <span class=\"math\">n</span>.<br>\r\n            Equation: <span class=\"math\">2n − 11 = 15 ⇒ 2n = 15 + 11 = 26 ⇒ n = 26/2 = <strong>13</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part: Equation setup (0.5 Mark) + Solution (0.5 Mark)</span><span class=\"marking-marks\">1 Mark each (4 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q4_4_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_4_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Laxmi’s father is 49 years old. He is 4 years older than three times Laxmi’s age. What is Laxmi’s age?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Define variable:</strong><br>\r\n            Let Laxmi's present age be <span class=\"math\">y years</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Set up equation:</strong><br>\r\n            Three times Laxmi's age = <span class=\"math\">3y</span>.<br>\r\n            Father is 4 years older than <span class=\"math\">3y</span>: <span class=\"math\">3y + 4</span>.<br>\r\n            Given father's age is 49 years:<br>\r\n            <span class=\"math\">3y + 4 = 49</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 3: Solve for y:</strong><br>\r\n            <span class=\"math\">3y = 49 − 4 = 45 ⇒ y = 45/3 = <strong>15</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> Laxmi’s age is <strong>15 years</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Assuming variable and equation 3y + 4 = 49</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving y = 15 with final conclusion statement</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q4_4_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q4_4_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">Irfan says that he has 7 marbles more than five times the marbles Parmit has. Irfan has 37 marbles. How many marbles does Parmit have?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Define variable:</strong><br>\r\n            Let the number of marbles Parmit has be <span class=\"math\">m</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Form equation:</strong><br>\r\n            Five times Parmit's marbles = <span class=\"math\">5m</span>.<br>\r\n            7 marbles more than 5m = <span class=\"math\">5m + 7</span>.<br>\r\n            Given Irfan has 37 marbles:<br>\r\n            <span class=\"math\">5m + 7 = 37</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 3: Solve equation:</strong><br>\r\n            <span class=\"math\">5m = 37 − 7 = 30 ⇒ m = 30/5 = <strong>6</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> Parmit has <strong>6 marbles</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Forming equation 5m + 7 = 37</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving for m = 6 with statement</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n    <div class=\"q-card\" id=\"q4_1_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_1_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Solve the following equations by trial and error method:<br>(i) 5p + 2 = 17<br>(ii) 3m − 14 = 4</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) 5p + 2 = 17:</strong><br>\n            Try p = 1: LHS = 5(1) + 2 = 7 ≠ 17.<br>\n            Try p = 2: LHS = 5(2) + 2 = 12 ≠ 17.<br>\n            Try p = 3: LHS = 5(3) + 2 = 15 + 2 = 17 = RHS.<br>\n            Solution is <span class=\"math\"><strong>p = 3</strong></span>.<br>\n            <strong>(ii) 3m − 14 = 4:</strong><br>\n            Try m = 4: LHS = 3(4) − 14 = −2 ≠ 4.<br>\n            Try m = 5: LHS = 3(5) − 14 = 1 ≠ 4.<br>\n            Try m = 6: LHS = 3(6) − 14 = 18 − 14 = 4 = RHS.<br>\n            Solution is <span class=\"math\"><strong>m = 6</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Trial steps shown with final correct value</span><span class=\"marking-marks\">1.5 Marks each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q4_1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Write equations for the following statements:<br>(i) The sum of numbers x and 4 is 9.<br>(ii) 2 subtracted from y is 8.<br>(iii) Ten times a is 70.<br>(iv) The number b divided by 5 gives 6.<br>(v) Three-fourth of t is 15.<br>(vi) Seven times m plus 7 gets you 77.<br>(vii) One-fourth of a number x minus 4 gives 4.<br>(viii) If you take away 6 from 6 times y, you get 60.<br>(ix) If you add 3 to one-third of z, you get 30.</div>\n      <div class=\"q-marks\">4.5 Marks (1/2 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> <span class=\"math\"><strong>x + 4 = 9</strong></span><br>\n            <strong>(ii)</strong> <span class=\"math\"><strong>y − 2 = 8</strong></span><br>\n            <strong>(iii)</strong> <span class=\"math\"><strong>10a = 70</strong></span><br>\n            <strong>(iv)</strong> <span class=\"math\"><strong>b / 5 = 6</strong></span><br>\n            <strong>(v)</strong> <span class=\"math\"><strong>(3/4)t = 15</strong></span><br>\n            <strong>(vi)</strong> <span class=\"math\"><strong>7m + 7 = 77</strong></span><br>\n            <strong>(vii)</strong> <span class=\"math\"><strong>(x / 4) − 4 = 4</strong></span><br>\n            <strong>(viii)</strong> <span class=\"math\"><strong>6y − 6 = 60</strong></span><br>\n            <strong>(ix)</strong> <span class=\"math\"><strong>(z / 3) + 3 = 30</strong></span>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct algebraic equation translation</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q4_1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Write the following equations in statement forms:<br>(i) p + 4 = 15 &nbsp;&nbsp; (ii) m − 7 = 3 &nbsp;&nbsp; (iii) 2m = 7 &nbsp;&nbsp; (iv) m/5 = 3<br>(v) 3m/5 = 6 &nbsp;&nbsp; (vi) 3p + 4 = 25 &nbsp;&nbsp; (vii) 4p − 2 = 18 &nbsp;&nbsp; (viii) p/2 + 2 = 8</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> The sum of numbers p and 4 is 15.<br>\n            <strong>(ii)</strong> 7 subtracted from m is 3.<br>\n            <strong>(iii)</strong> Twice a number m is 7.<br>\n            <strong>(iv)</strong> One-fifth of a number m is 3.<br>\n            <strong>(v)</strong> Three-fifth of a number m is 6.<br>\n            <strong>(vi)</strong> Three times a number p plus 4 gives 25.<br>\n            <strong>(vii)</strong> 2 subtracted from four times a number p is 18.<br>\n            <strong>(viii)</strong> Add 2 to half of a number p to get 8.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate English mathematical statement for each equation</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q4_3_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_3_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Solve the following equations:<br>(a) 2(x + 4) = 12<br>(b) 3(n − 5) = 21<br>(c) 3(n − 5) = −21<br>(d) −4(2 + x) = 8<br>(e) 4(2 − x) = 8</div>\n      <div class=\"q-marks\">5 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) 2(x + 4) = 12:</strong><br>\n            Divide both sides by 2: <span class=\"math\">x + 4 = 6 ⇒ x = 6 − 4 = <strong>2</strong></span>.<br>\n            <strong>(b) 3(n − 5) = 21:</strong><br>\n            Divide both sides by 3: <span class=\"math\">n − 5 = 7 ⇒ n = 7 + 5 = <strong>12</strong></span>.<br>\n            <strong>(c) 3(n − 5) = −21:</strong><br>\n            Divide both sides by 3: <span class=\"math\">n − 5 = −7 ⇒ n = −7 + 5 = <strong>−2</strong></span>.<br>\n            <strong>(d) −4(2 + x) = 8:</strong><br>\n            Divide both sides by −4: <span class=\"math\">2 + x = −2 ⇒ x = −2 − 2 = <strong>−4</strong></span>.<br>\n            <strong>(e) 4(2 − x) = 8:</strong><br>\n            Divide both sides by 4: <span class=\"math\">2 − x = 2 ⇒ −x = 2 − 2 = 0 ⇒ <strong>x = 0</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each step of simplification and accurate variable value</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q4_1_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_1_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Set up an equation in the following cases:<br>(i) Irfan says that he has 7 marbles more than five times the marbles Parmit has. Irfan has 37 marbles. (Take m to be the number of Parmit's marbles).<br>(ii) Laxmi's father is 49 years old. He is 4 years older than three times Laxmi's age. (Take Laxmi's age to be y years).<br>(iii) The teacher tells the class that the highest marks obtained by a student in her class is twice the lowest marks plus 7. The highest score is 87. (Take the lowest score to be l).<br>(iv) In an isosceles triangle, the vertex angle is twice either base angle. (Let the base angle be b in degrees. Remember that the sum of angles of a triangle is 180 degrees).</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> Let Parmit's marbles = <span class=\"math\">m</span>.<br>\n            Five times Parmit's marbles = <span class=\"math\">5m</span>.<br>\n            Equation: <span class=\"math\"><strong>5m + 7 = 37</strong></span>.<br>\n            <strong>(ii)</strong> Let Laxmi's age = <span class=\"math\">y</span> years.<br>\n            Three times Laxmi's age = <span class=\"math\">3y</span>.<br>\n            Equation: <span class=\"math\"><strong>3y + 4 = 49</strong></span>.<br>\n            <strong>(iii)</strong> Let lowest marks = <span class=\"math\">l</span>.<br>\n            Twice lowest marks plus 7 = <span class=\"math\">2l + 7</span>.<br>\n            Equation: <span class=\"math\"><strong>2l + 7 = 87</strong></span>.<br>\n            <strong>(iv)</strong> Base angles = <span class=\"math\">b</span> and <span class=\"math\">b</span>. Vertex angle = <span class=\"math\">2b</span>.<br>\n            Sum: <span class=\"math\">b + b + 2b = 180° ⇒ <strong>4b = 180°</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct algebraic equation setup</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n    <div class=\"q-card\" id=\"q4_1_1_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_1_1_def')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Check whether the value given in brackets satisfies the equation:<br>(i) x + 3 = 0 (x = 3)<br>(ii) x + 3 = 0 (x = −3)<br>(iii) 5x = 25 (x = 5)<br>(iv) m/3 = 2 (m = 6)</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> <span class=\"math\">x + 3 = 0</span>, for <span class=\"math\">x = 3</span>: LHS = <span class=\"math\">3 + 3 = 6 ≠ 0</span> (RHS). <strong>No, equation is not satisfied.</strong><br>\n            <strong>(ii)</strong> <span class=\"math\">x + 3 = 0</span>, for <span class=\"math\">x = −3</span>: LHS = <span class=\"math\">−3 + 3 = 0 = \\text{RHS}</span>. <strong>Yes, equation is satisfied.</strong><br>\n            <strong>(iii)</strong> <span class=\"math\">5x = 25</span>, for <span class=\"math\">x = 5</span>: LHS = <span class=\"math\">5 × 5 = 25 = \\text{RHS}</span>. <strong>Yes, equation is satisfied.</strong><br>\n            <strong>(iv)</strong> <span class=\"math\">m/3 = 2</span>, for <span class=\"math\">m = 6</span>: LHS = <span class=\"math\">6 / 3 = 2 = \\text{RHS}</span>. <strong>Yes, equation is satisfied.</strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">LHS substitution and verification for each equation</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q4_2_2_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_2_2_def')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Give first the step you will use to separate the variable and then solve the equation:<br>(a) 3l = 42 &nbsp;&nbsp; (b) b/2 = 6 &nbsp;&nbsp; (c) p/7 = 4 &nbsp;&nbsp; (d) 4x = 25</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) 3l = 42:</strong><br>\n            • Step: Divide both sides by 3.<br>\n            • Solution: <span class=\"math\">l = 42 / 3 = <strong>14</strong></span>.<br><br>\n            <strong>(b) b/2 = 6:</strong><br>\n            • Step: Multiply both sides by 2.<br>\n            • Solution: <span class=\"math\">b = 6 × 2 = <strong>12</strong></span>.<br><br>\n            <strong>(c) p/7 = 4:</strong><br>\n            • Step: Multiply both sides by 7.<br>\n            • Solution: <span class=\"math\">p = 4 × 7 = <strong>28</strong></span>.<br><br>\n            <strong>(d) 4x = 25:</strong><br>\n            • Step: Divide both sides by 4.<br>\n            • Solution: <span class=\"math\">x = <strong>25/4 = 6.25</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating separation step and solving</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q4_2_3_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_2_3_def')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Give the steps you will use to separate the variable and then solve the equation:<br>(a) 3n − 2 = 46 &nbsp;&nbsp; (b) 5m + 7 = 17 &nbsp;&nbsp; (c) 20p/3 = 40 &nbsp;&nbsp; (d) 3p/10 = 6</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) 3n − 2 = 46:</strong><br>\n            • Step 1: Add 2 to both sides: <span class=\"math\">3n = 48</span>.<br>\n            • Step 2: Divide both sides by 3: <span class=\"math\">n = 48 / 3 = <strong>16</strong></span>.<br><br>\n            <strong>(b) 5m + 7 = 17:</strong><br>\n            • Step 1: Subtract 7 from both sides: <span class=\"math\">5m = 10</span>.<br>\n            • Step 2: Divide both sides by 5: <span class=\"math\">m = 10 / 5 = <strong>2</strong></span>.<br><br>\n            <strong>(c) 20p/3 = 40:</strong><br>\n            • Step 1: Multiply both sides by 3: <span class=\"math\">20p = 120</span>.<br>\n            • Step 2: Divide both sides by 20: <span class=\"math\">p = 120 / 20 = <strong>6</strong></span>.<br><br>\n            <strong>(d) 3p/10 = 6:</strong><br>\n            • Step 1: Multiply both sides by 10: <span class=\"math\">3p = 60</span>.<br>\n            • Step 2: Divide both sides by 3: <span class=\"math\">p = 60 / 3 = <strong>20</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating 2 steps and final solution</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q4_4_1_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_4_1_def')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Set up equations and solve them to find the unknown numbers in the following cases:<br>(a) Add 4 to eight times a number; you get 60.<br>(b) One-fifth of a number minus 4 gives 3.<br>(c) If I take three-fourths of a number and add 3 to it, I get 21.<br>(d) When I subtracted 11 from twice a number, the result was 15.</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Let the unknown number be <span class=\"math\">x</span>:<br>\n            <strong>(a)</strong> Equation: <span class=\"math\">8x + 4 = 60</span><br>\n            <span class=\"math\">8x = 60 − 4 = 56 ⟹ x = 56 / 8 = <strong>7</strong></span>.<br><br>\n            <strong>(b)</strong> Equation: <span class=\"math\">\\frac{x}{5} − 4 = 3</span><br>\n            <span class=\"math\">\\frac{x}{5} = 7 ⟹ x = 7 × 5 = <strong>35</strong></span>.<br><br>\n            <strong>(c)</strong> Equation: <span class=\"math\">\\frac{3}{4}x + 3 = 21</span><br>\n            <span class=\"math\">\\frac{3}{4}x = 18 ⟹ x = \\frac{18 × 4}{3} = 6 × 4 = <strong>24</strong></span>.<br><br>\n            <strong>(d)</strong> Equation: <span class=\"math\">2x − 11 = 15</span><br>\n            <span class=\"math\">2x = 15 + 11 = 26 ⟹ x = 26 / 2 = <strong>13</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Setting up correct equation</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Solving for unknown number</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\">\r\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\r\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\r\n    </div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">Case Study: Cricket Partnership</div>\r\n        <div class=\"cbq-question\"><strong>Scenario:</strong> Rahul scored twice as many runs as Sachin. Together, their runs fell two short of a double century (200 runs). (i) Form an equation to represent this situation. (ii) How many runs did each one score?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <p><strong>(i) Equation Formulation:</strong><br>\r\n          Let Sachin's score = <span class=\"math\">x</span> runs.<br>\r\n          Rahul's score = <span class=\"math\">2x</span> runs.<br>\r\n          Combined runs = <span class=\"math\">x + 2x = 3x</span>.<br>\r\n          Two short of a double century = <span class=\"math\">200 − 2 = 198</span>.<br>\r\n          Equation: <span class=\"math\"><strong>3x = 198</strong></span>.</p>\r\n          <p><strong>(ii) Solving for individual scores:</strong><br>\r\n          <span class=\"math\">x = 198/3 = <strong>66</strong></span>.<br>\r\n          Sachin scored = <strong>66 runs</strong>.<br>\r\n          Rahul scored = <span class=\"math\">2 × 66 = <strong>132 runs</strong></span>.<br>\r\n          Check: <span class=\"math\">66 + 132 = 198</span> (verified).</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(3)\">← Chapter 3: Data Handling</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(5)\">Chapter 5: Lines &amp; Angles →</button>\r\n  </div>\r\n</section>\r\n","5":"<section class=\"chapter-section\" id=\"ch5\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">5</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 5: Lines and Angles</h2>\r\n      <p>NCERT Exercise 5.1 to 5.2 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"concept-card\">\r\n    <div class=\"concept-header\">📌 Key Concepts &amp; Angle Properties Summary</div>\r\n    <ul class=\"concept-list\">\r\n      <li><strong>Complementary Angles:</strong> Two angles whose sum of measures equals 90°. Each angle is called the complement of the other.</li>\r\n      <li><strong>Supplementary Angles:</strong> Two angles whose sum of measures equals 180°. Each angle is called the supplement of the other.</li>\r\n      <li><strong>Adjacent Angles:</strong> Angles that have a common vertex, a common arm, and non-common arms on opposite sides of the common arm.</li>\r\n      <li><strong>Linear Pair:</strong> A pair of adjacent angles whose non-common sides form opposite rays (a straight line). Sum = 180°.</li>\r\n      <li><strong>Vertically Opposite Angles:</strong> When two lines intersect at a point, vertically opposite angles are formed and are always equal.</li>\r\n      <li><strong>Parallel Lines and Transversal:</strong>\r\n        When two parallel lines l ∥ m are cut by a transversal t:\r\n        <ul>\r\n          <li><em>Corresponding angles</em> are equal (∠ 1 = ∠ 5, etc.).</li>\r\n          <li><em>Alternate interior angles</em> are equal (∠ 3 = ∠ 5, ∠ 4 = ∠ 6).</li>\r\n          <li><em>Alternate exterior angles</em> are equal (∠ 1 = ∠ 7, ∠ 2 = ∠ 8).</li>\r\n          <li><em>Co-interior angles</em> (interior angles on same side of transversal) are supplementary (∠ 4 + ∠ 5 = 180°).</li>\r\n        </ul>\r\n      </li>\r\n    </ul>\r\n  </div>\r\n\r\n  <!-- EXERCISE 5.1 -->\r\n  <div class=\"ex-div\">Exercise 5.1</div>\r\n\r\n  <div class=\"q-card\" id=\"q5_1_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Find the complement of each of the following angles:<br>(i) 20°<br>(ii) 63°<br>(iii) 57°</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p>Two angles are complementary if their sum is <span class=\"math\">90°</span>. The complement of <span class=\"math\">θ = 90° − θ</span>.</p>\r\n          <div class=\"step\">\r\n            <strong>(i) Complement of 20°:</strong><br>\r\n            <span class=\"math\">= 90° − 20° = <strong>70°</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) Complement of 63°:</strong><br>\r\n            <span class=\"math\">= 90° − 63° = <strong>27°</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) Complement of 57°:</strong><br>\r\n            <span class=\"math\">= 90° − 57° = <strong>33°</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct complement subtraction</span><span class=\"marking-marks\">1 Mark each (3 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q5_1_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Find the supplement of each of the following angles:<br>(i) 105°<br>(ii) 87°<br>(iii) 154°</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p>Two angles are supplementary if their sum is <span class=\"math\">180°</span>. The supplement of <span class=\"math\">θ = 180° − θ</span>.</p>\r\n          <div class=\"step\">\r\n            <strong>(i) Supplement of 105°:</strong><br>\r\n            <span class=\"math\">= 180° − 105° = <strong>75°</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) Supplement of 87°:</strong><br>\r\n            <span class=\"math\">= 180° − 87° = <strong>93°</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) Supplement of 154°:</strong><br>\r\n            <span class=\"math\">= 180° − 154° = <strong>26°</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct supplement calculation</span><span class=\"marking-marks\">1 Mark each (3 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q5_1_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">Identify which of the following pairs of angles are complementary and which are supplementary:<br>(i) 65°, 115°<br>(ii) 63°, 27°<br>(iii) 112°, 68°<br>(iv) 130°, 50°<br>(v) 45°, 45°<br>(vi) 80°, 10°</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) 65° + 115° = 180°:</strong> ⇒ <strong>Supplementary</strong>.<br>\r\n            <strong>(ii) 63° + 27° = 90°:</strong> ⇒ <strong>Complementary</strong>.<br>\r\n            <strong>(iii) 112° + 68° = 180°:</strong> ⇒ <strong>Supplementary</strong>.<br>\r\n            <strong>(iv) 130° + 50° = 180°:</strong> ⇒ <strong>Supplementary</strong>.<br>\r\n            <strong>(v) 45° + 45° = 90°:</strong> ⇒ <strong>Complementary</strong>.<br>\r\n            <strong>(vi) 80° + 10° = 90°:</strong> ⇒ <strong>Complementary</strong>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct sum and classification</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q5_1_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_4')\">\r\n      <div class=\"q-num\">Q4</div>\r\n      <div class=\"q-text\">(a) Find the angle which is equal to its complement.<br>(b) Find the angle which is equal to its supplement.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) Angle equal to its complement:</strong><br>\r\n            Let the angle be <span class=\"math\">x</span>.<br>\r\n            Its complement is <span class=\"math\">90° − x</span>.<br>\r\n            According to question: <span class=\"math\">x = 90° − x ⇒ 2x = 90° ⇒ x = <strong>45°</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) Angle equal to its supplement:</strong><br>\r\n            Let the angle be <span class=\"math\">y</span>.<br>\r\n            Its supplement is <span class=\"math\">180° − y</span>.<br>\r\n            According to question: <span class=\"math\">y = 180° − y ⇒ 2y = 180° ⇒ y = <strong>90°</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): Equation 2x = 90° and x = 45°</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): Equation 2y = 180° and y = 90°</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q5_1_5\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_5')\">\r\n      <div class=\"q-num\">Q5</div>\r\n      <div class=\"q-text\">Two lines intersect at a point. If one angle is 55°, find the values of all other angles x, y and z.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Vertically opposite angle:</strong><br>\r\n            Angle <span class=\"math\">x</span> is vertically opposite to 55°.<br>\r\n            Therefore, <span class=\"math\">x = <strong>55°</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Linear pair:</strong><br>\r\n            Angle <span class=\"math\">y</span> and 55° form a linear pair on a straight line:<br>\r\n            <span class=\"math\">y + 55° = 180° ⇒ y = 180° − 55° = <strong>125°</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 3: Vertically opposite to y:</strong><br>\r\n            Angle <span class=\"math\">z</span> is vertically opposite to <span class=\"math\">y</span>:<br>\r\n            <span class=\"math\">z = y = <strong>125°</strong></span>.\r\n          </div>\r\n          <p><strong>Final Answer:</strong> <span class=\"math\">x = 55°</span>, <span class=\"math\">y = 125°</span>, <span class=\"math\">z = 125°</span>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">x = 55° with vertically opposite angle reason</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">y = 125° with linear pair equation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">z = 125° with vertically opposite reason</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 5.2 -->\r\n  <div class=\"ex-div\">Exercise 5.2 (Parallel Lines &amp; Transversal)</div>\r\n\r\n  <div class=\"q-card\" id=\"q5_2_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_2_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">In a given figure, lines l ∥ m are cut by transversal p. If one exterior angle is 125°, find the measures of remaining angles a, b, c, d, e, f.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Linear pair with 125°:</strong><br>\r\n            <span class=\"math\">e + 125° = 180° ⇒ e = 180° − 125° = <strong>55°</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Vertically opposite angles:</strong><br>\r\n            <span class=\"math\">f = e = <strong>55°</strong></span>.<br>\r\n            Angle opposite to 125° is <span class=\"math\">125°</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 3: Corresponding angles (since l ∥ m):</strong><br>\r\n            <span class=\"math\">d = 125°</span> (corresponding to 125°).<br>\r\n            <span class=\"math\">a = e = <strong>55°</strong></span> (corresponding to e).<br>\r\n            <span class=\"math\">b = d = <strong>125°</strong></span> (vertically opposite to d).<br>\r\n            <span class=\"math\">c = a = <strong>55°</strong></span> (vertically opposite to a).\r\n          </div>\r\n          <p><strong>Final Answer:</strong> <span class=\"math\">a = 55°</span>, <span class=\"math\">b = 125°</span>, <span class=\"math\">c = 55°</span>, <span class=\"math\">d = 125°</span>, <span class=\"math\">e = 55°</span>, <span class=\"math\">f = 55°</span>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Linear pair to find e = 55°</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Corresponding angle arguments for d, a</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Vertically opposite arguments for b, c, f</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q5_2_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q5_2_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Find the value of x in each of the following figures if l ∥ m:<br>(i) One angle is 110° and alternate interior to x with linear pair.<br>(ii) Co-interior angles are (2x)° and (3x)°.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) Figure with angle 110°:</strong><br>\r\n            The angle adjacent to 110° on the straight line is: <span class=\"math\">180° − 110° = 70°</span>.<br>\r\n            Since <span class=\"math\">l ∥ m</span>, angle <span class=\"math\">x</span> is corresponding (or alternate) to this angle:<br>\r\n            <span class=\"math\">x = 180° − 110° = <strong>70°</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) Co-interior angles 2x and 3x:</strong><br>\r\n            Interior angles on the same side of a transversal are supplementary:<br>\r\n            <span class=\"math\">2x + 3x = 180° ⇒ 5x = 180° ⇒ x = 180°/5 = <strong>36°</strong></span>.<br>\r\n            The angles are <span class=\"math\">2(36°) = 72°</span> and <span class=\"math\">3(36°) = 108°</span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): Linear pair / corresponding reasoning x = 70°</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): Co-interior angles sum = 180° and x = 36°</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n    <div class=\"q-card\" id=\"q5_1_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Can two angles be supplementary if both of them are:<br>(i) acute?<br>(ii) obtuse?<br>(iii) right?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) No:</strong> If both angles are acute (&lt; 90°), their sum is always strictly less than <span class=\"math\">90° + 90° = 180°</span>.<br>\n            <strong>(ii) No:</strong> If both angles are obtuse (&gt; 90°), their sum is always strictly greater than <span class=\"math\">90° + 90° = 180°</span>.<br>\n            <strong>(iii) Yes:</strong> If both angles are right angles (90° each), their sum is <span class=\"math\">90° + 90° = 180°</span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part with accurate mathematical reason</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_1_12\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_12')\">\n      <div class=\"q-num\">Q12</div>\n      <div class=\"q-text\">Find the values of the angles x, y, and z in each of the following:<br>(i) Two intersecting lines form vertically opposite angles, one of which is 55°.<br>(ii) Three rays meet at a line where angles are 40°, x, 25° on one side, and y and z on the opposite side.</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> <span class=\"math\">x = <strong>55°</strong></span> (Vertically opposite angles are equal).<br>\n            Since <span class=\"math\">55° + y = 180°</span> (Linear pair), <span class=\"math\">y = 180° − 55° = <strong>125°</strong></span>.<br>\n            <span class=\"math\">z = y = <strong>125°</strong></span> (Vertically opposite to y).<br>\n            <strong>(ii)</strong> On the straight line: <span class=\"math\">40° + x + 25° = 180° ⇒ x + 65° = 180° ⇒ x = 180° − 65° = <strong>115°</strong></span>.<br>\n            <span class=\"math\">z = 40°</span> (Vertically opposite to 40°).<br>\n            <span class=\"math\">y + z = 180° ⇒ y + 40° = 180° ⇒ y = 180° − 40° = <strong>140°</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> (i) x = 55°, y = 125°, z = 125°; (ii) x = 115°, y = 140°, z = 40°.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): x = 55°, y = 125°, z = 125° with geometric theorems</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): x = 115°, y = 140°, z = 40° with linear pair and vertically opposite rules</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_2_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_2_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Find the value of x in each of the following figures if l ∥ m:<br>(i) A line intersects parallel lines l and m with an angle 110° and interior angle x.<br>(ii) A transversal intersects parallel lines l and m forming corresponding angles 100° and x.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> Let the angle vertically opposite to 110° be ∠1 = 110°.<br>\n            Since l ∥ m, interior angles on the same side of the transversal are supplementary:<br>\n            <span class=\"math\">110° + x = 180° ⇒ x = 180° − 110° = <strong>70°</strong></span>.<br>\n            <strong>(ii)</strong> Since l ∥ m and the line is a transversal, corresponding angles are equal:<br>\n            <span class=\"math\">x = <strong>100°</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> (i) x = 70°, (ii) x = 100°.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): Supplementary interior angles calculation: x = 70°</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): Corresponding angle property: x = 100°</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_1_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">In the given figure, ∠1 and ∠2 are supplementary angles. If ∠1 is decreased, what changes should take place in ∠2 so that both the angles still remain supplementary?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Since ∠1 and ∠2 are supplementary, <span class=\"math\">∠1 + ∠2 = 180°</span>.<br>\n            If ∠1 is decreased by some measure <span class=\"math\">d</span>, then ∠2 must be <strong>increased by the same measure</strong> so that their sum continues to remain 180°.\n          </div>\n          <p><strong>Final Answer:</strong> ∠2 must <strong>increase by the same degree/measure</strong> by which ∠1 is decreased.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Supplementary condition: ∠1 + ∠2 = 180°</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conclusion that ∠2 must increase by the same amount</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_1_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">An angle is greater than 45°. Is its complementary angle greater than 45° or equal to 45° or less than 45°?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Let the two complementary angles be <span class=\"math\">x</span> and <span class=\"math\">y</span>.<br>\n            Then, <span class=\"math\">x + y = 90° ⇒ y = 90° − x</span>.<br>\n            Given that <span class=\"math\">x &gt; 45°</span>.<br>\n            Subtracting both sides from 90°: <span class=\"math\">90° − x &lt; 90° − 45° ⇒ y &lt; 45°</span>.\n          </div>\n          <p><strong>Final Answer:</strong> Its complementary angle is <strong>less than 45°</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Inequality derivation from x + y = 90°</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conclusion: less than 45°</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_1_11\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_11')\">\n      <div class=\"q-num\">Q11</div>\n      <div class=\"q-text\">In the following figure, is ∠1 adjacent to ∠2? Give reasons.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>No</strong>, ∠1 is <strong>not adjacent</strong> to ∠2.<br>\n            <strong>Reason:</strong> For two angles to be adjacent, they must satisfy three essential geometric conditions:<br>\n            1. They must have a common vertex.<br>\n            2. They must have a common arm.<br>\n            3. Their non-common arms must be on different sides of the common arm.<br>\n            Here, ∠1 and ∠2 do <strong>not have a common vertex</strong> (their vertices are at two completely different points).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Answer: No</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reason: Do not have a common vertex</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_2_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_2_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">In the given figures below, decide whether l is parallel to m:<br>(i) Consecutive interior angles are 126° and 44°.<br>(ii) Two interior angles on the same side of transversal with vertical opposite given are 75° and 75°.<br>(iii) Alternate exterior / corresponding angles given are 57° and 123°.<br>(iv) Angles are 98° and 72°.</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> Sum of interior angles on same side = <span class=\"math\">126° + 44° = 170° ≠ 180°</span>. Hence, line l is <strong>not parallel</strong> to m.<br>\n            <strong>(ii)</strong> Angle vertically opposite to 75° is 75°. Sum = <span class=\"math\">75° + 75° = 150° ≠ 180°</span>. Hence, line l is <strong>not parallel</strong> to m.<br>\n            <strong>(iii)</strong> Linear pair to 123° = <span class=\"math\">180° − 123° = 57°</span>. The corresponding angles are equal (57° = 57°). Hence, line l is <strong>parallel to m (l ∥ m)</strong>.<br>\n            <strong>(iv)</strong> Corresponding angle = <span class=\"math\">180° − 98° = 82° ≠ 72°</span>. Hence, line l is <strong>not parallel</strong> to m.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each decision with angle sum or corresponding angle justification</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n    <div class=\"q-card\" id=\"q5_1_1_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_1_def')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Find the complement of each of the following angles:<br>(i) 20° &nbsp;&nbsp; (ii) 63° &nbsp;&nbsp; (iii) 57°</div>\n      <div class=\"q-marks\">3 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Two angles are complementary if their sum is 90°.<br>\n            Complement of an angle = <span class=\"math\">90° − \\text{angle}</span>.<br><br>\n            <strong>(i) Complement of 20°:</strong> <span class=\"math\">90° − 20° = <strong>70°</strong></span>.<br>\n            <strong>(ii) Complement of 63°:</strong> <span class=\"math\">90° − 63° = <strong>27°</strong></span>.<br>\n            <strong>(iii) Complement of 57°:</strong> <span class=\"math\">90° − 57° = <strong>33°</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula 90° − angle and correct evaluation</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_1_2_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_2_def')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find the supplement of each of the following angles:<br>(i) 105° &nbsp;&nbsp; (ii) 87° &nbsp;&nbsp; (iii) 154°</div>\n      <div class=\"q-marks\">3 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Two angles are supplementary if their sum is 180°.<br>\n            Supplement of an angle = <span class=\"math\">180° − \\text{angle}</span>.<br><br>\n            <strong>(i) Supplement of 105°:</strong> <span class=\"math\">180° − 105° = <strong>75°</strong></span>.<br>\n            <strong>(ii) Supplement of 87°:</strong> <span class=\"math\">180° − 87° = <strong>93°</strong></span>.<br>\n            <strong>(iii) Supplement of 154°:</strong> <span class=\"math\">180° − 154° = <strong>26°</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula 180° − angle and evaluation</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_1_9_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1_9_def')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">In an intersecting lines figure: (i) Is ∠1 adjacent to ∠2? (ii) Is ∠AOC adjacent to ∠AOE? (iii) Do ∠COE and ∠EOD form a linear pair? (iv) Are ∠BOD and ∠DOA supplementary? (v) Is ∠1 vertically opposite to ∠4? (vi) What is the vertically opposite angle of ∠5?</div>\n      <div class=\"q-marks\">3 Marks (1/2 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> <strong>Yes</strong>, ∠1 and ∠2 have common vertex O and common arm OC with non-common arms on opposite sides.<br>\n            <strong>(ii)</strong> <strong>No</strong>, common arm OA is internal, so non-common arms do not lie on opposite sides.<br>\n            <strong>(iii)</strong> <strong>Yes</strong>, ∠COE and ∠EOD lie on a straight line CD and form a linear pair.<br>\n            <strong>(iv)</strong> <strong>Yes</strong>, line AB is straight, so ∠BOD + ∠DOA = 180° (supplementary).<br>\n            <strong>(v)</strong> <strong>Yes</strong>, lines AB and CD intersect at O making ∠1 and ∠4 vertically opposite.<br>\n            <strong>(vi)</strong> Vertically opposite angle of ∠5 (∠AOD) is <strong>∠COB (or ∠2 + ∠3)</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct geometric reasoning for each part</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_2_2_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_2_2_def')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">In a pair of parallel lines cut by a transversal, identify:<br>(i) the pairs of corresponding angles<br>(ii) the pairs of alternate interior angles<br>(iii) the pairs of interior angles on the same side of the transversal<br>(iv) the vertically opposite angles.</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            For two parallel lines cut by a transversal labeled with angles 1 through 8:<br>\n            <strong>(i) Corresponding angles:</strong> (∠1, ∠5), (∠2, ∠6), (∠4, ∠8), (∠3, ∠7).<br>\n            <strong>(ii) Alternate interior angles:</strong> (∠3, ∠5) and (∠2, ∠8).<br>\n            <strong>(iii) Interior angles on the same side of transversal:</strong> (∠2, ∠5) and (∠3, ∠8).<br>\n            <strong>(iv) Vertically opposite angles:</strong> (∠1, ∠3), (∠2, ∠4), (∠5, ∠7), (∠6, ∠8).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing correct pairs for each angle classification</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\">\r\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\r\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\r\n    </div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">HOTS: Ratio of Supplementary Angles</div>\r\n        <div class=\"cbq-question\"><strong>Problem:</strong> Two supplementary angles are in the ratio 4 : 5. Find the measure of both angles.</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <p>Let the common ratio multiplier be <span class=\"math\">x</span>.<br>\r\n          The two angles are <span class=\"math\">4x</span> and <span class=\"math\">5x</span>.<br>\r\n          Since they are supplementary:<br>\r\n          <span class=\"math\">4x + 5x = 180° ⇒ 9x = 180° ⇒ x = 180°/9 = 20°</span>.<br>\r\n          First angle = <span class=\"math\">4 × 20° = <strong>80°</strong></span>.<br>\r\n          Second angle = <span class=\"math\">5 × 20° = <strong>100°</strong></span>.<br>\r\n          Check: <span class=\"math\">80° + 100° = 180°</span> (verified).</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#10b981;\">⚡ Assertion &amp; Reason</div>\r\n        <div class=\"cbq-question\">\r\n          <strong>Assertion (A):</strong> If two parallel lines are intersected by a transversal, then each pair of alternate interior angles are equal.<br>\r\n          <strong>Reason (R):</strong> If two parallel lines are intersected by a transversal, the interior angles on the same side of the transversal are supplementary.<br>\r\n          Choose: (a) Both A and R are true and R is the correct explanation of A. (b) Both A and R are true, but R is not the correct explanation of A. (c) A is true, R is false. (d) A is false, R is true.\r\n        </div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <strong>Answer: (b) Both A and R are true, but R is not the correct explanation of A.</strong><br>\r\n          <em>Explanation:</em> Both statements are fundamental, correct geometric properties of parallel lines and transversals, but Reason (R) states the co-interior angle property, which is not the explanation for why alternate interior angles are equal.\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(4)\">← Chapter 4: Simple Equations</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(6)\">Chapter 6: Triangle &amp; its Properties →</button>\r\n  </div>\r\n</section>\r\n","6":"<section class=\"chapter-section\" id=\"ch6\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">6</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 6: The Triangle and its Properties</h2>\r\n      <p>NCERT Exercise 6.1 to 6.5 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"concept-card\">\r\n    <div class=\"concept-header\">📌 Key Concepts &amp; Theorems Summary</div>\r\n    <ul class=\"concept-list\">\r\n      <li><strong>Median of a Triangle:</strong> The line segment connecting a vertex to the midpoint of the opposite side. Every triangle has 3 medians that concur at the <em>Centroid</em>.</li>\r\n      <li><strong>Altitude of a Triangle:</strong> The perpendicular line segment from a vertex to the line containing the opposite side. A triangle has 3 altitudes that concur at the <em>Orthocentre</em>.</li>\r\n      <li><strong>Exterior Angle Property:</strong> An exterior angle of a triangle is equal to the sum of its two interior opposite angles:\r\n        ∠ ext = ∠ A + ∠ B\r\n      </li>\r\n      <li><strong>Angle Sum Property:</strong> The sum of all three interior angles of a triangle is always 180°:\r\n        ∠ A + ∠ B + ∠ C = 180°\r\n      </li>\r\n      <li><strong>Triangle Inequality Property:</strong> The sum of the lengths of any two sides of a triangle is always greater than the length of the third side:\r\n        a + b > c,   b + c > a,   c + a > b\r\n      </li>\r\n      <li><strong>Pythagoras Theorem:</strong> In a right-angled triangle, the square of the hypotenuse is equal to the sum of the squares of the other two sides:\r\n        Hypotenuse² = Base² + Perpendicular² ⇒ h² = b² + p²\r\n      </li>\r\n    </ul>\r\n  </div>\r\n\r\n  <!-- EXERCISE 6.1 -->\r\n  <div class=\"ex-div\">Exercise 6.1</div>\r\n\r\n  <div class=\"q-card\" id=\"q6_1_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_1_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">In ΔPQR, D is the mid-point of QR. (i) Line segment PM is ..... (ii) Line segment PD is ..... (iii) Is QM = MR?</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) Line segment PM:</strong><br>\r\n            Since <span class=\"math\">PM ⊥ QR</span> (makes a right angle 90° with QR), <span class=\"math\">PM</span> is an <strong>Altitude</strong> of ΔPQR.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) Line segment PD:</strong><br>\r\n            Since D is the midpoint of QR, line segment joining vertex P to midpoint D is the <strong>Median</strong> of ΔPQR.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) Is QM = MR?</strong><br>\r\n            <strong>No, QM ≠ MR.</strong> Because D is the midpoint (so <span class=\"math\">QD = DR</span>), whereas M is the foot of the perpendicular altitude, which is not necessarily the midpoint for a scalene triangle.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(i) Altitude</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(ii) Median</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">(iii) No, with justification</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 6.2 -->\r\n  <div class=\"ex-div\">Exercise 6.2 (Exterior Angle Property)</div>\r\n\r\n  <div class=\"q-card\" id=\"q6_2_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_2_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Find the value of the unknown exterior angle x in the following figures:<br>(i) Interior opposite angles are 50° and 70°<br>(ii) Interior opposite angles are 65° and 45°<br>(iii) Interior opposite angles are 30° and 40°</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p>By Exterior Angle Property: <span class=\"math\">Exterior angle = Sum of interior opposite angles</span>.</p>\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">x = 50° + 70° = <strong>120°</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) <span class=\"math\">x = 65° + 45° = <strong>110°</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) <span class=\"math\">x = 30° + 40° = <strong>70°</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Exterior angle formula statement</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation</span><span class=\"marking-marks\">0.67 Mark each (2 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q6_2_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_2_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Find the value of the unknown interior angle x in the following figures:<br>(i) Exterior angle = 115°, one interior opposite angle = 50°<br>(ii) Exterior angle = 100°, one interior opposite angle = 70°<br>(iii) Exterior angle = 125°, right angled at other interior opposite angle (90°)</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">x + 50° = 115° ⇒ x = 115° − 50° = <strong>65°</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) <span class=\"math\">x + 70° = 100° ⇒ x = 100° − 70° = <strong>30°</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) <span class=\"math\">x + 90° = 125° ⇒ x = 125° − 90° = <strong>35°</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct subtraction from exterior angle</span><span class=\"marking-marks\">1 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 6.3 -->\r\n  <div class=\"ex-div\">Exercise 6.3 (Angle Sum Property)</div>\r\n\r\n  <div class=\"q-card\" id=\"q6_3_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_3_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Find the value of the unknown x in the following triangles:<br>(i) Two angles are 50° and 60°<br>(ii) Right-angled triangle with one acute angle 30°<br>(iii) Two angles are 30° and 110°<br>(iv) Isosceles triangle with two equal angles x and vertex angle 50°<br>(v) Equilateral-like triangle with all angles equal to x</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p>By Angle Sum Property of a triangle: <span class=\"math\">Sum of all 3 angles = 180°</span>.</p>\r\n          <div class=\"step\">\r\n            <strong>(i)</strong> <span class=\"math\">x + 50° + 60° = 180° ⇒ x + 110° = 180° ⇒ x = <strong>70°</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii)</strong> <span class=\"math\">x + 90° + 30° = 180° ⇒ x + 120° = 180° ⇒ x = <strong>60°</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii)</strong> <span class=\"math\">x + 30° + 110° = 180° ⇒ x + 140° = 180° ⇒ x = <strong>40°</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iv)</strong> <span class=\"math\">x + x + 50° = 180° ⇒ 2x = 180° − 50° = 130° ⇒ x = 130°/2 = <strong>65°</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(v)</strong> <span class=\"math\">x + x + x = 180° ⇒ 3x = 180° ⇒ x = 180°/3 = <strong>60°</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating Angle Sum Property = 180°</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurately computed angle values</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 6.4 -->\r\n  <div class=\"ex-div\">Exercise 6.4 (Triangle Inequality)</div>\r\n\r\n  <div class=\"q-card\" id=\"q6_4_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_4_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Is it possible to have a triangle with the following sides?<br>(i) 2 cm, 3 cm, 5 cm<br>(ii) 3 cm, 6 cm, 7 cm<br>(iii) 6 cm, 3 cm, 2 cm</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p><strong>Property:</strong> In any triangle, the sum of lengths of any two sides must be strictly greater than the third side (<span class=\"math\">a + b > c</span>).</p>\r\n          <div class=\"step\">\r\n            <strong>(i) 2 cm, 3 cm, 5 cm:</strong><br>\r\n            Check sum of smaller sides: <span class=\"math\">2 + 3 = 5 cm</span>.<br>\r\n            Since <span class=\"math\">5</span> is not greater than the third side <span class=\"math\">5</span> (<span class=\"math\">5 = 5</span>), <strong>a triangle is NOT possible</strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) 3 cm, 6 cm, 7 cm:</strong><br>\r\n            Check all three combinations:<br>\r\n            • <span class=\"math\">3 + 6 = 9 > 7</span> (True)<br>\r\n            • <span class=\"math\">6 + 7 = 13 > 3</span> (True)<br>\r\n            • <span class=\"math\">3 + 7 = 10 > 6</span> (True)<br>\r\n            Therefore, <strong>a triangle IS possible</strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) 6 cm, 3 cm, 2 cm:</strong><br>\r\n            Check sum of smaller sides: <span class=\"math\">3 + 2 = 5 cm</span>.<br>\r\n            Since <span class=\"math\">5 < 6</span> (less than third side), <strong>a triangle is NOT possible</strong>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part checked against a + b > c with clear decision</span><span class=\"marking-marks\">1 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q6_4_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_4_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">The lengths of two sides of a triangle are 12 cm and 15 cm. Between what two measures should the length of the third side fall?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Mathematical Principle:</strong><br>\r\n            For any triangle with sides <span class=\"math\">a, b, c</span>:<br>\r\n            <span class=\"math\">|a − b| < c < (a + b)</span>.<br>\r\n            That is, the third side must be greater than the difference of the two sides and less than their sum.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Calculation:</strong><br>\r\n            Sum of two sides = <span class=\"math\">15 + 12 = <strong>27 cm</strong></span>.<br>\r\n            Difference of two sides = <span class=\"math\">15 − 12 = <strong>3 cm</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> The length of the third side must be greater than <strong>3 cm</strong> and less than <strong>27 cm</strong> (i.e. between 3 cm and 27 cm).</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Difference bound: 15 − 12 = 3 cm</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Sum bound: 15 + 12 = 27 cm with final statement</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 6.5 -->\r\n  <div class=\"ex-div\">Exercise 6.5 (Pythagoras Theorem)</div>\r\n\r\n  <div class=\"q-card\" id=\"q6_5_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_5_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">PQR is a triangle, right-angled at P. If PQ = 10 cm and PR = 24 cm, find QR.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Identify sides of right-angled triangle:</strong><br>\r\n            Right angle is at vertex P ⇒ QR is the <strong>hypotenuse</strong>.<br>\r\n            Given legs: <span class=\"math\">PQ = 10 cm</span>, <span class=\"math\">PR = 24 cm</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Apply Pythagoras Theorem:</strong><br>\r\n            <span class=\"math\">QR² = PQ² + PR²</span><br>\r\n            <span class=\"math\">QR² = 10² + 24² = 100 + 576 = 676</span><br>\r\n            <span class=\"math\">QR = √(676) = <strong>26 cm</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> The length of <span class=\"math\">QR</span> is <strong>26 cm</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Pythagoras formula: QR² = PQ² + PR²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">10² + 24² = 676</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">QR = 26 cm with unit</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q6_5_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_5_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">A 15 m long ladder reached a window 12 m high from the ground on placing it against a wall at a distance a. Find the distance of the foot of the ladder from the wall.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Geometry setup:</strong><br>\r\n            The wall and the horizontal ground meet at 90°.<br>\r\n            Ladder acts as hypotenuse: <span class=\"math\">h = 15 m</span>.<br>\r\n            Height of window: <span class=\"math\">p = 12 m</span>.<br>\r\n            Distance of foot from wall: <span class=\"math\">b = a</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Pythagoras Theorem:</strong><br>\r\n            <span class=\"math\">a² + 12² = 15²</span><br>\r\n            <span class=\"math\">a² + 144 = 225</span><br>\r\n            <span class=\"math\">a² = 225 − 144 = 81</span><br>\r\n            <span class=\"math\">a = √(81) = <strong>9 m</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> The distance of the foot of the ladder from the wall is <strong>9 metres</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Pythagoras setup: a² + 12² = 15²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">a² = 81 evaluation</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Final answer a = 9 m with unit</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q6_5_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_5_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">A tree is broken at a height of 5 m from the ground and its top touches the ground at a distance of 12 m from the base of the tree. Find the original height of the tree.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Right-angled triangle model:</strong><br>\r\n            Let <span class=\"math\">BC = 5 m</span> be the standing trunk (perpendicular).<br>\r\n            Distance from trunk base to top <span class=\"math\">AB = 12 m</span> (base).<br>\r\n            The broken fallen trunk <span class=\"math\">AC</span> is the hypotenuse.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Calculate hypotenuse AC:</strong><br>\r\n            <span class=\"math\">AC² = AB² + BC² = 12² + 5² = 144 + 25 = 169</span><br>\r\n            <span class=\"math\">AC = √(169) = 13 m</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 3: Calculate original tree height:</strong><br>\r\n            <span class=\"math\">Original height = BC + AC = 5 m + 13 m = <strong>18 m</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> The original height of the tree was <strong>18 metres</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Pythagoras theorem: AC = 13 m</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Adding 5 m + 13 m = 18 m with conclusion</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q6_5_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q6_5_4')\">\r\n      <div class=\"q-num\">Q4</div>\r\n      <div class=\"q-text\">Find the perimeter of the rectangle whose length is 40 cm and a diagonal is 41 cm.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Find breadth using Pythagoras theorem:</strong><br>\r\n            In a rectangle, adjacent sides meet at 90°. Diagonal = <span class=\"math\">41 cm</span>, Length = <span class=\"math\">40 cm</span>.<br>\r\n            <span class=\"math\">Breadth² + 40² = 41²</span><br>\r\n            <span class=\"math\">b² + 1600 = 1681 ⇒ b² = 1681 − 1600 = 81 ⇒ b = √(81) = <strong>9 cm</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Calculate perimeter:</strong><br>\r\n            <span class=\"math\">Perimeter = 2(l + b) = 2(40 + 9) = 2 × 49 = <strong>98 cm</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> The perimeter of the rectangle is <strong>98 cm</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Pythagoras theorem to find breadth b = 9 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Perimeter = 2(40 + 9) = 98 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n    <div class=\"q-card\" id=\"q6_1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Draw rough sketches for the following:<br>(a) In ΔABC, BE is a median.<br>(b) In ΔPQR, PQ and PR are altitudes of the triangle.<br>(c) In ΔXYZ, YL is an altitude in the exterior of the triangle.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) In ΔABC, BE is a median:</strong><br>\n            Draw triangle ABC. Locate midpoint E on side AC such that <span class=\"math\">AE = EC</span>. Join vertex B to E. The line segment <strong>BE</strong> is the median.<br>\n            <strong>(b) In ΔPQR, PQ and PR are altitudes:</strong><br>\n            Draw a right-angled triangle PQR, right-angled at vertex P (∠P = 90°). Here, side <strong>PQ ⊥ PR</strong>, so PQ is the altitude to PR and PR is the altitude to PQ.<br>\n            <strong>(c) In ΔXYZ, YL is an altitude in the exterior:</strong><br>\n            Draw an obtuse-angled triangle XYZ where ∠X is obtuse (&gt; 90°). Produce the opposite base XZ backwards, and draw a perpendicular from vertex Y to meet the extended base at point L. The line segment <strong>YL</strong> lies in the exterior of ΔXYZ.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate description and geometric properties for each sketch</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_4_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_4_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">The lengths of two sides of a triangle are 12 cm and 15 cm. Between what two measures should the length of the third side fall?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            1. Sum of two sides = <span class=\"math\">15 cm + 12 cm = 27 cm</span>. The third side must be less than 27 cm.<br>\n            2. Difference of two sides = <span class=\"math\">15 cm − 12 cm = 3 cm</span>. The third side must be greater than 3 cm.<br>\n            Therefore, the length of the third side should fall between <strong>3 cm and 27 cm</strong>.\n          </div>\n          <p><strong>Final Answer:</strong> The third side must be greater than <strong>3 cm</strong> and less than <strong>27 cm</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating difference boundary (15 − 12 = 3 cm)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating sum boundary (15 + 12 = 27 cm)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_4_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_4_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">AM is a median of a triangle ABC. Is AB + BC + CA &gt; 2 AM? (Consider the sides of triangles ΔABM and ΔAMC).</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            In any triangle, the sum of any two sides is greater than the third side.<br>\n            1. In ΔABM: <span class=\"math\">AB + BM &gt; AM</span> ... (Equation 1)<br>\n            2. In ΔAMC: <span class=\"math\">AC + MC &gt; AM</span> ... (Equation 2)<br>\n            Adding equations (1) and (2):<br>\n            <span class=\"math\">(AB + BM) + (AC + MC) &gt; AM + AM</span><br>\n            <span class=\"math\">AB + (BM + MC) + AC &gt; 2 AM</span>.<br>\n            Since M is on BC, <span class=\"math\">BM + MC = BC</span>.<br>\n            Therefore, <span class=\"math\"><strong>AB + BC + CA &gt; 2 AM</strong></span>.<br>\n            <strong>Yes, the statement is true!</strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying inequality to ΔABM and ΔAMC</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Summing inequalities and substituting BM + MC = BC</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_4_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_4_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">ABCD is a quadrilateral. Is AB + BC + CD + DA &gt; AC + BD?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Consider the triangles formed by diagonals AC and BD:<br>\n            1. In ΔABC: <span class=\"math\">AB + BC &gt; AC</span> ... (1)<br>\n            2. In ΔADC: <span class=\"math\">CD + DA &gt; AC</span> ... (2)<br>\n            3. In ΔABD: <span class=\"math\">AB + DA &gt; BD</span> ... (3)<br>\n            4. In ΔBCD: <span class=\"math\">BC + CD &gt; BD</span> ... (4)<br>\n            Adding all four inequalities:<br>\n            <span class=\"math\">2(AB + BC + CD + DA) &gt; 2(AC + BD)</span>.<br>\n            Dividing both sides by 2:<br>\n            <span class=\"math\"><strong>AB + BC + CD + DA &gt; AC + BD</strong></span>.<br>\n            <strong>Yes, the statement is true!</strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Setting up triangle inequality for all 4 triangles</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Adding inequalities to prove statement</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_5_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_5_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Find the perimeter of the rectangle whose length is 40 cm and a diagonal is 41 cm.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Let the breadth of the rectangle be <span class=\"math\">b</span> cm.<br>\n            In a rectangle, adjacent sides and diagonal form a right-angled triangle:<br>\n            <span class=\"math\">Length² + Breadth² = Diagonal²</span><br>\n            <span class=\"math\">40² + b² = 41² ⇒ 1600 + b² = 1681 ⇒ b² = 1681 − 1600 = 81 ⇒ b = √81 = <strong>9 cm</strong></span>.<br>\n            <span class=\"math\">Perimeter of rectangle = 2(length + breadth) = 2(40 + 9) = 2(49) = <strong>98 cm</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The perimeter of the rectangle is <strong>98 cm</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Finding breadth = 9 cm using Pythagoras theorem</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Perimeter = 2(40 + 9) = 98 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_5_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_5_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">The diagonals of a rhombus measure 16 cm and 30 cm. Find its perimeter.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            The diagonals of a rhombus bisect each other at right angles (90°).<br>\n            Half of diagonals = <span class=\"math\">16/2 = 8 cm</span> and <span class=\"math\">30/2 = 15 cm</span>.<br>\n            In the right triangle formed by the half-diagonals and a side of the rhombus (<span class=\"math\">s</span>):<br>\n            <span class=\"math\">s² = 8² + 15² = 64 + 225 = 289 ⇒ s = √289 = <strong>17 cm</strong></span>.<br>\n            Since all 4 sides of a rhombus are equal:<br>\n            <span class=\"math\">Perimeter = 4 × s = 4 × 17 = <strong>68 cm</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The perimeter of the rhombus is <strong>68 cm</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Side length = 17 cm using half-diagonals</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Perimeter = 4 × 17 = 68 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n    <div class=\"q-card\" id=\"q6_1_3_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_1_3_def')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Verify by drawing a diagram if the median and altitude of an isosceles triangle can be same.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            1. Draw an isosceles triangle ΔABC where <span class=\"math\">AB = AC</span>.<br>\n            2. Draw median AD from vertex A to the midpoint D of the non-equal base BC (so <span class=\"math\">BD = DC</span>).<br>\n            3. In ΔABD and ΔACD:<br>\n            • <span class=\"math\">AB = AC</span> (given)<br>\n            • <span class=\"math\">BD = DC</span> (AD is median)<br>\n            • <span class=\"math\">AD = AD</span> (common side)<br>\n            By SSS Congruence, <span class=\"math\">\\Delta ABD \\cong \\Delta ACD</span>.<br>\n            Hence, <span class=\"math\">\\angle ADB = \\angle ADC</span> (CPCTC).<br>\n            Since they form a linear pair: <span class=\"math\">\\angle ADB + \\angle ADC = 180° ⟹ \\angle ADB = 90°</span>.<br>\n            Therefore, AD is perpendicular to BC, making AD an <strong>altitude</strong> as well.<br>\n            <strong>Conclusion:</strong> In an isosceles triangle, the median drawn to the non-equal base is identical to its altitude.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Triangle construction and congruence proof</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conclusion that median = altitude</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_2_2_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_2_2_def')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find the value of the unknown interior angle x in the following figures:<br>(i) Interior angle 50°, exterior angle 115°<br>(ii) Interior angle 70°, exterior angle 100°<br>(iii) Interior angle 90° (right angle), exterior angle 125°<br>(iv) Interior angle 60°, exterior angle 120°</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            By Exterior Angle Property: <span class=\"math\">\\text{Exterior angle} = \\text{Sum of opposite interior angles}</span>.<br><br>\n            <strong>(i)</strong> <span class=\"math\">x + 50° = 115° ⟹ x = 115° − 50° = <strong>65°</strong></span>.<br>\n            <strong>(ii)</strong> <span class=\"math\">x + 70° = 100° ⟹ x = 100° − 70° = <strong>30°</strong></span>.<br>\n            <strong>(iii)</strong> <span class=\"math\">x + 90° = 125° ⟹ x = 125° − 90° = <strong>35°</strong></span>.<br>\n            <strong>(iv)</strong> <span class=\"math\">x + 60° = 120° ⟹ x = 120° − 60° = <strong>60°</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Exterior angle theorem formula and calculation</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_3_2_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_3_2_def')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find the values of the unknowns x and y in the following diagrams:<br>(i) Interior angles 50°, x, y with exterior to y being 120°<br>(ii) Interior angles y, 50°, x with vertically opposite to y being 80°</div>\n      <div class=\"q-marks\">4 Marks (2 Marks each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong><br>\n            • Linear pair: <span class=\"math\">y + 120° = 180° ⟹ y = 180° − 120° = <strong>60°</strong></span>.<br>\n            • Angle sum property of triangle: <span class=\"math\">50° + x + y = 180°</span><br>\n            <span class=\"math\">50° + x + 60° = 180° ⟹ x = 180° − 110° = <strong>70°</strong></span>.<br>\n            So, <span class=\"math\"><strong>x = 70°, y = 60°</strong></span>.<br><br>\n            <strong>(ii)</strong><br>\n            • Vertically opposite angles: <span class=\"math\">y = <strong>80°</strong></span>.<br>\n            • Angle sum property of triangle: <span class=\"math\">50° + x + y = 180°</span><br>\n            <span class=\"math\">50° + x + 80° = 180° ⟹ x = 180° − 130° = <strong>50°</strong></span>.<br>\n            So, <span class=\"math\"><strong>x = 50°, y = 80°</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Values of x and y for part (i)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Values of x and y for part (ii)</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_5_5_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_5_5_def')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">A tree is broken at a height of 5 m from the ground and its top touches the ground at a distance of 12 m from the base of the tree. Find the original height of the tree.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Let the tree be broken at point B at height <span class=\"math\">AB = 5\\text{ m}</span>.<br>\n            Its top touches the ground at point C, so distance <span class=\"math\">AC = 12\\text{ m}</span>.<br>\n            The broken part BC forms the hypotenuse of right triangle ΔBAC.<br><br>\n            By Pythagoras theorem:<br>\n            <span class=\"math\">BC^2 = AB^2 + AC^2</span><br>\n            <span class=\"math\">BC^2 = 5^2 + 12^2 = 25 + 144 = 169</span><br>\n            <span class=\"math\">BC = \\sqrt{169} = 13\\text{ m}</span>.<br><br>\n            Original height of tree = <span class=\"math\">AB + BC = 5 + 13 = <strong>18 m</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pythagoras formula and finding hypotenuse BC = 13 m</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Total height AB + BC = 18 m</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\">\r\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\r\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\r\n    </div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">HOTS: Perimeter of Rhombus via Diagonals</div>\r\n        <div class=\"cbq-question\"><strong>Problem:</strong> The diagonals of a rhombus measure 16 cm and 30 cm. Find its perimeter.</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <p><strong>Properties of Rhombus:</strong><br>\r\n          1. Diagonals bisect each other at right angles (90°).<br>\r\n          Half of diagonal 1 = <span class=\"math\">16/2 = 8 cm</span>.<br>\r\n          Half of diagonal 2 = <span class=\"math\">30/2 = 15 cm</span>.<br>\r\n          2. In right-angled triangle formed by half-diagonals and side <span class=\"math\">s</span>:<br>\r\n          <span class=\"math\">s² = 8² + 15² = 64 + 225 = 289 ⇒ s = √(289) = <strong>17 cm</strong></span>.<br>\r\n          3. <span class=\"math\">Perimeter of rhombus = 4 × s = 4 × 17 = <strong>68 cm</strong></span>.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(5)\">← Chapter 5: Lines &amp; Angles</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(7)\">Chapter 7: Comparing Quantities →</button>\r\n  </div>\r\n</section>\r\n","7":"<section class=\"chapter-section\" id=\"ch7\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">7</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 7: Comparing Quantities</h2>\r\n      <p>NCERT Exercise 7.1 to 7.2 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"concept-card\">\r\n    <div class=\"concept-header\">📌 Key Concepts &amp; Commercial Mathematics Formulas</div>\r\n    <ul class=\"concept-list\">\r\n      <li><strong>Ratio:</strong> A comparison of two quantities of the same kind by division (a : b = a/b). Both quantities must have the same unit.</li>\r\n      <li><strong>Percentage:</strong> Ratios with denominator 100.\r\n        <ul>\r\n          <li>Fraction/Decimal to % ⇒ Multiply by 100%.</li>\r\n          <li>%  to Fraction/Decimal ⇒ Divide by 100.</li>\r\n        </ul>\r\n      </li>\r\n      <li><strong>Percentage Change:</strong>\r\n        Percentage Increase / Decrease = (Amount of change)/(Original value) × 100%\r\n      </li>\r\n      <li><strong>Profit and Loss:</strong>\r\n        <ul>\r\n          <li>When SP > CP ⇒ Profit = SP - CP; Profit  % = Profit/CP × 100%.</li>\r\n          <li>When CP > SP ⇒ Loss = CP - SP; Loss  % = Loss/CP × 100%.</li>\r\n        </ul>\r\n      </li>\r\n      <li><strong>Simple Interest:</strong>\r\n        SI = (P × R × T)/100,   Total Amount  A = P + SI\r\n        where P = Principal (sum borrowed/invested), R = Rate of interest per annum, T = Time in years.\r\n      </li>\r\n    </ul>\r\n  </div>\r\n\r\n  <!-- EXERCISE 7.1 -->\r\n  <div class=\"ex-div\">Exercise 7.1 (Ratios &amp; Percentages)</div>\r\n\r\n  <div class=\"q-card\" id=\"q7_1_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Find the ratio of:<br>(a) ₹5 to 50 paise<br>(b) 15 kg to 210 g<br>(c) 9 m to 27 cm<br>(d) 30 days to 36 hours</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) ₹5 to 50 paise:</strong><br>\r\n            Convert to paise: <span class=\"math\">₹5 = 5 × 100 = 500 paise</span>.<br>\r\n            Ratio = <span class=\"math\">500/50 = 10/1 = <strong>10 : 1</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) 15 kg to 210 g:</strong><br>\r\n            Convert to grams: <span class=\"math\">15 kg = 15 × 1000 = 15000 g</span>.<br>\r\n            Ratio = <span class=\"math\">15000/210 = 1500/21 = 500/7 = <strong>500 : 7</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) 9 m to 27 cm:</strong><br>\r\n            Convert to cm: <span class=\"math\">9 m = 900 cm</span>.<br>\r\n            Ratio = <span class=\"math\">900/27 = 100/3 = <strong>100 : 3</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(d) 30 days to 36 hours:</strong><br>\r\n            Convert to hours: <span class=\"math\">30 days = 30 × 24 = 720 hours</span>.<br>\r\n            Ratio = <span class=\"math\">720/36 = 20/1 = <strong>20 : 1</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Unit conversions done accurately</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">All ratios simplified to lowest terms</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q7_1_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">In a computer lab, there are 3 computers for every 6 students. How many computers will be needed for 24 students?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Unitary Method:</strong><br>\r\n            Computers required for 6 students = 3.<br>\r\n            Computers required for 1 student = <span class=\"math\">3/6 = 1/2</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            Computers required for 24 students = <span class=\"math\">24 × 1/2 = <strong>12 computers</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> Exactly <strong>12 computers</strong> will be needed for 24 students.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Rate for 1 student = 3/6 = 1/2</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Total computers = 24 × 1/2 = 12</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q7_1_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">Convert the given fractional numbers to per cents:<br>(a) 1/8<br>(b) 5/4<br>(c) 3/40<br>(d) 2/7</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) <span class=\"math\">1/8 × 100% = 25/2% = <strong>12.5%</strong> = <strong>12 1/2%</strong></span></strong><br>\r\n            <strong>(b) <span class=\"math\">5/4 × 100% = 5 × 25% = <strong>125%</strong></span></strong><br>\r\n            <strong>(c) <span class=\"math\">3/40 × 100% = 15/2% = <strong>7.5%</strong></span></strong><br>\r\n            <strong>(d) <span class=\"math\">2/7 × 100% = 200/7% = <strong>28 4/7%</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each fraction converted to %</span><span class=\"marking-marks\">0.5 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q7_1_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_4')\">\r\n      <div class=\"q-num\">Q4</div>\r\n      <div class=\"q-text\">Find:<br>(a) 15% of 250<br>(b) 1% of 1 hour<br>(c) 20% of ₹2500<br>(d) 75% of 1 kg</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) <span class=\"math\">15%  of  250 = 15/100 × 250 = (15 × 5)/2 = 75/2 = <strong>37.5</strong></span></strong><br>\r\n            <strong>(b) <span class=\"math\">1%  of  1 hour = 1/100 × 60 min = (60 × 60)/100 sec = <strong>36 seconds</strong></span></strong><br>\r\n            <strong>(c) <span class=\"math\">20%  of  ₹2500 = 20/100 × 2500 = 20 × 25 = <strong>₹500</strong></span></strong><br>\r\n            <strong>(d) <span class=\"math\">75%  of  1 kg = 75/100 × 1000 g = 75 × 10 = <strong>750 g</strong> = <strong>0.75 kg</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct percentage evaluation</span><span class=\"marking-marks\">0.5 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 7.2 -->\r\n  <div class=\"ex-div\">Exercise 7.2 (Profit &amp; Loss, Simple Interest)</div>\r\n\r\n  <div class=\"q-card\" id=\"q7_2_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_2_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Tell what is the profit or loss in the following transactions. Also find profit per cent or loss per cent in each case:<br>(a) Gardening shears bought for ₹250 and sold for ₹325.<br>(b) A refrigerator bought for ₹12,000 and sold at ₹13,500.<br>(c) A cupboard bought for ₹2,500 and sold at ₹3,000.<br>(d) A skirt bought for ₹250 and sold at ₹150.</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) Gardening shears:</strong><br>\r\n            <span class=\"math\">CP = ₹250, SP = ₹325</span>. Since <span class=\"math\">SP > CP</span>, there is a profit.<br>\r\n            <span class=\"math\">Profit = 325 − 250 = <strong>₹75</strong></span>.<br>\r\n            <span class=\"math\">Profit  % = 75/250 × 100 = 3/10 × 100 = <strong>30%</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) Refrigerator:</strong><br>\r\n            <span class=\"math\">CP = ₹12,000, SP = ₹13,500</span>. Profit.<br>\r\n            <span class=\"math\">Profit = 13500 − 12000 = <strong>₹1,500</strong></span>.<br>\r\n            <span class=\"math\">Profit  % = 1500/12000 × 100 = 150/12 = <strong>12.5%</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) Cupboard:</strong><br>\r\n            <span class=\"math\">CP = ₹2,500, SP = ₹3,000</span>. Profit.<br>\r\n            <span class=\"math\">Profit = 3000 − 2500 = <strong>₹500</strong></span>.<br>\r\n            <span class=\"math\">Profit  % = 500/2500 × 100 = 1/5 × 100 = <strong>20%</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(d) Skirt:</strong><br>\r\n            <span class=\"math\">CP = ₹250, SP = ₹150</span>. Since <span class=\"math\">CP > SP</span>, there is a loss.<br>\r\n            <span class=\"math\">Loss = 250 − 150 = <strong>₹100</strong></span>.<br>\r\n            <span class=\"math\">Loss  % = 100/250 × 100 = 2/5 × 100 = <strong>40%</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part: Profit/Loss calculation (0.5 Mark) + % calculation (0.5 Mark)</span><span class=\"marking-marks\">1 Mark each (4 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q7_2_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_2_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Find the amount to be paid at the end of 3 years in each case:<br>(a) Principal = ₹1,200 at 12% p.a.<br>(b) Principal = ₹7,500 at 5% p.a.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) P = ₹1,200, R = 12% p.a., T = 3 years:</strong><br>\r\n            <span class=\"math\">SI = (P × R × T)/100 = (1200 × 12 × 3)/100 = 12 × 36 = <strong>₹432</strong></span>.<br>\r\n            <span class=\"math\">Amount = P + SI = ₹1200 + ₹432 = <strong>₹1,632</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) P = ₹7,500, R = 5% p.a., T = 3 years:</strong><br>\r\n            <span class=\"math\">SI = (P × R × T)/100 = (7500 × 5 × 3)/100 = 75 × 15 = <strong>₹1,125</strong></span>.<br>\r\n            <span class=\"math\">Amount = P + SI = ₹7500 + ₹1125 = <strong>₹8,625</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): SI = ₹432, Amount = ₹1,632</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): SI = ₹1,125, Amount = ₹8,625</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q7_2_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q7_2_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">What rate gives ₹280 as interest on a sum of ₹56,000 in 2 years?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Given:</strong><br>\r\n            <span class=\"math\">SI = ₹280</span>, <span class=\"math\">P = ₹56,000</span>, <span class=\"math\">T = 2 years</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Formula for Rate:</strong><br>\r\n            <span class=\"math\">R = (SI × 100)/(P × T) = (280 × 100)/(56000 × 2) = 28000/112000 = 28/112 = 1/4% = <strong>0.25%</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> The rate of interest is <strong>0.25% (or ¼%) per annum</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula R = (SI × 100) / (P × T)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">R = 0.25% p.a. with statement</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n    <div class=\"q-card\" id=\"q7_1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Find the whole quantity if:<br>(a) 5% of it is 600<br>(b) 12% of it is ₹1080<br>(c) 40% of it is 500 km<br>(d) 70% of it is 14 minutes<br>(e) 8% of it is 40 litres</div>\n      <div class=\"q-marks\">5 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Let the whole quantity be <span class=\"math\">x</span>:<br>\n            <strong>(a)</strong> <span class=\"math\">5% of x = 600 ⇒ (5/100) × x = 600 ⇒ x = (600 × 100) / 5 = <strong>12,000</strong></span>.<br>\n            <strong>(b)</strong> <span class=\"math\">12% of x = ₹1080 ⇒ x = (1080 × 100) / 12 = <strong>₹9,000</strong></span>.<br>\n            <strong>(c)</strong> <span class=\"math\">40% of x = 500 km ⇒ x = (500 × 100) / 40 = <strong>1250 km</strong></span>.<br>\n            <strong>(d)</strong> <span class=\"math\">70% of x = 14 min ⇒ x = (14 × 100) / 70 = <strong>20 minutes</strong></span>.<br>\n            <strong>(e)</strong> <span class=\"math\">8% of x = 40 L ⇒ x = (40 × 100) / 8 = <strong>500 litres</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct algebraic calculation with units</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_1_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">Out of 15,000 voters in a constituency, 60% voted. Find the percentage of voters who did not vote. Can you now find how many actually did not vote?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Total number of voters = 15,000.<br>\n            Percentage of voters who voted = 60%.<br>\n            Percentage of voters who did not vote = <span class=\"math\">100% − 60% = <strong>40%</strong></span>.<br>\n            Number of voters who did not vote = <span class=\"math\">40% of 15,000 = (40 / 100) × 15,000 = 40 × 150 = <strong>6,000 voters</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> <strong>40%</strong> of voters did not vote, which corresponds to <strong>6,000 voters</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Percentage calculation: 100% − 60% = 40%</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Total count: (40/100) × 15000 = 6000 voters</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_2_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_2_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">What rate gives ₹280 as interest on a sum of ₹56,000 in 2 years?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Principal (<span class=\"math\">P</span>) = ₹56,000.<br>\n            Simple Interest (<span class=\"math\">I</span>) = ₹280.<br>\n            Time (<span class=\"math\">T</span>) = 2 years.<br>\n            Formula: <span class=\"math\">I = (P × R × T) / 100 ⇒ R = (I × 100) / (P × T)</span>.<br>\n            <span class=\"math\">R = (280 × 100) / (56,000 × 2) = 28,000 / 1,12,000 = 28 / 112 = 1 / 4 = <strong>0.25% per annum</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The rate of interest is <strong>0.25% p.a.</strong> (or 1/4% p.a.).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula: R = (I × 100) / (P × T)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation: R = 0.25% per annum</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_1_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">In a city, 30% are females, 40% are males and remaining are children. What per cent are children?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Total percentage of population = 100%.<br>\n            Percentage of females = 30%.<br>\n            Percentage of males = 40%.<br>\n            Total percentage of adults = <span class=\"math\">30% + 40% = 70%</span>.<br>\n            Percentage of children = <span class=\"math\">100% − 70% = <strong>30%</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> <strong>30%</strong> of the city's population are children.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formulation: 100% − (30% + 40%)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final answer: 30%</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_1_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">Meeta saves ₹4000 from her salary. If this is 10% of her salary, what is her salary?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Let Meeta's salary be <span class=\"math\">₹S</span>.<br>\n            Given: <span class=\"math\">10% of S = ₹4000</span>.<br>\n            <span class=\"math\">(10 / 100) × S = 4000 ⇒ S = (4000 × 100) / 10 = 4000 × 10 = <strong>₹40,000</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> Meeta's salary is <strong>₹40,000</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Equation setup: (10/100) × S = 4000</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation: S = ₹40,000</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_1_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">A local cricket team played 20 matches in one season. It won 25% of them. How many matches did they win?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Total matches played = 20.<br>\n            Percentage of matches won = 25%.<br>\n            Number of matches won = <span class=\"math\">25% of 20 = (25 / 100) × 20 = (1 / 4) × 20 = <strong>5 matches</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The cricket team won <strong>5 matches</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formulation: (25/100) × 20</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Answer: 5 matches</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_2_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_2_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Arun bought a car for ₹3,50,000. The next year, the price went upto ₹3,70,000. What was the percentage of price increase?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Original price = ₹3,50,000.<br>\n            Increased price = ₹3,70,000.<br>\n            Increase in price = <span class=\"math\">₹3,70,000 − ₹3,50,000 = ₹20,000</span>.<br>\n            <span class=\"math\">Percentage increase = (Increase / Original price) × 100% = (20,000 / 3,50,000) × 100% = 200 / 35 = 40 / 7 = <strong>5 5/7% ≈ 5.71%</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The percentage increase in price is <strong>5 5/7%</strong> (or <strong>5.71%</strong>).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Increase value: ₹20,000</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Percentage: 5 5/7%</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_2_11\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_2_11')\">\n      <div class=\"q-num\">Q11</div>\n      <div class=\"q-text\">If Meena gives an interest of ₹45 for one year at 9% rate p.a., what is the sum she has borrowed?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Simple Interest (<span class=\"math\">I</span>) = ₹45.<br>\n            Time (<span class=\"math\">T</span>) = 1 year.<br>\n            Rate (<span class=\"math\">R</span>) = 9% p.a.<br>\n            Formula: <span class=\"math\">I = (P × R × T) / 100 ⇒ P = (I × 100) / (R × T)</span>.<br>\n            <span class=\"math\">P = (45 × 100) / (9 × 1) = 5 × 100 = <strong>₹500</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The sum borrowed by Meena is <strong>₹500</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula: P = (I × 100) / (R × T)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation: P = ₹500</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_2_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_2_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">Find the amount to be paid at the end of 3 years in each case:<br>(a) Principal = ₹ 1,200 at 12% p.a.<br>(b) Principal = ₹ 7,500 at 5% p.a.</div>\n      <div class=\"q-marks\">4 Marks (2 Marks each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a)</strong> Given: <span class=\"math\">P = ₹ 1,200</span>, <span class=\"math\">R = 12\\%</span> per annum, <span class=\"math\">T = 3</span> years.<br>\n            Simple Interest (<span class=\"math\">I</span>) = <span class=\"math\">(P × R × T) / 100 = (1200 × 12 × 3) / 100 = 12 × 36 = ₹ 432</span>.<br>\n            Amount = <span class=\"math\">P + I = 1200 + 432 = <strong>₹ 1,632</strong></span>.<br><br>\n            <strong>(b)</strong> Given: <span class=\"math\">P = ₹ 7,500</span>, <span class=\"math\">R = 5\\%</span> per annum, <span class=\"math\">T = 3</span> years.<br>\n            Simple Interest (<span class=\"math\">I</span>) = <span class=\"math\">(7500 × 5 × 3) / 100 = 75 × 15 = ₹ 1,125</span>.<br>\n            Amount = <span class=\"math\">P + I = 7500 + 1125 = <strong>₹ 8,625</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of Simple Interest (Formula + steps)</span><span class=\"marking-marks\">1 Mark each part</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of final Amount (P + I)</span><span class=\"marking-marks\">1 Mark each part</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_2_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_2_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">What rate gives ₹ 280 as interest on a sum of ₹ 56,000 in 2 years?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Given:<br>\n            Simple Interest (<span class=\"math\">I</span>) = ₹ 280<br>\n            Principal (<span class=\"math\">P</span>) = ₹ 56,000<br>\n            Time period (<span class=\"math\">T</span>) = 2 years<br><br>\n            Formula: <span class=\"math\">I = (P × R × T) / 100</span><br>\n            <span class=\"math\">280 = (56000 × R × 2) / 100</span><br>\n            <span class=\"math\">280 = 560 × 2 × R</span><br>\n            <span class=\"math\">280 = 1120 × R</span><br>\n            <span class=\"math\">R = 280 / 1120 = 1 / 4 = <strong>0.25%</strong></span> per annum.<br>\n            Hence, the required rate of interest is <strong>0.25% p.a.</strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution of values in Simple Interest formula</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct evaluation of Rate R = 0.25%</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n    <div class=\"q-card\" id=\"q7_1_3_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_3_def')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Estimate what part of the figures is coloured and hence find the per cent which is coloured:<br>(i) 1 part out of 4 is coloured<br>(ii) 3 parts out of 5 are coloured<br>(iii) 3 parts out of 8 are coloured</div>\n      <div class=\"q-marks\">3 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> Coloured part = <span class=\"math\">1/4</span>.<br>\n            Percentage = <span class=\"math\">\\frac{1}{4} × 100\\% = <strong>25%</strong></span>.<br><br>\n            <strong>(ii)</strong> Coloured part = <span class=\"math\">3/5</span>.<br>\n            Percentage = <span class=\"math\">\\frac{3}{5} × 100\\% = 3 × 20\\% = <strong>60%</strong></span>.<br><br>\n            <strong>(iii)</strong> Coloured part = <span class=\"math\">3/8</span>.<br>\n            Percentage = <span class=\"math\">\\frac{3}{8} × 100\\% = \\frac{75}{2}\\% = <strong>37.5%</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Fraction identification and percentage conversion</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_1_4_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_4_def')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Find:<br>(a) 15% of 250 &nbsp;&nbsp; (b) 1% of 1 hour &nbsp;&nbsp; (c) 20% of ₹ 2500 &nbsp;&nbsp; (d) 75% of 1 kg</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a)</strong> <span class=\"math\">\\frac{15}{100} × 250 = \\frac{15 × 5}{2} = \\frac{75}{2} = <strong>37.5</strong></span>.<br>\n            <strong>(b)</strong> 1 hour = 60 minutes = 3600 seconds.<br>\n            <span class=\"math\">\\frac{1}{100} × 60\\text{ min} = \\frac{3}{5}\\text{ min} = \\frac{3}{5} × 60\\text{ sec} = <strong>36 seconds</strong></span>.<br>\n            <strong>(c)</strong> <span class=\"math\">\\frac{20}{100} × ₹ 2500 = 20 × 25 = <strong>₹ 500</strong></span>.<br>\n            <strong>(d)</strong> 1 kg = 1000 g.<br>\n            <span class=\"math\">\\frac{75}{100} × 1000\\text{ g} = 75 × 10 = <strong>750 g (or 0.75 kg)</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation for each percentage evaluation</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_1_6_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1_6_def')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Convert given per cents to decimal fractions and also to fractions in simplest forms:<br>(a) 25% &nbsp;&nbsp; (b) 150% &nbsp;&nbsp; (c) 20% &nbsp;&nbsp; (d) 5%</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) 25%:</strong><br>\n            • Decimal: <span class=\"math\">25 / 100 = <strong>0.25</strong></span>.<br>\n            • Simplest fraction: <span class=\"math\">25 / 100 = <strong>1/4</strong></span>.<br><br>\n            <strong>(b) 150%:</strong><br>\n            • Decimal: <span class=\"math\">150 / 100 = <strong>1.5</strong></span>.<br>\n            • Simplest fraction: <span class=\"math\">150 / 100 = <strong>3/2 = 1 ½</strong></span>.<br><br>\n            <strong>(c) 20%:</strong><br>\n            • Decimal: <span class=\"math\">20 / 100 = <strong>0.2</strong></span>.<br>\n            • Simplest fraction: <span class=\"math\">20 / 100 = <strong>1/5</strong></span>.<br><br>\n            <strong>(d) 5%:</strong><br>\n            • Decimal: <span class=\"math\">5 / 100 = <strong>0.05</strong></span>.<br>\n            • Simplest fraction: <span class=\"math\">5 / 100 = <strong>1/20</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Decimal and simplest fraction form for each part</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\">\r\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\r\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\r\n    </div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">Case Study: Population Growth &amp; Depreciation</div>\r\n        <div class=\"cbq-question\"><strong>Scenario:</strong> The population of a city decreased from 25,000 to 24,500. (i) Find the percentage decrease in population. (ii) If the population decreases by the same percentage next year, what will the new population be?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <p><strong>(i) Percentage decrease:</strong><br>\r\n          Original population = <span class=\"math\">25,000</span>.<br>\r\n          Decrease = <span class=\"math\">25,000 − 24,500 = 500</span>.<br>\r\n          <span class=\"math\">Percentage Decrease = 500/25000 × 100% = 50/25% = <strong>2%</strong></span>.</p>\r\n          <p><strong>(ii) Next year's population:</strong><br>\r\n          Decrease next year = <span class=\"math\">2%  of  24,500 = 2/100 × 24500 = 490</span>.<br>\r\n          New population = <span class=\"math\">24,500 − 490 = <strong>24,010</strong></span>.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(6)\">← Chapter 6: Triangle &amp; its Properties</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(8)\">Chapter 8: Rational Numbers →</button>\r\n  </div>\r\n</section>\r\n","8":"<section class=\"chapter-section\" id=\"ch8\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">8</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 8: Rational Numbers</h2>\r\n      <p>NCERT Exercise 8.1 to 8.2 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"concept-card\">\r\n    <div class=\"concept-header\">📌 Key Concepts &amp; Properties Summary</div>\r\n    <ul class=\"concept-list\">\r\n      <li><strong>Rational Number:</strong> A number that can be written in the form p/q, where p and q are integers and q ≠ 0.\r\n        <ul>\r\n          <li><em>Positive:</em> Both p and q have the same sign (e.g. 2/3, (-5)/(-7)).</li>\r\n          <li><em>Negative:</em> p and q have opposite signs (e.g. (-3)/8, 5/(-9)).</li>\r\n          <li>0 is a rational number since 0 = 0/1.</li>\r\n        </ul>\r\n      </li>\r\n      <li><strong>Standard Form:</strong> A rational number p/q is in standard form if q > 0 and p, q have no common factor other than 1.</li>\r\n      <li><strong>Equivalent Rational Numbers:</strong> Obtained by multiplying or dividing numerator and denominator by the same non-zero integer:\r\n        p/q = (p × m)/(q × m)\r\n      </li>\r\n      <li><strong>Density Property:</strong> Between any two rational numbers, there exist infinitely many rational numbers.</li>\r\n      <li><strong>Operations on Rational Numbers:</strong>\r\n        <ul>\r\n          <li><em>Addition/Subtraction:</em> Take LCM of denominators and adjust numerators accordingly.</li>\r\n          <li><em>Multiplication:</em> a/b × c/d = (a × c)/(b × d).</li>\r\n          <li><em>Division:</em> a/b ÷ c/d = a/b × d/c (multiplication by reciprocal of divisor).</li>\r\n        </ul>\r\n      </li>\r\n    </ul>\r\n  </div>\r\n\r\n  <!-- EXERCISE 8.1 -->\r\n  <div class=\"ex-div\">Exercise 8.1</div>\r\n\r\n  <div class=\"q-card\" id=\"q8_1_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_1_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">List five rational numbers between:<br>(i) −1 and 0<br>(ii) −2 and −1<br>(iii) −4/5 and −2/3<br>(iv) −1/2 and 2/3</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) Between −1 and 0:</strong><br>\r\n            Multiply numerator and denominator by <span class=\"math\">5 + 1 = 6</span>:<br>\r\n            <span class=\"math\">−1 = -6/6</span>, &nbsp; <span class=\"math\">0 = 0/6</span>.<br>\r\n            Five rational numbers: <span class=\"math\"><strong>-5/6, -4/6, -3/6, -2/6, -1/6</strong></span><br>\r\n            (Simplified: <span class=\"math\">-5/6, -2/3, -1/2, -1/3, -1/6</span>).\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) Between −2 and −1:</strong><br>\r\n            Multiply by 6:<br>\r\n            <span class=\"math\">−2 = -12/6</span>, &nbsp; <span class=\"math\">−1 = -6/6</span>.<br>\r\n            Five rational numbers: <span class=\"math\"><strong>-11/6, -10/6, -9/6, -8/6, -7/6</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) Between −4/5 and −2/3:</strong><br>\r\n            LCM of 5 and 3 is 15. Make denominators equal to <span class=\"math\">15 × 3 = 45</span>:<br>\r\n            <span class=\"math\">-4/5 = -36/45</span>, &nbsp; <span class=\"math\">-2/3 = -30/45</span>.<br>\r\n            Five rational numbers: <span class=\"math\"><strong>-35/45, -34/45, -33/45, -32/45, -31/45</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iv) Between −1/2 and 2/3:</strong><br>\r\n            LCM of 2 and 3 is 6. Multiply by 2 ⇒ denominator 12:<br>\r\n            <span class=\"math\">-1/2 = -6/12</span>, &nbsp; <span class=\"math\">2/3 = 8/12</span>.<br>\r\n            Five rational numbers: <span class=\"math\"><strong>-5/12, -4/12, 0, 1/12, 5/12</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part: Finding suitable common denominator &amp; listing 5 rationals</span><span class=\"marking-marks\">1 Mark each (4 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q8_1_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_1_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Rewrite the following rational numbers in the simplest (standard) form:<br>(i) −8/6<br>(ii) 25/45<br>(iii) −44/72<br>(iv) −8/10</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p>Divide numerator and denominator by their HCF:</p>\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">-8/6</span>:</strong><br>\r\n            HCF of 8 and 6 is 2: <span class=\"math\">-(8 ÷ 2)/(6 ÷ 2) = <strong>-4/3</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) <span class=\"math\">25/45</span>:</strong><br>\r\n            HCF of 25 and 45 is 5: <span class=\"math\">(25 ÷ 5)/(45 ÷ 5) = <strong>5/9</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) <span class=\"math\">-44/72</span>:</strong><br>\r\n            HCF of 44 and 72 is 4: <span class=\"math\">-(44 ÷ 4)/(72 ÷ 4) = <strong>-11/18</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iv) <span class=\"math\">-8/10</span>:</strong><br>\r\n            HCF of 8 and 10 is 2: <span class=\"math\">-(8 ÷ 2)/(10 ÷ 2) = <strong>-4/5</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct reduction to simplest standard form</span><span class=\"marking-marks\">0.5 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q8_1_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_1_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">Which is greater in each of the following?<br>(i) 2/3, 5/2<br>(ii) −5/6, −4/3<br>(iii) −3/4, 2/−3<br>(iv) −3 2/7, −3 4/5</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) 2/3 and 5/2:</strong><br>\r\n            LCM = 6: <span class=\"math\">2/3 = 4/6</span>, <span class=\"math\">5/2 = 15/6</span>.<br>\r\n            Since <span class=\"math\">15 > 4 ⇒ <strong>5/2 > 2/3</strong></span>. (Also 5/2 &gt; 1 while 2/3 &lt; 1).\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) −5/6 and −4/3:</strong><br>\r\n            LCM = 6: <span class=\"math\">-5/6</span>, <span class=\"math\">-4/3 = -8/6</span>.<br>\r\n            On the number line, <span class=\"math\">−5 > −8</span>. Hence, <span class=\"math\"><strong>-5/6 > -4/3</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) −3/4 and 2/−3:</strong><br>\r\n            In standard form: <span class=\"math\">-3/4</span> and <span class=\"math\">-2/3</span>.<br>\r\n            LCM = 12: <span class=\"math\">-3/4 = -9/12</span>, <span class=\"math\">-2/3 = -8/12</span>.<br>\r\n            Since <span class=\"math\">−8 > −9 ⇒ <strong>2/(−3) > -3/4</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iv) −3 2/7 and −3 4/5:</strong><br>\r\n            <span class=\"math\">-3 2/7 = -23/7 = -115/35</span>.<br>\r\n            <span class=\"math\">-3 4/5 = -19/5 = -133/35</span>.<br>\r\n            Since <span class=\"math\">−115 > −133 ⇒ <strong>-3 2/7 > -3 4/5</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Converting to common denominator and comparing numerators</span><span class=\"marking-marks\">3 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 8.2 -->\r\n  <div class=\"ex-div\">Exercise 8.2 (Operations on Rational Numbers)</div>\r\n\r\n  <div class=\"q-card\" id=\"q8_2_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_2_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Find the sum:<br>(i) 5/4 + (−11/4)<br>(ii) 5/3 + 3/5<br>(iii) −9/10 + 22/15<br>(iv) −3/−11 + 5/9<br>(v) −8/19 + (−2/57)<br>(vi) −2⅓ + 4⅗</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">5/4 + (-11/4) = (5 − 11)/4 = (−6)/4 = <strong>-3/2</strong> = <strong>-1 1/2</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) <span class=\"math\">5/3 + 3/5</span>:</strong> LCM = 15.<br>\r\n            <span class=\"math\">= (5 × 5 + 3 × 3)/15 = (25 + 9)/15 = <strong>34/15</strong> = <strong>2 4/15</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) <span class=\"math\">-9/10 + 22/15</span>:</strong> LCM = 30.<br>\r\n            <span class=\"math\">= (−9 × 3 + 22 × 2)/30 = (−27 + 44)/30 = <strong>17/30</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iv) <span class=\"math\">(−3)/(−11) + 5/9 = 3/11 + 5/9</span>:</strong> LCM = 99.<br>\r\n            <span class=\"math\">= (3 × 9 + 5 × 11)/99 = (27 + 55)/99 = <strong>82/99</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(v) <span class=\"math\">-8/19 + (-2/57)</span>:</strong> LCM = 57.<br>\r\n            <span class=\"math\">= (−8 × 3 − 2)/57 = (−24 − 2)/57 = <strong>-26/57</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(vi) <span class=\"math\">-2 1/3 + 4 3/5 = -7/3 + 23/5</span>:</strong> LCM = 15.<br>\r\n            <span class=\"math\">= (−7 × 5 + 23 × 3)/15 = (−35 + 69)/15 = <strong>34/15</strong> = <strong>2 4/15</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct fraction addition with LCM steps</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q8_2_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_2_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Find the product:<br>(i) 9/2 × (−7/4)<br>(ii) 3/10 × (−9)<br>(iii) −6/5 × 9/11<br>(iv) 3/7 × (−2/5)<br>(v) 3/−5 × (−5/3)</div>\r\n      <div class=\"q-marks\">2.5 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">9/2 × (-7/4) = (9 × (−7))/(2 × 4) = <strong>-63/8</strong> = <strong>-7 7/8</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) <span class=\"math\">3/10 × (−9) = (3 × (−9))/10 = <strong>-27/10</strong> = <strong>-2 7/10</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) <span class=\"math\">-6/5 × 9/11 = (−6 × 9)/(5 × 11) = <strong>-54/55</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iv) <span class=\"math\">3/7 × (-2/5) = (3 × (−2))/(7 × 5) = <strong>-6/35</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(v) <span class=\"math\">3/(−5) × (-5/3) = (−3)/5 × (−5)/3 = ((−3) × (−5))/(5 × 3) = 15/15 = <strong>1</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Multiplying numerators and denominators with correct signs</span><span class=\"marking-marks\">0.5 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q8_2_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q8_2_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">Find the value of:<br>(i) (−4) ÷ 2/3<br>(ii) −3/5 ÷ 2<br>(iii) −4/5 ÷ (−3)<br>(iv) −1/8 ÷ 3/4<br>(v) −2/13 ÷ 1/7<br>(vi) −7/12 ÷ (−2/13)</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p>Multiply the first number by the reciprocal of the divisor:</p>\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">(−4) ÷ 2/3 = (−4) × 3/2 = −2 × 3 = <strong>−6</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) <span class=\"math\">-3/5 ÷ 2 = -3/5 × 1/2 = <strong>-3/10</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) <span class=\"math\">-4/5 ÷ (−3) = -4/5 × (-1/3) = <strong>4/15</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iv) <span class=\"math\">-1/8 ÷ 3/4 = -1/8 × 4/3 = <strong>-1/6</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(v) <span class=\"math\">-2/13 ÷ 1/7 = -2/13 × 7/1 = <strong>-14/13</strong> = <strong>-1 1/13</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(vi) <span class=\"math\">-7/12 ÷ (-2/13) = -7/12 × (-13/2) = <strong>91/24</strong> = <strong>3 19/24</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Reciprocal inversion &amp; accurate evaluation</span><span class=\"marking-marks\">0.5 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n    <div class=\"q-card\" id=\"q8_1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Draw the number line and represent the following rational numbers on it:<br>(i) 3/4 &nbsp;&nbsp; (ii) −5/8 &nbsp;&nbsp; (iii) −7/4 &nbsp;&nbsp; (iv) 7/8</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) 3/4:</strong> Lies between 0 and 1. Divide unit distance between 0 and 1 into 4 equal parts. The 3rd mark to the right of 0 represents <span class=\"math\"><strong>3/4</strong></span>.<br>\n            <strong>(ii) −5/8:</strong> Lies between 0 and −1. Divide unit distance between 0 and −1 into 8 equal parts. The 5th mark to the left of 0 represents <span class=\"math\"><strong>−5/8</strong></span>.<br>\n            <strong>(iii) −7/4:</strong> Note <span class=\"math\">−7/4 = −1 3/4</span>. Lies between −1 and −2. Divide unit distance between −1 and −2 into 4 equal parts. The 3rd mark to the left of −1 represents <span class=\"math\"><strong>−7/4</strong></span>.<br>\n            <strong>(iv) 7/8:</strong> Lies between 0 and 1. Divide distance between 0 and 1 into 8 equal parts. The 7th mark to the right of 0 represents <span class=\"math\"><strong>7/8</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct number line division and point plotting</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q8_1_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_1_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Which of the following pairs represent the same rational number?<br>(i) −7/21 and 3/9<br>(ii) −16/20 and 20/−25<br>(iii) −2/−3 and 2/3<br>(iv) −3/5 and −12/20</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Reduce each fraction to its standard simplest form:<br>\n            <strong>(i)</strong> <span class=\"math\">−7/21 = −1/3</span> and <span class=\"math\">3/9 = 1/3</span>. Since <span class=\"math\">−1/3 ≠ 1/3</span>, they <strong>do not represent the same rational number</strong>.<br>\n            <strong>(ii)</strong> <span class=\"math\">−16/20 = −4/5</span> and <span class=\"math\">20/−25 = −4/5</span>. Since <span class=\"math\">−4/5 = −4/5</span>, they <strong>represent the same rational number</strong>.<br>\n            <strong>(iii)</strong> <span class=\"math\">−2/−3 = 2/3</span>. Both are equal to <span class=\"math\">2/3</span>. They <strong>represent the same rational number</strong>.<br>\n            <strong>(iv)</strong> <span class=\"math\">−12/20 = −3/5</span>. Both are equal to <span class=\"math\">−3/5</span>. They <strong>represent the same rational number</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Simplest form reduction and comparison for each pair</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q8_1_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_1_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">Fill in the boxes with the correct symbol out of &lt;, &gt;, and =:<br>(i) −5/7 [ ] 2/3<br>(ii) −4/5 [ ] −5/7<br>(iii) −7/8 [ ] 14/−16<br>(iv) −8/5 [ ] −7/4</div>\n      <div class=\"q-marks\">2 Marks (1/2 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> Negative is always less than positive: <span class=\"math\">−5/7 <strong>&lt;</strong> 2/3</span>.<br>\n            <strong>(ii)</strong> Common denominator 35: <span class=\"math\">−4/5 = −28/35</span> and <span class=\"math\">−5/7 = −25/35</span>. Since <span class=\"math\">−28 &lt; −25</span>: <span class=\"math\">−4/5 <strong>&lt;</strong> −5/7</span>.<br>\n            <strong>(iii)</strong> <span class=\"math\">14/−16 = −7/8</span>. Therefore: <span class=\"math\">−7/8 <strong>=</strong> 14/−16</span>.<br>\n            <strong>(iv)</strong> Common denominator 20: <span class=\"math\">−8/5 = −32/20</span> and <span class=\"math\">−7/4 = −35/20</span>. Since <span class=\"math\">−32 &gt; −35</span>: <span class=\"math\">−8/5 <strong>&gt;</strong> −7/4</span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct relational symbol with mathematical justification</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q8_1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">The points P, Q, R, S, T, U, A and B on the number line are such that, TR = RS = SC and AP = PQ = QB. Name the rational numbers represented by P, Q, R and S.</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            On the number line:<br>\n            The distance between 2 (A) and 3 (B) is divided into 3 equal parts: AP = PQ = QB = 1/3.<br>\n            Therefore:<br>\n            • Point P = <span class=\"math\">2 + 1/3 = 6/3 + 1/3 = <strong>7/3</strong></span><br>\n            • Point Q = <span class=\"math\">2 + 2/3 = 6/3 + 2/3 = <strong>8/3</strong></span><br><br>\n            Similarly, the distance between −1 (T) and −2 (U) is divided into 3 equal parts: TR = RS = SU = 1/3.<br>\n            Moving leftwards from −1:<br>\n            • Point R = <span class=\"math\">−1 − 1/3 = −3/3 − 1/3 = <strong>−4/3</strong></span><br>\n            • Point S = <span class=\"math\">−1 − 2/3 = −3/3 − 2/3 = <strong>−5/3</strong></span>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct rational representation for P, Q, R, S</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n    <div class=\"q-card\" id=\"q8_1_7_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_1_7_def')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Rewrite the following rational numbers in the simplest form:<br>(i) −8/6 &nbsp;&nbsp; (ii) 25/45 &nbsp;&nbsp; (iii) −44/72 &nbsp;&nbsp; (iv) −8/10</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Divide numerator and denominator by their HCF:<br>\n            <strong>(i)</strong> <span class=\"math\">\\text{HCF}(8, 6) = 2 ⟹ \\frac{-8 ÷ 2}{6 ÷ 2} = <strong>-\\frac{4}{3}</strong></span>.<br>\n            <strong>(ii)</strong> <span class=\"math\">\\text{HCF}(25, 45) = 5 ⟹ \\frac{25 ÷ 5}{45 ÷ 5} = <strong>\\frac{5}{9}</strong></span>.<br>\n            <strong>(iii)</strong> <span class=\"math\">\\text{HCF}(44, 72) = 4 ⟹ \\frac{-44 ÷ 4}{72 ÷ 4} = <strong>-\\frac{11}{18}</strong></span>.<br>\n            <strong>(iv)</strong> <span class=\"math\">\\text{HCF}(8, 10) = 2 ⟹ \\frac{-8 ÷ 2}{10 ÷ 2} = <strong>-\\frac{4}{5}</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">HCF division and simplest fraction reduction</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q8_2_3_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_2_3_def')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Find the product:<br>(i) 9/2 × (−7/4) &nbsp;&nbsp; (ii) 3/10 × (−9) &nbsp;&nbsp; (iii) −6/5 × 9/11 &nbsp;&nbsp; (iv) 3/7 × (−2/5)</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> <span class=\"math\">\\frac{9}{2} × \\frac{-7}{4} = \\frac{9 × (-7)}{2 × 4} = <strong>-\\frac{63}{8} = -7 \\frac{7}{8}</strong></span>.<br>\n            <strong>(ii)</strong> <span class=\"math\">\\frac{3}{10} × (-9) = \\frac{3 × (-9)}{10} = <strong>-\\frac{27}{10} = -2 \\frac{7}{10}</strong></span>.<br>\n            <strong>(iii)</strong> <span class=\"math\">-\\frac{6}{5} × \\frac{9}{11} = \\frac{-6 × 9}{5 × 11} = <strong>-\\frac{54}{55}</strong></span>.<br>\n            <strong>(iv)</strong> <span class=\"math\">\\frac{3}{7} × \\left(-\\frac{2}{5}\\right) = \\frac{3 × (-2)}{7 × 5} = <strong>-\\frac{6}{35}</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Numerator and denominator multiplication with signs</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q8_2_4_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_2_4_def')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Find the value of:<br>(i) (−4) ÷ 2/3 &nbsp;&nbsp; (ii) −3/5 ÷ 2 &nbsp;&nbsp; (iii) −4/5 ÷ (−3) &nbsp;&nbsp; (iv) −1/8 ÷ 3/4</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Multiply by the reciprocal of divisor:<br>\n            <strong>(i)</strong> <span class=\"math\">(-4) ÷ \\frac{2}{3} = (-4) × \\frac{3}{2} = -2 × 3 = <strong>-6</strong></span>.<br>\n            <strong>(ii)</strong> <span class=\"math\">-\\frac{3}{5} ÷ 2 = -\\frac{3}{5} × \\frac{1}{2} = <strong>-\\frac{3}{10}</strong></span>.<br>\n            <strong>(iii)</strong> <span class=\"math\">-\\frac{4}{5} ÷ (-3) = -\\frac{4}{5} × \\left(-\\frac{1}{3}\\right) = <strong>\\frac{4}{15}</strong></span>.<br>\n            <strong>(iv)</strong> <span class=\"math\">-\\frac{1}{8} ÷ \\frac{3}{4} = -\\frac{1}{8} × \\frac{4}{3} = -\\frac{1}{2 × 3} = <strong>-\\frac{1}{6}</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reciprocal application and correct evaluation</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\">\r\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\r\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\r\n    </div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">HOTS: Insertion of Rationals</div>\r\n        <div class=\"cbq-question\"><strong>Problem:</strong> Is it true that there are only 5 rational numbers between −1 and 0? Explain mathematically how many rational numbers exist between any two distinct rational numbers.</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <p><strong>Answer: No, it is not true.</strong></p>\r\n          <p>Between any two distinct rational numbers, there are <strong>infinitely many rational numbers</strong>.</p>\r\n          <p><em>Reasoning:</em> We can multiply the numerator and denominator by any arbitrarily large integer <span class=\"math\">k</span>. For example, choosing <span class=\"math\">k = 100</span> gives <span class=\"math\">-100/100</span> and <span class=\"math\">0/100</span>, yielding 99 rational numbers. Choosing <span class=\"math\">k = 10,000</span> yields 9,999 rational numbers. By choosing <span class=\"math\">k</span> arbitrarily large, we can insert as many rational numbers as we desire. This fundamental property is called the <strong>Density Property</strong> of rational numbers.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(7)\">← Chapter 7: Comparing Quantities</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(9)\">Chapter 9: Perimeter &amp; Area →</button>\r\n  </div>\r\n</section>\r\n","9":"<section class=\"chapter-section\" id=\"ch9\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">9</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 9: Perimeter and Area</h2>\r\n      <p>NCERT Exercise 9.1 to 9.2 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"concept-card\">\r\n    <div class=\"concept-header\">📌 Key Concepts &amp; Mensuration Formulas Summary</div>\r\n    <ul class=\"concept-list\">\r\n      <li><strong>Square &amp; Rectangle:</strong>\r\n        <ul>\r\n          <li>Perimeter of square = 4 × side;   Area of square = side².</li>\r\n          <li>Perimeter of rectangle = 2(l + b);   Area of rectangle = l × b.</li>\r\n        </ul>\r\n      </li>\r\n      <li><strong>Area of Parallelogram:</strong>\r\n        Area = Base × Height = b × h\r\n      </li>\r\n      <li><strong>Area of Triangle:</strong>\r\n        Area = 1/2 × Base × Height = 1/2 b h\r\n        (Every triangle can be viewed as half of a parallelogram with the same base and height).\r\n      </li>\r\n      <li><strong>Circle:</strong>\r\n        <ul>\r\n          <li>Circumference = 2π r = π d (where π ≈ 22/7 or 3.14).</li>\r\n          <li>Area of circle = π r².</li>\r\n          <li>Area of circular ring / path = π (R² - r²) = π(R + r)(R - r).</li>\r\n        </ul>\r\n      </li>\r\n      <li><strong>Unit Conversions:</strong>\r\n        1 cm² = 100 mm²,   1 m² = 10,000 cm²,   1 hectare = 10,000 m².\r\n      </li>\r\n    </ul>\r\n  </div>\r\n\r\n  <!-- EXERCISE 9.1 -->\r\n  <div class=\"ex-div\">Exercise 9.1 (Parallelograms &amp; Triangles)</div>\r\n\r\n  <div class=\"q-card\" id=\"q9_1_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Find the area of each of the following parallelograms:<br>(a) base = 7 cm, height = 4 cm<br>(b) base = 5 cm, height = 3 cm<br>(c) base = 2.5 cm, height = 3.5 cm<br>(d) base = 5 cm, height = 4.8 cm<br>(e) base = 2 cm, height = 4.4 cm</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p>Formula: <span class=\"math\">Area of parallelogram = base × height</span>.</p>\r\n          <div class=\"step\">\r\n            <strong>(a) <span class=\"math\">Area = 7 cm × 4 cm = <strong>28 cm²</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) <span class=\"math\">Area = 5 cm × 3 cm = <strong>15 cm²</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) <span class=\"math\">Area = 2.5 cm × 3.5 cm = <strong>8.75 cm²</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(d) <span class=\"math\">Area = 5 cm × 4.8 cm = <strong>24 cm²</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(e) <span class=\"math\">Area = 2 cm × 4.4 cm = <strong>8.8 cm²</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula stated: Base × Height</span><span class=\"marking-marks\">0.5 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with proper units (cm²)</span><span class=\"marking-marks\">0.5 Mark each (2.5 Marks)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q9_1_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Find the area of each of the following triangles:<br>(a) base = 4 cm, height = 3 cm<br>(b) base = 5 cm, height = 3.2 cm<br>(c) base = 3 cm, height = 4 cm (right-angled)<br>(d) base = 3 cm, height = 2 cm (obtuse)</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p>Formula: <span class=\"math\">Area of triangle = 1/2 × base × height</span>.</p>\r\n          <div class=\"step\">\r\n            <strong>(a) <span class=\"math\">Area = 1/2 × 4 × 3 = 2 × 3 = <strong>6 cm²</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) <span class=\"math\">Area = 1/2 × 5 × 3.2 = 5 × 1.6 = <strong>8 cm²</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) <span class=\"math\">Area = 1/2 × 3 × 4 = 3 × 2 = <strong>6 cm²</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(d) <span class=\"math\">Area = 1/2 × 3 × 2 = <strong>3 cm²</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula stated: ½ × Base × Height</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with unit (cm²)</span><span class=\"marking-marks\">0.5 Mark each (2 Marks)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q9_1_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">ΔABC is right angled at A. AD is perpendicular to BC. If AB = 5 cm, BC = 13 cm and AC = 12 cm, find the area of ΔABC. Also find the length of AD.</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Calculate Area of ΔABC using legs AB and AC:</strong><br>\r\n            Since right angle is at A, legs <span class=\"math\">AB = 5 cm</span> and <span class=\"math\">AC = 12 cm</span> serve as base and height.<br>\r\n            <span class=\"math\">Area = 1/2 × AB × AC = 1/2 × 5 × 12 = 5 × 6 = <strong>30 cm²</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Find altitude AD using hypotenuse BC as base:</strong><br>\r\n            <span class=\"math\">Area = 1/2 × BC × AD</span><br>\r\n            <span class=\"math\">30 = 1/2 × 13 × AD ⇒ AD = (30 × 2)/13 = 60/13 = <strong>4 8/13 cm</strong> ≈ 4.62 cm</span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> Area of ΔABC is <strong>30 cm²</strong> and length of <span class=\"math\">AD</span> is <strong>60/13 cm (4.62 cm)</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Area = ½ × 5 × 12 = 30 cm²</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Equating ½ × 13 × AD = 30 ⇒ AD = 60/13 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 9.2 -->\r\n  <div class=\"ex-div\">Exercise 9.2 (Circles: Circumference &amp; Area)</div>\r\n\r\n  <div class=\"q-card\" id=\"q9_2_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Find the circumference of the circles with the following radius (Take π = 22/7):<br>(a) 14 cm<br>(b) 28 mm<br>(c) 21 cm</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p>Formula: <span class=\"math\">C = 2π r</span>.</p>\r\n          <div class=\"step\">\r\n            <strong>(a) <span class=\"math\">C = 2 × 22/7 × 14 = 2 × 22 × 2 = <strong>88 cm</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) <span class=\"math\">C = 2 × 22/7 × 28 = 2 × 22 × 4 = <strong>176 mm</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) <span class=\"math\">C = 2 × 22/7 × 21 = 2 × 22 × 3 = <strong>132 cm</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula 2πr + each evaluation</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q9_2_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Find the area of the following circles, given that (Take π = 22/7):<br>(a) radius = 14 mm<br>(b) diameter = 49 m<br>(c) radius = 5 cm</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p>Formula: <span class=\"math\">Area = π r²</span>.</p>\r\n          <div class=\"step\">\r\n            <strong>(a) r = 14 mm:</strong><br>\r\n            <span class=\"math\">Area = 22/7 × 14 × 14 = 22 × 2 × 14 = <strong>616 mm²</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) d = 49 m ⇒ r = 49/2 m:</strong><br>\r\n            <span class=\"math\">Area = 22/7 × 49/2 × 49/2 = (11 × 7 × 49)/2 = 3773/2 = <strong>1886.5 m²</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) r = 5 cm:</strong><br>\r\n            <span class=\"math\">Area = 22/7 × 5 × 5 = 550/7 = <strong>78 4/7 cm²</strong> ≈ 78.57 cm²</span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with formula and units</span><span class=\"marking-marks\">1 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q9_2_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">A gardener wants to fence a circular garden of diameter 21 m. Find the length of the rope he needs to purchase, if he makes 2 rounds of fence. Also find the cost of the rope, if it costs ₹4 per metre. (Take π = 22/7)</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Calculate circumference of garden:</strong><br>\r\n            Diameter <span class=\"math\">d = 21 m ⇒ r = 21/2 m</span>.<br>\r\n            <span class=\"math\">C = 2π r = 2 × 22/7 × 21/2 = 22 × 3 = <strong>66 m</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Total length of rope for 2 rounds:</strong><br>\r\n            <span class=\"math\">Length of rope = 2 × C = 2 × 66 = <strong>132 m</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 3: Calculate total cost:</strong><br>\r\n            Cost per metre = <span class=\"math\">₹4</span>.<br>\r\n            <span class=\"math\">Total Cost = 132 × ₹4 = <strong>₹528</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> He needs <strong>132 metres</strong> of rope and the total cost is <strong>₹528</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Circumference C = 66 m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Rope length for 2 rounds = 132 m</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Total cost = 132 × 4 = ₹528</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q9_2_4\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_4')\">\r\n      <div class=\"q-num\">Q4</div>\r\n      <div class=\"q-text\">From a circular sheet of radius 4 cm, a circle of radius 3 cm is removed. Find the area of the remaining sheet. (Take π = 3.14)</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Step 1: Area of outer circular sheet (R = 4 cm):</strong><br>\r\n            <span class=\"math\">Area₁ = π R² = 3.14 × 4² = 3.14 × 16 = <strong>50.24 cm²</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 2: Area of removed circle (r = 3 cm):</strong><br>\r\n            <span class=\"math\">Area₂ = π r² = 3.14 × 3² = 3.14 × 9 = <strong>28.26 cm²</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>Step 3: Area of remaining sheet:</strong><br>\r\n            <span class=\"math\">Area = Area₁ − Area₂ = 50.24 − 28.26 = <strong>21.98 cm²</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> The area of the remaining sheet is <strong>21.98 cm²</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Outer area = 50.24 cm²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Inner area = 28.26 cm²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Difference = 21.98 cm²</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n    <div class=\"q-card\" id=\"q9_1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">PQRS is a parallelogram. QM is the height from Q to SR and QN is the height from Q to PS. If SR = 12 cm and QM = 7.6 cm:<br>(a) Find the area of the parallelogram PQRS.<br>(b) Find QN, if PS = 8 cm.</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Area of parallelogram PQRS:</strong><br>\n            Base = SR = 12 cm, Height = QM = 7.6 cm.<br>\n            <span class=\"math\">Area = Base × Height = 12 × 7.6 = <strong>91.2 cm²</strong></span>.\n          </div>\n          <div class=\"step\">\n            <strong>(b) Find QN when PS = 8 cm:</strong><br>\n            Base = PS = 8 cm, Height = QN.<br>\n            <span class=\"math\">Area = Base × Height ⇒ 91.2 = 8 × QN ⇒ QN = 91.2 / 8 = <strong>11.4 cm</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> (a) Area = <strong>91.2 cm²</strong>; (b) QN = <strong>11.4 cm</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): Area = 12 × 7.6 = 91.2 cm²</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): QN = 91.2 / 8 = 11.4 cm</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_1_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">DL and BM are the heights on sides AB and AD respectively of parallelogram ABCD. If the area of the parallelogram is 1470 cm², AB = 35 cm and AD = 49 cm, find the length of BM and DL.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Area of parallelogram ABCD = 1470 cm².<br>\n            <strong>1. Height DL on base AB:</strong><br>\n            <span class=\"math\">Area = Base × Height ⇒ 1470 = AB × DL = 35 × DL</span><br>\n            <span class=\"math\">DL = 1470 / 35 = <strong>42 cm</strong></span>.<br>\n            <strong>2. Height BM on base AD:</strong><br>\n            <span class=\"math\">Area = AD × BM ⇒ 1470 = 49 × BM</span><br>\n            <span class=\"math\">BM = 1470 / 49 = <strong>30 cm</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> DL = <strong>42 cm</strong> and BM = <strong>30 cm</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">DL = 1470 / 35 = 42 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">BM = 1470 / 49 = 30 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_1_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">ΔABC is right angled at A. AD is perpendicular to BC. If AB = 5 cm, BC = 13 cm and AC = 12 cm, find the area of ΔABC. Also find the length of AD.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. Area of right-angled ΔABC:</strong><br>\n            Base = AB = 5 cm, Height = AC = 12 cm.<br>\n            <span class=\"math\">Area = 1/2 × Base × Height = 1/2 × 5 × 12 = 5 × 6 = <strong>30 cm²</strong></span>.<br>\n            <strong>2. Length of altitude AD on hypotenuse BC:</strong><br>\n            Taking BC = 13 cm as base and AD as height:<br>\n            <span class=\"math\">Area = 1/2 × BC × AD ⇒ 30 = 1/2 × 13 × AD ⇒ AD = (30 × 2) / 13 = <strong>60/13 cm ≈ 4.62 cm</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> Area is <strong>30 cm²</strong> and AD is <strong>60/13 cm</strong> (or <strong>4.62 cm</strong>).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Area = 1/2 × 5 × 12 = 30 cm²</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">AD = 60/13 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_2_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Find the perimeter of the adjoining figure, which is a semicircle including its diameter of 10 cm.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Diameter <span class=\"math\">d = 10 cm</span> ⇒ Radius <span class=\"math\">r = 5 cm</span>.<br>\n            Perimeter of semicircle = Circumference of curved boundary + Diameter<br>\n            <span class=\"math\">= πr + d = (22/7 × 5) + 10 = (110 / 7) + 10 = 15.71 + 10 = <strong>25.71 cm</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The perimeter of the figure is <strong>25.71 cm</strong> (or <strong>180/7 cm</strong>).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula: Perimeter = πr + d</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation: 25.71 cm</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_2_11\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_11')\">\n      <div class=\"q-num\">Q11</div>\n      <div class=\"q-text\">A circle of radius 2 cm is cut out from a square piece of an aluminium sheet of side 6 cm. What is the area of the left over aluminium sheet? (Take π = 3.14).</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Side of square aluminium sheet = 6 cm.<br>\n            <span class=\"math\">Area of square sheet = side × side = 6 × 6 = <strong>36 cm²</strong></span>.<br>\n            Radius of circle = 2 cm.<br>\n            <span class=\"math\">Area of circle = πr² = 3.14 × 2² = 3.14 × 4 = <strong>12.56 cm²</strong></span>.<br>\n            Area of leftover aluminium sheet = <span class=\"math\">36 − 12.56 = <strong>23.44 cm²</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The area of the leftover sheet is <strong>23.44 cm²</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Area of square = 36 cm², Area of circle = 12.56 cm²</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Difference = 23.44 cm²</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">PQRS is a parallelogram. QM is the height from Q to SR and QN is the height from Q to PS. If SR = 12 cm and QM = 7.6 cm. Find:<br>(a) the area of the parallelogram PQRS<br>(b) QN, if PS = 8 cm.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a)</strong> Area of parallelogram = <span class=\"math\">\\text{Base} × \\text{Height} = SR × QM</span><br>\n            <span class=\"math\">= 12\\text{ cm} × 7.6\\text{ cm} = <strong>91.2 cm²</strong></span>.<br><br>\n            <strong>(b)</strong> Also, Area of parallelogram = <span class=\"math\">PS × QN</span><br>\n            <span class=\"math\">91.2 = 8 × QN</span><br>\n            <span class=\"math\">QN = 91.2 / 8 = <strong>11.4 cm</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Area calculation = 91.2 cm²</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Height QN calculation = 11.4 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_1_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">DL and BM are the heights on sides AB and AD respectively of parallelogram ABCD. If the area of the parallelogram is 1470 cm², AB = 35 cm and AD = 49 cm, find the length of BM and DL.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Given: Area of parallelogram ABCD = 1470 cm².<br><br>\n            (i) Taking base <span class=\"math\">AB = 35\\text{ cm}</span> and height = <span class=\"math\">DL</span>:<br>\n            <span class=\"math\">\\text{Area} = AB × DL</span><br>\n            <span class=\"math\">1470 = 35 × DL ⟹ DL = 1470 / 35 = <strong>42 cm</strong></span>.<br><br>\n            (ii) Taking base <span class=\"math\">AD = 49\\text{ cm}</span> and height = <span class=\"math\">BM</span>:<br>\n            <span class=\"math\">\\text{Area} = AD × BM</span><br>\n            <span class=\"math\">1470 = 49 × BM ⟹ BM = 1470 / 49 = <strong>30 cm</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of DL = 42 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of BM = 30 cm</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_1_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">ΔABC is right angled at A. AD is perpendicular to BC. If AB = 5 cm, BC = 13 cm and AC = 12 cm, Find the area of ΔABC. Also find the length of AD.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Since ΔABC is right-angled at A:<br>\n            <span class=\"math\">\\text{Area of } \\Delta ABC = \\frac{1}{2} × \\text{base} × \\text{height} = \\frac{1}{2} × AB × AC</span><br>\n            <span class=\"math\">= \\frac{1}{2} × 5 × 12 = 5 × 6 = <strong>30 cm²</strong></span>.<br><br>\n            Now, taking BC as base and AD as perpendicular height:<br>\n            <span class=\"math\">\\text{Area of } \\Delta ABC = \\frac{1}{2} × BC × AD</span><br>\n            <span class=\"math\">30 = \\frac{1}{2} × 13 × AD</span><br>\n            <span class=\"math\">AD = (30 × 2) / 13 = 60 / 13 = <strong>4.62 cm</strong></span> (or <span class=\"math\">4 \\frac{8}{13}</span> cm).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Area calculation (30 cm²)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Length of AD calculation (60/13 cm)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_1_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">ΔABC is isosceles with AB = AC = 7.5 cm and BC = 9 cm. The height AD from A to BC, is 6 cm. Find the area of ΔABC. What will be the height from C to AB i.e., CE?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            (i) Base <span class=\"math\">BC = 9\\text{ cm}</span>, Height <span class=\"math\">AD = 6\\text{ cm}</span>:<br>\n            <span class=\"math\">\\text{Area of } \\Delta ABC = \\frac{1}{2} × BC × AD = \\frac{1}{2} × 9 × 6 = 9 × 3 = <strong>27 cm²</strong></span>.<br><br>\n            (ii) Taking base <span class=\"math\">AB = 7.5\\text{ cm}</span> and height <span class=\"math\">CE</span>:<br>\n            <span class=\"math\">\\text{Area of } \\Delta ABC = \\frac{1}{2} × AB × CE</span><br>\n            <span class=\"math\">27 = \\frac{1}{2} × 7.5 × CE</span><br>\n            <span class=\"math\">CE = (27 × 2) / 7.5 = 54 / 7.5 = <strong>7.2 cm</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Area calculation (27 cm²)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Height CE calculation (7.2 cm)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_2_13\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_13')\">\n      <div class=\"q-num\">Q13</div>\n      <div class=\"q-text\">A circular flower bed is surrounded by a path 4 m wide. The diameter of the flower bed is 66 m. What is the area of this path? (π = 3.14)</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Diameter of circular flower bed = 66 m.<br>\n            Radius of flower bed (<span class=\"math\">r</span>) = <span class=\"math\">66 / 2 = 33\\text{ m}</span>.<br>\n            Width of path = 4 m.<br>\n            Radius of flower bed including path (<span class=\"math\">R</span>) = <span class=\"math\">33 + 4 = 37\\text{ m}</span>.<br><br>\n            Area of the path = <span class=\"math\">\\pi R^2 − \\pi r^2 = \\pi (R^2 − r^2)</span><br>\n            <span class=\"math\">= 3.14 × (37^2 − 33^2)</span><br>\n            Using <span class=\"math\">a^2 − b^2 = (a − b)(a + b)</span>:<br>\n            <span class=\"math\">= 3.14 × (37 − 33)(37 + 33) = 3.14 × 4 × 70 = 3.14 × 280 = <strong>879.2 m²</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Radii calculation r = 33 m, R = 37 m</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula π(R² - r²) and correct answer 879.2 m²</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_2_14\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_14')\">\n      <div class=\"q-num\">Q14</div>\n      <div class=\"q-text\">A circular flower garden has an area of 314 m². A sprinkler at the centre of the garden can cover an area that has a radius of 12 m. Will the sprinkler water the entire garden? (Take π = 3.14)</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Area of the circular flower garden = 314 m².<br>\n            Radius covered by sprinkler (<span class=\"math\">r</span>) = 12 m.<br><br>\n            Area covered by sprinkler = <span class=\"math\">\\pi r^2 = 3.14 × 12^2 = 3.14 × 144 = <strong>452.16 m²</strong></span>.<br><br>\n            Comparison:<br>\n            Since the area covered by the sprinkler (452.16 m²) is <strong>greater</strong> than the area of the garden (314 m²),<br>\n            <strong>Yes, the sprinkler will water the entire garden.</strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of area covered by sprinkler (452.16 m²)</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Comparison and conclusion</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n    <div class=\"q-card\" id=\"q9_1_1_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_1_def')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Find the area of each of the following parallelograms:<br>(a) base = 7 cm, height = 4 cm<br>(b) base = 5 cm, height = 3 cm<br>(c) base = 2.5 cm, height = 3.5 cm</div>\n      <div class=\"q-marks\">3 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Area of parallelogram = <span class=\"math\">\\text{base} × \\text{height}</span>.<br><br>\n            <strong>(a)</strong> <span class=\"math\">\\text{Area} = 7\\text{ cm} × 4\\text{ cm} = <strong>28 cm²</strong></span>.<br>\n            <strong>(b)</strong> <span class=\"math\">\\text{Area} = 5\\text{ cm} × 3\\text{ cm} = <strong>15 cm²</strong></span>.<br>\n            <strong>(c)</strong> <span class=\"math\">\\text{Area} = 2.5\\text{ cm} × 3.5\\text{ cm} = <strong>8.75 cm²</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula base × height and correct evaluation</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_1_2_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1_2_def')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Find the area of each of the following triangles:<br>(a) base = 4 cm, height = 3 cm<br>(b) base = 5 cm, height = 3.2 cm<br>(c) base = 3 cm, height = 4 cm</div>\n      <div class=\"q-marks\">3 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Area of triangle = <span class=\"math\">\\frac{1}{2} × \\text{base} × \\text{height}</span>.<br><br>\n            <strong>(a)</strong> <span class=\"math\">\\text{Area} = \\frac{1}{2} × 4 × 3 = <strong>6 cm²</strong></span>.<br>\n            <strong>(b)</strong> <span class=\"math\">\\text{Area} = \\frac{1}{2} × 5 × 3.2 = 5 × 1.6 = <strong>8 cm²</strong></span>.<br>\n            <strong>(c)</strong> <span class=\"math\">\\text{Area} = \\frac{1}{2} × 3 × 4 = <strong>6 cm²</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula 1/2 × b × h and correct calculation</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_2_5_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_5_def')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">From a circular sheet of radius 4 cm, a circle of radius 3 cm is removed. Find the area of the remaining sheet. (Take π = 3.14)</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Radius of outer circular sheet (<span class=\"math\">R</span>) = 4 cm.<br>\n            Radius of removed circle (<span class=\"math\">r</span>) = 3 cm.<br><br>\n            Area of remaining sheet = <span class=\"math\">\\pi R^2 − \\pi r^2 = \\pi (R^2 − r^2)</span><br>\n            <span class=\"math\">= 3.14 × (4^2 − 3^2)</span><br>\n            <span class=\"math\">= 3.14 × (16 − 9) = 3.14 × 7 = <strong>21.98 cm²</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula π(R² - r²) substitution</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluation 21.98 cm²</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_2_6_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_6_def')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Saima wants to put a lace on the edge of a circular table cover of diameter 1.5 m. Find the length of the lace required and also find its cost if one meter of the lace costs ₹ 15. (Take π = 3.14)</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Diameter of circular table cover (<span class=\"math\">d</span>) = 1.5 m.<br>\n            Length of lace required = Circumference = <span class=\"math\">\\pi d</span><br>\n            <span class=\"math\">= 3.14 × 1.5 = <strong>4.71 m</strong></span>.<br><br>\n            Cost of 1 m lace = ₹ 15.<br>\n            Total cost = <span class=\"math\">4.71 × 15 = <strong>₹ 70.65</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Circumference calculation = 4.71 m</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Cost calculation = ₹ 70.65</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q9_2_15_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2_15_def')\">\n      <div class=\"q-num\">Q15</div>\n      <div class=\"q-text\">Find the circumference of the inner and the outer circles, shown in the figure, where outer radius is 19 m and the width of the track is 10 m. (Take π = 3.14)</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Outer radius (<span class=\"math\">R</span>) = 19 m.<br>\n            Circumference of outer circle = <span class=\"math\">2\\pi R = 2 × 3.14 × 19 = <strong>119.32 m</strong></span>.<br><br>\n            Inner radius (<span class=\"math\">r</span>) = <span class=\"math\">19 − 10 = 9\\text{ m}</span>.<br>\n            Circumference of inner circle = <span class=\"math\">2\\pi r = 2 × 3.14 × 9 = <strong>56.52 m</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Outer circumference = 119.32 m</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Inner circumference = 56.52 m</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\">\r\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\r\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\r\n    </div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">HOTS: Wire Rebent from Square to Rectangle</div>\r\n        <div class=\"cbq-question\"><strong>Problem:</strong> A wire is in the shape of a square of side 10 cm. If the wire is rebent into a rectangle of length 12 cm, find its breadth. Which figure encloses more area and by how much?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <p><strong>1. Length of wire (Perimeter):</strong><br>\r\n          <span class=\"math\">Perimeter of square = 4 × side = 4 × 10 = <strong>40 cm</strong></span>.<br>\r\n          When rebent into a rectangle, perimeter is still 40 cm:<br>\r\n          <span class=\"math\">2(l + b) = 40 ⇒ 2(12 + b) = 40 ⇒ 12 + b = 20 ⇒ b = 20 − 12 = <strong>8 cm</strong></span>.</p>\r\n          <p><strong>2. Compare Areas:</strong><br>\r\n          <span class=\"math\">Area of square = side² = 10 × 10 = <strong>100 cm²</strong></span>.<br>\r\n          <span class=\"math\">Area of rectangle = l × b = 12 × 8 = <strong>96 cm²</strong></span>.<br>\r\n          Difference = <span class=\"math\">100 − 96 = <strong>4 cm²</strong></span>.<br>\r\n          <strong>Conclusion:</strong> The <strong>square</strong> encloses more area by <strong>4 cm²</strong>.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(8)\">← Chapter 8: Rational Numbers</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(10)\">Chapter 10: Algebraic Expressions →</button>\r\n  </div>\r\n</section>\r\n","10":"<section class=\"chapter-section\" id=\"ch10\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">10</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 10: Algebraic Expressions</h2>\r\n      <p>NCERT Exercise 10.1 to 10.2 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"concept-card\">\r\n    <div class=\"concept-header\">📌 Key Concepts &amp; Algebraic Rules Summary</div>\r\n    <ul class=\"concept-list\">\r\n      <li><strong>Terms and Factors:</strong>\r\n        An algebraic expression is formed by terms. For example, in 4x² - 3xy, the terms are 4x² and -3xy. The factors of 4x² are 4, x, x and of -3xy are -3, x, y.\r\n      </li>\r\n      <li><strong>Coefficients:</strong> The numerical factor of a term is called its numerical coefficient (e.g. In -5xy, the coefficient is -5).</li>\r\n      <li><strong>Like and Unlike Terms:</strong>\r\n        <ul>\r\n          <li><em>Like terms:</em> Terms having the same algebraic factors with identical exponents (e.g. 7x and -12x, 4x^2y and -9x^2y).</li>\r\n          <li><em>Unlike terms:</em> Terms having different algebraic factors (e.g. 7x and 7y, 4x² and 4x).</li>\r\n        </ul>\r\n      </li>\r\n      <li><strong>Classification of Expressions:</strong>\r\n        <ul>\r\n          <li><em>Monomial:</em> Exactly one term (e.g. 7xy, -5).</li>\r\n          <li><em>Binomial:</em> Exactly two terms (e.g. a + b, 4x² - 3).</li>\r\n          <li><em>Trinomial:</em> Exactly three terms (e.g. a + b + c, x² + 5x + 6).</li>\r\n          <li><em>Polynomial:</em> An expression with one or more terms having non-negative integral exponents.</li>\r\n        </ul>\r\n      </li>\r\n      <li><strong>Addition and Subtraction:</strong> Only like terms can be combined (added or subtracted) by adding their numerical coefficients.</li>\r\n      <li><strong>Evaluating Expressions:</strong> Substitute the given numerical values of variables into the expression and apply BODMAS.</li>\r\n    </ul>\r\n  </div>\r\n\r\n  <!-- EXERCISE 10.1 -->\r\n  <div class=\"ex-div\">Exercise 10.1</div>\r\n\r\n  <div class=\"q-card\" id=\"q10_1_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_1_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Identify the terms and their factors in the following expressions:<br>(a) x − 3<br>(b) 1 + x + x²<br>(c) y − y³<br>(d) 5xy² + 7x²y<br>(e) −ab + 2b² − 3a²</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) x − 3:</strong><br>\r\n            • Term: <span class=\"math\">x</span> ⇒ Factors: <span class=\"math\">x</span><br>\r\n            • Term: <span class=\"math\">−3</span> ⇒ Factors: <span class=\"math\">−3</span> (or <span class=\"math\">−1, 3</span>)\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) 1 + x + x²:</strong><br>\r\n            • Terms: <span class=\"math\">1, x, x²</span><br>\r\n            • Factors of <span class=\"math\">x²</span>: <span class=\"math\">x, x</span>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) y − y³:</strong><br>\r\n            • Terms: <span class=\"math\">y</span> and <span class=\"math\">−y³</span><br>\r\n            • Factors of <span class=\"math\">−y³</span>: <span class=\"math\">−1, y, y, y</span>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(d) 5xy² + 7x²y:</strong><br>\r\n            • Term: <span class=\"math\">5xy²</span> ⇒ Factors: <span class=\"math\">5, x, y, y</span><br>\r\n            • Term: <span class=\"math\">7x^2y</span> ⇒ Factors: <span class=\"math\">7, x, x, y</span>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(e) −ab + 2b² − 3a²:</strong><br>\r\n            • Term <span class=\"math\">−ab</span>: <span class=\"math\">−1, a, b</span><br>\r\n            • Term <span class=\"math\">2b²</span>: <span class=\"math\">2, b, b</span><br>\r\n            • Term <span class=\"math\">−3a²</span>: <span class=\"math\">−3, a, a</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying terms and breaking into factors</span><span class=\"marking-marks\">3 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q10_1_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_1_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Classify into monomials, binomials and trinomials:<br>(i) 4y − 7z<br>(ii) y²<br>(iii) x + y − xy<br>(iv) 100<br>(v) ab − a − b<br>(vi) 5 − 3t<br>(vii) 4p²q − 4pq²<br>(viii) 7mn<br>(ix) z² − 3z + 8</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            • <strong>Monomials (1 term):</strong> (ii) <span class=\"math\">y²</span>, (iv) <span class=\"math\">100</span>, (viii) <span class=\"math\">7mn</span>.<br>\r\n            • <strong>Binomials (2 terms):</strong> (i) <span class=\"math\">4y − 7z</span>, (vi) <span class=\"math\">5 − 3t</span>, (vii) <span class=\"math\">4p^2q − 4pq²</span>.<br>\r\n            • <strong>Trinomials (3 terms):</strong> (iii) <span class=\"math\">x + y − xy</span>, (v) <span class=\"math\">ab − a − b</span>, (ix) <span class=\"math\">z² − 3z + 8</span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct classification</span><span class=\"marking-marks\">0.33 Mark each (3 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q10_1_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_1_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">Simplify by combining like terms:<br>(i) 21b − 32 + 7b − 20b<br>(ii) −z² + 13z² − 5z + 7z³ − 15z<br>(iii) p − (p − q) − q − (q − p)<br>(iv) 3a − 2b − ab − (a − b + ab) + 3ab + b − a</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) 21b − 32 + 7b − 20b:</strong><br>\r\n            Group terms with variable <span class=\"math\">b</span>:<br>\r\n            <span class=\"math\">= (21 + 7 − 20)b − 32 = (28 − 20)b − 32 = <strong>8b − 32</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) −z² + 13z² − 5z + 7z³ − 15z:</strong><br>\r\n            Arrange by descending powers of <span class=\"math\">z</span>:<br>\r\n            <span class=\"math\">= 7z³ + (−1 + 13)z² + (−5 − 15)z = <strong>7z³ + 12z² − 20z</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) p − (p − q) − q − (q − p):</strong><br>\r\n            Open parentheses with sign rules:<br>\r\n            <span class=\"math\">= p − p + q − q − q + p = (p − p + p) + (q − q − q) = <strong>p − q</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iv) 3a − 2b − ab − (a − b + ab) + 3ab + b − a:</strong><br>\r\n            Open brackets: <span class=\"math\">= 3a − 2b − ab − a + b − ab + 3ab + b − a</span>.<br>\r\n            Group like terms:<br>\r\n            • Terms in <span class=\"math\">a</span>: <span class=\"math\">(3 − 1 − 1)a = a</span><br>\r\n            • Terms in <span class=\"math\">b</span>: <span class=\"math\">(−2 + 1 + 1)b = 0b = 0</span><br>\r\n            • Terms in <span class=\"math\">ab</span>: <span class=\"math\">(−1 − 1 + 3)ab = ab</span><br>\r\n            <span class=\"math\">= <strong>a + ab</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part: Grouping like terms and simplifying</span><span class=\"marking-marks\">1 Mark each (4 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 10.2 -->\r\n  <div class=\"ex-div\">Exercise 10.2 (Evaluation of Expressions)</div>\r\n\r\n  <div class=\"q-card\" id=\"q10_2_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_2_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">If m = 2, find the value of:<br>(i) m − 2<br>(ii) 3m − 5<br>(iii) 9 − 5m<br>(iv) 3m² − 2m − 7<br>(v) 5m/2 − 4</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p>Substitute <span class=\"math\">m = 2</span>:</p>\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">m − 2 = 2 − 2 = <strong>0</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) <span class=\"math\">3m − 5 = 3(2) − 5 = 6 − 5 = <strong>1</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) <span class=\"math\">9 − 5m = 9 − 5(2) = 9 − 10 = <strong>−1</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iv) <span class=\"math\">3m² − 2m − 7 = 3(2)² − 2(2) − 7 = 3(4) − 4 − 7 = 12 − 11 = <strong>1</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(v) <span class=\"math\">5m/2 − 4 = 5(2)/2 − 4 = 5 − 4 = <strong>1</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct numerical evaluation</span><span class=\"marking-marks\">0.6 Mark each (3 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q10_2_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q10_2_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">If a = 2, b = −2, find the value of:<br>(i) a² + b²<br>(ii) a² + ab + b²<br>(iii) a² − b²</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p>Given: <span class=\"math\">a = 2</span>, <span class=\"math\">b = −2</span>.</p>\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">a² + b² = (2)² + (−2)² = 4 + 4 = <strong>8</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) <span class=\"math\">a² + ab + b² = (2)² + (2)(−2) + (−2)² = 4 − 4 + 4 = <strong>4</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) <span class=\"math\">a² − b² = (2)² − (−2)² = 4 − 4 = <strong>0</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part evaluated with square of negative numbers</span><span class=\"marking-marks\">1 Mark each (3 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n    <div class=\"q-card\" id=\"q10_2_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_2_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">What should be the value of a if the value of 2x² + x − a equals 5, when x = 0?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Given expression: <span class=\"math\">2x² + x − a = 5</span>.<br>\n            Substitute <span class=\"math\">x = 0</span>:<br>\n            <span class=\"math\">2(0)² + (0) − a = 5 ⇒ 0 + 0 − a = 5 ⇒ −a = 5 ⇒ a = <strong>−5</strong></span>.\n          </div>\n          <p><strong>Final Answer:</strong> The value of <span class=\"math\">a</span> is <strong>−5</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution of x = 0: 0 + 0 − a = 5</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Result: a = −5</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q10_1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Classify into monomials, binomials and trinomials:<br>(i) 4y − 7z &nbsp;&nbsp; (ii) y² &nbsp;&nbsp; (iii) x + y − xy &nbsp;&nbsp; (iv) 100<br>(v) ab − a − b &nbsp;&nbsp; (vi) 5 − 3t &nbsp;&nbsp; (vii) 4p²q − 4pq² &nbsp;&nbsp; (viii) 7mn<br>(ix) z² − 3z + 8 &nbsp;&nbsp; (x) a² + b² &nbsp;&nbsp; (xi) z² + z &nbsp;&nbsp; (xii) 1 + x + x²</div>\n      <div class=\"q-marks\">3 Marks (1/4 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            • <strong>Monomials (1 term):</strong> (ii) y², (iv) 100, (viii) 7mn.<br>\n            • <strong>Binomials (2 terms):</strong> (i) 4y − 7z, (vi) 5 − 3t, (vii) 4p²q − 4pq², (x) a² + b², (xi) z² + z.<br>\n            • <strong>Trinomials (3 terms):</strong> (iii) x + y − xy, (v) ab − a − b, (ix) z² − 3z + 8, (xii) 1 + x + x².\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct algebraic polynomial classification</span><span class=\"marking-marks\">1/4 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q10_2_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_2_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">If a = 2, b = −2, find the value of:<br>(i) a² + b²<br>(ii) a² + ab + b²<br>(iii) a² − b²</div>\n      <div class=\"q-marks\">3 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Substitute <span class=\"math\">a = 2, b = −2</span>:<br>\n            <strong>(i)</strong> <span class=\"math\">a² + b² = 2² + (−2)² = 4 + 4 = <strong>8</strong></span>.<br>\n            <strong>(ii)</strong> <span class=\"math\">a² + ab + b² = 2² + 2(−2) + (−2)² = 4 − 4 + 4 = <strong>4</strong></span>.<br>\n            <strong>(iii)</strong> <span class=\"math\">a² − b² = 2² − (−2)² = 4 − 4 = <strong>0</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with proper sign rules</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q10_1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">(a) Identify terms which contain x and give the coefficient of x:<br>(i) y²x + y &nbsp;&nbsp; (ii) 13y² − 8yx &nbsp;&nbsp; (iii) x + y + 2 &nbsp;&nbsp; (iv) 5 + z + zx<br>(b) Identify terms which contain y² and give the coefficient of y²:<br>(i) 8 − xy² &nbsp;&nbsp; (ii) 5y² + 7x &nbsp;&nbsp; (iii) 2x²y − 15xy² + 20t²</div>\n      <div class=\"q-marks\">3.5 Marks (1/2 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Terms with x and coefficient of x:</strong><br>\n            • (i) <span class=\"math\">y^2x + y</span>: Term with x is <span class=\"math\">y^2x</span>, coefficient of x is <strong>y²</strong>.<br>\n            • (ii) <span class=\"math\">13y^2 − 8yx</span>: Term with x is <span class=\"math\">−8yx</span>, coefficient of x is <strong>−8y</strong>.<br>\n            • (iii) <span class=\"math\">x + y + 2</span>: Term with x is <span class=\"math\">x</span>, coefficient of x is <strong>1</strong>.<br>\n            • (iv) <span class=\"math\">5 + z + zx</span>: Term with x is <span class=\"math\">zx</span>, coefficient of x is <strong>z</strong>.<br><br>\n            <strong>(b) Terms with y² and coefficient of y²:</strong><br>\n            • (i) <span class=\"math\">8 − xy^2</span>: Term with y² is <span class=\"math\">−xy^2</span>, coefficient is <strong>−x</strong>.<br>\n            • (ii) <span class=\"math\">5y^2 + 7x</span>: Term with y² is <span class=\"math\">5y^2</span>, coefficient is <strong>5</strong>.<br>\n            • (iii) <span class=\"math\">2x^2y − 15xy^2 + 20t^2</span>: Term with y² is <span class=\"math\">−15xy^2</span>, coefficient is <strong>−15x</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying term and coefficient for each sub-question</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q10_1_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_1_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">State whether a given pair of terms is of like or unlike terms:<br>(i) 1, 100 &nbsp;&nbsp; (ii) −7x, 5/2 x &nbsp;&nbsp; (iii) −29x, −29y &nbsp;&nbsp; (iv) 14xy, 42yx &nbsp;&nbsp; (v) 4m²p, 4mp² &nbsp;&nbsp; (vi) 12xz, 12x²z²</div>\n      <div class=\"q-marks\">3 Marks (1/2 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) 1, 100:</strong> <strong>Like terms</strong> (both are constants, no algebraic factors).<br>\n            <strong>(ii) −7x, 5/2 x:</strong> <strong>Like terms</strong> (both have same algebraic factor x).<br>\n            <strong>(iii) −29x, −29y:</strong> <strong>Unlike terms</strong> (different variables x and y).<br>\n            <strong>(iv) 14xy, 42yx:</strong> <strong>Like terms</strong> (xy = yx, algebraic factors are identical).<br>\n            <strong>(v) 4m²p, 4mp²:</strong> <strong>Unlike terms</strong> (powers of m and p differ: m²p vs mp²).<br>\n            <strong>(vi) 12xz, 12x²z²:</strong> <strong>Unlike terms</strong> (powers differ: xz vs x²z²).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct identification of like / unlike terms</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q10_2_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_2_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Find the value of the following expressions for x = −1:<br>(i) 2x − 7 &nbsp;&nbsp; (ii) −x + 2 &nbsp;&nbsp; (iii) x² + 2x + 1 &nbsp;&nbsp; (iv) 2x² − x − 2</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Substitute <span class=\"math\">x = −1</span> in each expression:<br>\n            <strong>(i)</strong> <span class=\"math\">2x − 7 = 2(−1) − 7 = −2 − 7 = <strong>−9</strong></span>.<br>\n            <strong>(ii)</strong> <span class=\"math\">−x + 2 = −(−1) + 2 = 1 + 2 = <strong>3</strong></span>.<br>\n            <strong>(iii)</strong> <span class=\"math\">x^2 + 2x + 1 = (−1)^2 + 2(−1) + 1 = 1 − 2 + 1 = <strong>0</strong></span>.<br>\n            <strong>(iv)</strong> <span class=\"math\">2x^2 − x − 2 = 2(−1)^2 − (−1) − 2 = 2(1) + 1 − 2 = 2 + 1 − 2 = <strong>1</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution and arithmetic evaluation</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q10_2_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_2_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">When a = 0, b = −1, find the value of the given expressions:<br>(i) 2a + 2b &nbsp;&nbsp; (ii) 2a² + b² + 1 &nbsp;&nbsp; (iii) 2a²b + 2ab² + ab &nbsp;&nbsp; (iv) a² + ab + 2</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Substitute <span class=\"math\">a = 0, b = −1</span>:<br>\n            <strong>(i)</strong> <span class=\"math\">2a + 2b = 2(0) + 2(−1) = 0 − 2 = <strong>−2</strong></span>.<br>\n            <strong>(ii)</strong> <span class=\"math\">2a^2 + b^2 + 1 = 2(0)^2 + (−1)^2 + 1 = 0 + 1 + 1 = <strong>2</strong></span>.<br>\n            <strong>(iii)</strong> <span class=\"math\">2a^2b + 2ab^2 + ab = 2(0)^2(−1) + 2(0)(−1)^2 + (0)(−1) = 0 + 0 + 0 = <strong>0</strong></span>.<br>\n            <strong>(iv)</strong> <span class=\"math\">a^2 + ab + 2 = (0)^2 + (0)(−1) + 2 = 0 + 0 + 2 = <strong>2</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Substitution and evaluation for each expression</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q10_2_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_2_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Simplify the expressions and find the value if x is equal to 2:<br>(i) x + 7 + 4(x − 5)<br>(ii) 3(x + 2) + 5x − 7<br>(iii) 6x + 5(x − 2)<br>(iv) 4(2x − 1) + 3x + 11</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> <span class=\"math\">x + 7 + 4(x − 5) = x + 7 + 4x − 20 = 5x − 13</span>.<br>\n            For <span class=\"math\">x = 2</span>: <span class=\"math\">5(2) − 13 = 10 − 13 = <strong>−3</strong></span>.<br><br>\n            <strong>(ii)</strong> <span class=\"math\">3(x + 2) + 5x − 7 = 3x + 6 + 5x − 7 = 8x − 1</span>.<br>\n            For <span class=\"math\">x = 2</span>: <span class=\"math\">8(2) − 1 = 16 − 1 = <strong>15</strong></span>.<br><br>\n            <strong>(iii)</strong> <span class=\"math\">6x + 5(x − 2) = 6x + 5x − 10 = 11x − 10</span>.<br>\n            For <span class=\"math\">x = 2</span>: <span class=\"math\">11(2) − 10 = 22 − 10 = <strong>12</strong></span>.<br><br>\n            <strong>(iv)</strong> <span class=\"math\">4(2x − 1) + 3x + 11 = 8x − 4 + 3x + 11 = 11x + 7</span>.<br>\n            For <span class=\"math\">x = 2</span>: <span class=\"math\">11(2) + 7 = 22 + 7 = <strong>29</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Algebraic simplification and numerical evaluation for each</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n    <div class=\"q-card\" id=\"q10_1_2_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_1_2_def')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Identify the terms and their factors in the following expressions:<br>(a) −4x + 5 &nbsp;&nbsp; (b) −4x + 5y &nbsp;&nbsp; (c) 5y + 3y² &nbsp;&nbsp; (d) xy + 2x²y²</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) −4x + 5:</strong><br>\n            • Terms: <span class=\"math\">−4x</span> and <span class=\"math\">5</span>.<br>\n            • Factors: for <span class=\"math\">−4x</span> are <strong>−4, x</strong>; for <span class=\"math\">5</span> is <strong>5</strong>.<br><br>\n            <strong>(b) −4x + 5y:</strong><br>\n            • Terms: <span class=\"math\">−4x</span> and <span class=\"math\">5y</span>.<br>\n            • Factors: for <span class=\"math\">−4x</span> are <strong>−4, x</strong>; for <span class=\"math\">5y</span> are <strong>5, y</strong>.<br><br>\n            <strong>(c) 5y + 3y²:</strong><br>\n            • Terms: <span class=\"math\">5y</span> and <span class=\"math\">3y²</span>.<br>\n            • Factors: for <span class=\"math\">5y</span> are <strong>5, y</strong>; for <span class=\"math\">3y²</span> are <strong>3, y, y</strong>.<br><br>\n            <strong>(d) xy + 2x²y²:</strong><br>\n            • Terms: <span class=\"math\">xy</span> and <span class=\"math\">2x²y²</span>.<br>\n            • Factors: for <span class=\"math\">xy</span> are <strong>x, y</strong>; for <span class=\"math\">2x²y²</span> are <strong>2, x, x, y, y</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing terms and factors for each expression</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q10_2_7_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_2_7_def')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Simplify these expressions and find their values if x = 3, a = −1, b = −2:<br>(i) 3x − 5 − x + 9<br>(ii) 2 − 8x + 4x + 4<br>(iii) 3a + 5 − 8a + 1<br>(iv) 10 − 3b − 4 − 5b</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> <span class=\"math\">3x − x + 9 − 5 = 2x + 4</span>.<br>\n            For <span class=\"math\">x = 3</span>: <span class=\"math\">2(3) + 4 = 6 + 4 = <strong>10</strong></span>.<br><br>\n            <strong>(ii)</strong> <span class=\"math\">−8x + 4x + 2 + 4 = −4x + 6</span>.<br>\n            For <span class=\"math\">x = 3</span>: <span class=\"math\">−4(3) + 6 = −12 + 6 = <strong>−6</strong></span>.<br><br>\n            <strong>(iii)</strong> <span class=\"math\">3a − 8a + 5 + 1 = −5a + 6</span>.<br>\n            For <span class=\"math\">a = −1</span>: <span class=\"math\">−5(−1) + 6 = 5 + 6 = <strong>11</strong></span>.<br><br>\n            <strong>(iv)</strong> <span class=\"math\">10 − 4 − 3b − 5b = 6 − 8b</span>.<br>\n            For <span class=\"math\">b = −2</span>: <span class=\"math\">6 − 8(−2) = 6 + 16 = <strong>22</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Simplification and numerical evaluation</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q10_2_8_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_2_8_def')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">(i) If z = 10, find the value of z³ − 3(z − 10).<br>(ii) If p = −10, find the value of p² − 2p − 100.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> Given expression: <span class=\"math\">z^3 − 3(z − 10)</span>.<br>\n            Substitute <span class=\"math\">z = 10</span>:<br>\n            <span class=\"math\">= 10^3 − 3(10 − 10) = 1000 − 3(0) = 1000 − 0 = <strong>1000</strong></span>.<br><br>\n            <strong>(ii)</strong> Given expression: <span class=\"math\">p^2 − 2p − 100</span>.<br>\n            Substitute <span class=\"math\">p = −10</span>:<br>\n            <span class=\"math\">= (−10)^2 − 2(−10) − 100 = 100 + 20 − 100 = <strong>20</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Value of (i) = 1000</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Value of (ii) = 20</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\">\r\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\r\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\r\n    </div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">HOTS: Constant Determination</div>\r\n        <div class=\"cbq-question\"><strong>Problem:</strong> What should be the value of <span class=\"math\">a</span> if the value of <span class=\"math\">2x² + x − a</span> equals 5, when <span class=\"math\">x = 0</span>?</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <p>Given equation condition: <span class=\"math\">2x² + x − a = 5</span> when <span class=\"math\">x = 0</span>.</p>\r\n          <p>Substitute <span class=\"math\">x = 0</span> into the expression:<br>\r\n          <span class=\"math\">2(0)² + 0 − a = 5</span><br>\r\n          <span class=\"math\">0 + 0 − a = 5 ⇒ −a = 5 ⇒ <strong>a = −5</strong></span>.</p>\r\n          <p><strong>Conclusion:</strong> The value of <span class=\"math\">a</span> is <strong>−5</strong>.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(9)\">← Chapter 9: Perimeter &amp; Area</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(11)\">Chapter 11: Exponents &amp; Powers →</button>\r\n  </div>\r\n</section>\r\n","11":"<section class=\"chapter-section\" id=\"ch11\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">11</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 11: Exponents and Powers</h2>\r\n      <p>NCERT Exercise 11.1 to 11.3 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"concept-card\">\r\n    <div class=\"concept-header\">📌 Key Concepts &amp; Laws of Exponents Summary</div>\r\n    <ul class=\"concept-list\">\r\n      <li><strong>Exponential Form:</strong> Repeated multiplication written concisely: a × a × a ... (n times) = aⁿ, where a is the <strong>base</strong> and n is the <strong>exponent</strong>.</li>\r\n      <li><strong>Laws of Exponents (for non-zero integers a, b and whole numbers m, n):</strong>\r\n        <ul>\r\n          <li><em>Multiplying powers with same base:</em> aᵐ × aⁿ = aᵐ⁺ⁿ.</li>\r\n          <li><em>Dividing powers with same base:</em> aᵐ ÷ aⁿ = aᵐ⁻ⁿ (m > n).</li>\r\n          <li><em>Power of a power:</em> (aᵐ)ⁿ = aᵐⁿ.</li>\r\n          <li><em>Multiplying powers with same exponents:</em> aᵐ × bᵐ = (a × b)ᵐ = (ab)ᵐ.</li>\r\n          <li><em>Dividing powers with same exponents:</em> aᵐ ÷ bᵐ = (a/b)ᵐ.</li>\r\n          <li><em>Zero Exponent:</em> a⁰ = 1.</li>\r\n          <li><em>Powers of -1:</em> (-1)eveⁿ = +1, (-1)odd = -1.</li>\r\n        </ul>\r\n      </li>\r\n      <li><strong>Standard Form (Scientific Notation):</strong>\r\n        Any number can be expressed as k × 10ⁿ, where 1 ≤ k < 10 and n is an integer. Used to write very large numbers compactly.\r\n      </li>\r\n    </ul>\r\n  </div>\r\n\r\n  <!-- EXERCISE 11.1 -->\r\n  <div class=\"ex-div\">Exercise 11.1</div>\r\n\r\n  <div class=\"q-card\" id=\"q11_1_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_1_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Find the value of:<br>(i) 2⁶<br>(ii) 9³<br>(iii) 11²<br>(iv) 5⁴</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">2⁶ = 2 × 2 × 2 × 2 × 2 × 2 = <strong>64</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) <span class=\"math\">9³ = 9 × 9 × 9 = 81 × 9 = <strong>729</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) <span class=\"math\">11² = 11 × 11 = <strong>121</strong></span></strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iv) <span class=\"math\">5⁴ = 5 × 5 × 5 × 5 = 25 × 25 = <strong>625</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation</span><span class=\"marking-marks\">0.5 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q11_1_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_1_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Express each of the following as product of powers of their prime factors:<br>(i) 648<br>(ii) 405<br>(iii) 540<br>(iv) 3,600</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) 648:</strong><br>\r\n            <span class=\"math\">648 = 2 × 324 = 2 × 2 × 162 = 2 × 2 × 2 × 81 = 2³ × 3⁴ = <strong>2³ × 3⁴</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) 405:</strong><br>\r\n            <span class=\"math\">405 = 5 × 81 = 5 × 3⁴ = <strong>3⁴ × 5</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) 540:</strong><br>\r\n            <span class=\"math\">540 = 2 × 270 = 2 × 2 × 135 = 2² × 3 × 45 = 2² × 3³ × 5 = <strong>2² × 3³ × 5</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iv) 3,600:</strong><br>\r\n            <span class=\"math\">3600 = 36 × 100 = (2² × 3²) × (2² × 5²) = <strong>2⁴ × 3² × 5²</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Prime factorisation steps and final exponential notation</span><span class=\"marking-marks\">3 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q11_1_3\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_1_3')\">\r\n      <div class=\"q-num\">Q3</div>\r\n      <div class=\"q-text\">Identify the greater number, wherever possible, in each of the following:<br>(i) 4³ or 3⁴<br>(ii) 5³ or 3⁵<br>(iii) 2⁸ or 8²<br>(iv) 100² or 2¹⁰⁰</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) 4³ vs 3⁴:</strong><br>\r\n            <span class=\"math\">4³ = 4 × 4 × 4 = 64</span>.<br>\r\n            <span class=\"math\">3⁴ = 3 × 3 × 3 × 3 = 81</span>.<br>\r\n            Since <span class=\"math\">81 > 64 ⇒ <strong>3⁴ > 4³</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) 5³ vs 3⁵:</strong><br>\r\n            <span class=\"math\">5³ = 125</span>.<br>\r\n            <span class=\"math\">3⁵ = 243</span>.<br>\r\n            Since <span class=\"math\">243 > 125 ⇒ <strong>3⁵ > 5³</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) 2⁸ vs 8²:</strong><br>\r\n            <span class=\"math\">2⁸ = 256</span>.<br>\r\n            <span class=\"math\">8² = 64</span>.<br>\r\n            Since <span class=\"math\">256 > 64 ⇒ <strong>2⁸ > 8²</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iv) 100² vs 2¹⁰⁰:</strong><br>\r\n            <span class=\"math\">100² = 10,000</span>.<br>\r\n            Notice <span class=\"math\">2¹⁰ = 1024 > 1000 ⇒ 2¹⁰⁰ = (2¹⁰)¹⁰ > (10³)¹⁰ = 10³⁰</span>.<br>\r\n            Hence, <span class=\"math\"><strong>2¹⁰⁰ > 100²</strong></span> by an enormous margin.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation &amp; comparison</span><span class=\"marking-marks\">0.75 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 11.2 -->\r\n  <div class=\"ex-div\">Exercise 11.2 (Laws of Exponents)</div>\r\n\r\n  <div class=\"q-card\" id=\"q11_2_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_2_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Using laws of exponents, simplify and write the answer in exponential form:<br>(i) 3² × 3⁴ × 3⁸<br>(ii) 6¹⁵ ÷ 6¹⁰<br>(iii) a³ × a²<br>(iv) 7ˣ × 7²<br>(v) (5²)³ ÷ 5³<br>(vi) 2⁵ × 5⁵<br>(vii) (2²⁰ ÷ 2¹⁵) × 2³<br>(viii) 8ᵗ ÷ 8²</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">3² × 3⁴ × 3⁸ = 3² ⁺ ⁴ ⁺ ⁸ = <strong>3¹⁴</strong></span></strong> &nbsp;<em>[Law: aᵐ × aⁿ = aᵐ⁺ⁿ]</em><br>\r\n            <strong>(ii) <span class=\"math\">6¹⁵ ÷ 6¹⁰ = 6¹⁵ ⁻ ¹⁰ = <strong>6⁵</strong></span></strong> &nbsp;<em>[Law: aᵐ ÷ aⁿ = aᵐ⁻ⁿ]</em><br>\r\n            <strong>(iii) <span class=\"math\">a³ × a² = a³ ⁺ ² = <strong>a⁵</strong></span></strong><br>\r\n            <strong>(iv) <span class=\"math\">7ˣ × 7² = <strong>7ˣ⁺²</strong></span></strong><br>\r\n            <strong>(v) <span class=\"math\">(5²)³ ÷ 5³ = 5² × ³ ÷ 5³ = 5⁶ ÷ 5³ = 5⁶ ⁻ ³ = <strong>5³</strong></span></strong><br>\r\n            <strong>(vi) <span class=\"math\">2⁵ × 5⁵ = (2 × 5)⁵ = <strong>10⁵</strong></span></strong> &nbsp;<em>[Law: aᵐ × bᵐ = (ab)ᵐ]</em><br>\r\n            <strong>(vii) <span class=\"math\">(2²⁰ ÷ 2¹⁵) × 2³ = 2²⁰ ⁻ ¹⁵ × 2³ = 2⁵ × 2³ = 2⁵ ⁺ ³ = <strong>2⁸</strong></span></strong><br>\r\n            <strong>(viii) <span class=\"math\">8^t ÷ 8² = <strong>8t⁻²</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Applying exponent law formulas correctly</span><span class=\"marking-marks\">2 Marks</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">All 8 simplified exponential results</span><span class=\"marking-marks\">2 Marks</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q11_2_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_2_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Simplify and express each of the following in exponential form:<br>(i) (2³ × 3⁴ × 4) / (3 × 32)<br>(ii) [(5²)³ × 5⁴] ÷ 5⁷<br>(iii) 25⁴ ÷ 5³<br>(iv) (3 × 7² × 11⁸) / (21 × 11³)</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) <span class=\"math\">(2³ × 3⁴ × 4)/(3 × 32)</span>:</strong><br>\r\n            Express in prime factors: <span class=\"math\">4 = 2²</span>, <span class=\"math\">32 = 2⁵</span>.<br>\r\n            <span class=\"math\">= (2³ × 3⁴ × 2²)/(3¹ × 2⁵) = (2³⁺² × 3⁴)/(2⁵ × 3¹) = (2⁵ × 3⁴)/(2⁵ × 3¹) = 2⁵⁻⁵ × 3⁴⁻¹ = 2⁰ × 3³ = 1 × 3³ = <strong>3³</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) <span class=\"math\">[(5²)³ × 5⁴] ÷ 5⁷</span>:</strong><br>\r\n            <span class=\"math\">= [5² × ³ × 5⁴] ÷ 5⁷ = [5⁶ × 5⁴] ÷ 5⁷ = 5⁶⁺⁴ ÷ 5⁷ = 5¹⁰ ÷ 5⁷ = 5¹⁰⁻⁷ = <strong>5³</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) <span class=\"math\">25⁴ ÷ 5³</span>:</strong><br>\r\n            Write <span class=\"math\">25 = 5² ⇒ (5²)⁴ ÷ 5³ = 5⁸ ÷ 5³ = 5⁸⁻³ = <strong>5⁵</strong></span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iv) <span class=\"math\">(3 × 7² × 11⁸)/(21 × 11³)</span>:</strong><br>\r\n            Write <span class=\"math\">21 = 3 × 7</span>.<br>\r\n            <span class=\"math\">= (3¹ × 7² × 11⁸)/(3¹ × 7¹ × 11³) = 3¹⁻¹ × 7²⁻¹ × 11⁸⁻³ = 3⁰ × 7¹ × 11⁵ = 1 × 7 × 11⁵ = <strong>7 × 11⁵</strong></span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each part: Prime base conversion &amp; exponent law steps</span><span class=\"marking-marks\">1 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 11.3 -->\r\n  <div class=\"ex-div\">Exercise 11.3 (Expanded Form &amp; Scientific Notation)</div>\r\n\r\n  <div class=\"q-card\" id=\"q11_3_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_3_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Write the following numbers in expanded forms using powers of 10:<br>(i) 279404<br>(ii) 3006194<br>(iii) 2806196</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(i) 279404:</strong><br>\r\n            <span class=\"math\">= 2 × 10⁵ + 7 × 10⁴ + 9 × 10³ + 4 × 10² + 0 × 10¹ + 4 × 10⁰</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) 3006194:</strong><br>\r\n            <span class=\"math\">= 3 × 10⁶ + 0 × 10⁵ + 0 × 10⁴ + 6 × 10³ + 1 × 10² + 9 × 10¹ + 4 × 10⁰</span>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(iii) 2806196:</strong><br>\r\n            <span class=\"math\">= 2 × 10⁶ + 8 × 10⁵ + 0 × 10⁴ + 6 × 10³ + 1 × 10² + 9 × 10¹ + 6 × 10⁰</span>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct expanded power-of-10 representation</span><span class=\"marking-marks\">1 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q11_3_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q11_3_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Express the following in standard scientific form (k × 10ⁿ):<br>(a) 5,00,00,000<br>(b) 70,00,000<br>(c) 3,18,65,00,000<br>(d) 39087.8<br>(e) Distance between Sun and Earth = 149,600,000,000 m<br>(f) Speed of light in vacuum = 300,000,000 m/s</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p>Scientific notation format: <span class=\"math\">k × 10ⁿ</span> where <span class=\"math\">1 ≤ k < 10</span>.</p>\r\n          <div class=\"step\">\r\n            <strong>(a) <span class=\"math\">5,00,00,000 = <strong>5.0 × 10⁷</strong></span></strong><br>\r\n            <strong>(b) <span class=\"math\">70,00,000 = <strong>7.0 × 10⁶</strong></span></strong><br>\r\n            <strong>(c) <span class=\"math\">3,18,65,00,000 = <strong>3.1865 × 10⁹</strong></span></strong><br>\r\n            <strong>(d) <span class=\"math\">39087.8 = <strong>3.90878 × 10⁴</strong></span></strong><br>\r\n            <strong>(e) <span class=\"math\">149,600,000,000 m = <strong>1.496 × 10¹¹ m</strong></span></strong><br>\r\n            <strong>(f) <span class=\"math\">300,000,000 m/s = <strong>3.0 × 10⁸ m/s</strong></span></strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct standard form representation</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n    <div class=\"q-card\" id=\"q11_3_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_3_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Express the number appearing in the following statements in standard form:<br>(a) The distance between Earth and Moon is 384,000,000 m.<br>(b) Speed of light in vacuum is 300,000,000 m/s.<br>(c) Diameter of the Earth is 1,27,56,000 m.<br>(d) Diameter of the Sun is 1,400,000,000 m.<br>(e) In a galaxy there are on an average 100,000,000,000 stars.</div>\n      <div class=\"q-marks\">5 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <em>Standard scientific notation: <span class=\"math\">k × 10ⁿ</span> where <span class=\"math\">1 ≤ k &lt; 10</span></em>.<br>\n            <strong>(a)</strong> <span class=\"math\">384,000,000 m = <strong>3.84 × 10⁸ m</strong></span><br>\n            <strong>(b)</strong> <span class=\"math\">300,000,000 m/s = <strong>3.0 × 10⁸ m/s</strong></span><br>\n            <strong>(c)</strong> <span class=\"math\">12,756,000 m = <strong>1.2756 × 10⁷ m</strong></span><br>\n            <strong>(d)</strong> <span class=\"math\">1,400,000,000 m = <strong>1.4 × 10⁹ m</strong></span><br>\n            <strong>(e)</strong> <span class=\"math\">100,000,000,000 = <strong>1.0 × 10¹¹ stars</strong></span>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct standard form representation with accurate power of 10</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q11_1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Identify the greater number, wherever possible, in each of the following:<br>(i) 4³ or 3⁴<br>(ii) 5³ or 3⁵<br>(iii) 2⁸ or 8²<br>(iv) 100² or 2¹⁰⁰<br>(v) 2¹⁰ or 10²</div>\n      <div class=\"q-marks\">5 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> <span class=\"math\">4³ = 64</span> and <span class=\"math\">3⁴ = 81</span>. Since <span class=\"math\">81 &gt; 64</span>, <strong>3⁴ is greater</strong>.<br>\n            <strong>(ii)</strong> <span class=\"math\">5³ = 125</span> and <span class=\"math\">3⁵ = 243</span>. Since <span class=\"math\">243 &gt; 125</span>, <strong>3⁵ is greater</strong>.<br>\n            <strong>(iii)</strong> <span class=\"math\">2⁸ = 256</span> and <span class=\"math\">8² = 64</span>. Since <span class=\"math\">256 &gt; 64</span>, <strong>2⁸ is greater</strong>.<br>\n            <strong>(iv)</strong> <span class=\"math\">100² = 10,000</span>. Since <span class=\"math\">2¹⁰ = 1024</span>, <span class=\"math\">2¹⁰⁰ = (2¹⁰)¹⁰ = (1024)¹⁰ &gt;&gt; 10,000</span>. <strong>2¹⁰⁰ is much greater</strong>.<br>\n            <strong>(v)</strong> <span class=\"math\">2¹⁰ = 1024</span> and <span class=\"math\">10² = 100</span>. Since <span class=\"math\">1024 &gt; 100</span>, <strong>2¹⁰ is greater</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each comparison evaluated accurately</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q11_1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Identify the greater number, wherever possible, in each of the following:<br>(i) 4³ or 3⁴ &nbsp;&nbsp; (ii) 5³ or 3⁵ &nbsp;&nbsp; (iii) 2⁸ or 8² &nbsp;&nbsp; (iv) 100² or 2¹⁰⁰ &nbsp;&nbsp; (v) 2¹⁰ or 10²</div>\n      <div class=\"q-marks\">5 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) 4³ or 3⁴:</strong><br>\n            <span class=\"math\">4^3 = 4 × 4 × 4 = 64</span><br>\n            <span class=\"math\">3^4 = 3 × 3 × 3 × 3 = 81</span><br>\n            Since 81 > 64, <strong>3⁴ > 4³</strong>.<br><br>\n            <strong>(ii) 5³ or 3⁵:</strong><br>\n            <span class=\"math\">5^3 = 125</span>, <span class=\"math\">3^5 = 243</span>. Since 243 > 125, <strong>3⁵ > 5³</strong>.<br><br>\n            <strong>(iii) 2⁸ or 8²:</strong><br>\n            <span class=\"math\">2^8 = 256</span>, <span class=\"math\">8^2 = 64</span>. Since 256 > 64, <strong>2⁸ > 8²</strong>.<br><br>\n            <strong>(iv) 100² or 2¹⁰⁰:</strong><br>\n            <span class=\"math\">100^2 = 10,000</span>.<br>\n            <span class=\"math\">2^{10} = 1024 > 10^3 ⟹ 2^{100} = (2^{10})^{10} > (10^3)^{10} = 10^{30}</span>.<br>\n            Clearly, <strong>2¹⁰⁰ is vastly greater than 100²</strong>.<br><br>\n            <strong>(v) 2¹⁰ or 10²:</strong><br>\n            <span class=\"math\">2^{10} = 1024</span>, <span class=\"math\">10^2 = 100</span>. Since 1024 > 100, <strong>2¹⁰ > 10²</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluation of exponential powers and correct comparison</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q11_1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Express each of the following as product of powers of their prime factors:<br>(i) 648 &nbsp;&nbsp; (ii) 405 &nbsp;&nbsp; (iii) 540 &nbsp;&nbsp; (iv) 3600</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Prime factorisation:<br>\n            <strong>(i) 648:</strong><br>\n            <span class=\"math\">648 = 2 × 324 = 2 × 2 × 162 = 2 × 2 × 2 × 81 = 2^3 × 3^4 = <strong>2³ × 3⁴</strong></span>.<br><br>\n            <strong>(ii) 405:</strong><br>\n            <span class=\"math\">405 = 3 × 135 = 3 × 3 × 45 = 3 × 3 × 3 × 15 = 3^4 × 5 = <strong>3⁴ × 5</strong></span>.<br><br>\n            <strong>(iii) 540:</strong><br>\n            <span class=\"math\">540 = 2 × 270 = 2 × 2 × 135 = 2^2 × 3 × 45 = 2^2 × 3^3 × 5 = <strong>2² × 3³ × 5</strong></span>.<br><br>\n            <strong>(iv) 3600:</strong><br>\n            <span class=\"math\">3600 = 36 × 100 = (2^2 × 3^2) × (2^2 × 5^2) = 2^4 × 3^2 × 5^2 = <strong>2⁴ × 3² × 5²</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct prime factorisation and exponential form</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q11_1_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_1_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Simplify:<br>(i) 2 × 10³ &nbsp;&nbsp; (ii) 7² × 2² &nbsp;&nbsp; (iii) 2³ × 5 &nbsp;&nbsp; (iv) 3 × 4⁴ &nbsp;&nbsp; (v) 0 × 10² &nbsp;&nbsp; (vi) 5² × 3³</div>\n      <div class=\"q-marks\">3 Marks (1/2 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> <span class=\"math\">2 × 10^3 = 2 × 1000 = <strong>2,000</strong></span>.<br>\n            <strong>(ii)</strong> <span class=\"math\">7^2 × 2^2 = 49 × 4 = <strong>196</strong></span>.<br>\n            <strong>(iii)</strong> <span class=\"math\">2^3 × 5 = 8 × 5 = <strong>40</strong></span>.<br>\n            <strong>(iv)</strong> <span class=\"math\">3 × 4^4 = 3 × 256 = <strong>768</strong></span>.<br>\n            <strong>(v)</strong> <span class=\"math\">0 × 10^2 = 0 × 100 = <strong>0</strong></span>.<br>\n            <strong>(vi)</strong> <span class=\"math\">5^2 × 3^3 = 25 × 27 = <strong>675</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaluation of each product</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q11_2_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_2_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Say true or false and justify your answer:<br>(i) 10 × 10¹¹ = 100¹¹<br>(ii) 2³ > 5²<br>(iii) 2³ × 3² = 6⁵<br>(iv) 3⁰ = (1000)⁰</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) 10 × 10¹¹ = 100¹¹:</strong> <strong>False</strong>.<br>\n            LHS = <span class=\"math\">10^1 × 10^{11} = 10^{1+11} = 10^{12}</span>.<br>\n            RHS = <span class=\"math\">100^{11} = (10^2)^{11} = 10^{22}</span>. Since <span class=\"math\">10^{12} ≠ 10^{22}</span>, statement is false.<br><br>\n            <strong>(ii) 2³ > 5²:</strong> <strong>False</strong>.<br>\n            LHS = <span class=\"math\">2^3 = 8</span>, RHS = <span class=\"math\">5^2 = 25</span>. Since 8 < 25, statement is false.<br><br>\n            <strong>(iii) 2³ × 3² = 6⁵:</strong> <strong>False</strong>.<br>\n            LHS = <span class=\"math\">8 × 9 = 72</span>, RHS = <span class=\"math\">6^5 = 7776</span>. Since <span class=\"math\">72 ≠ 7776</span>, statement is false.<br><br>\n            <strong>(iv) 3⁰ = (1000)⁰:</strong> <strong>True</strong>.<br>\n            Any non-zero number raised to exponent 0 equals 1: <span class=\"math\">3^0 = 1</span> and <span class=\"math\">(1000)^0 = 1</span>. Both sides equal 1.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">True/False judgment with mathematical justification</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n    <div class=\"q-card\" id=\"q11_1_3_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_1_3_def')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Express each of the following numbers using exponential notation:<br>(i) 512 &nbsp;&nbsp; (ii) 343 &nbsp;&nbsp; (iii) 729 &nbsp;&nbsp; (iv) 3125</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) 512:</strong> <span class=\"math\">512 = 2 × 2 × 2 × 2 × 2 × 2 × 2 × 2 × 2 = <strong>2⁹</strong></span>.<br>\n            <strong>(ii) 343:</strong> <span class=\"math\">343 = 7 × 7 × 7 = <strong>7³</strong></span>.<br>\n            <strong>(iii) 729:</strong> <span class=\"math\">729 = 3 × 3 × 3 × 3 × 3 × 3 = <strong>3⁶</strong></span> (or <span class=\"math\">9^3</span>).<br>\n            <strong>(iv) 3125:</strong> <span class=\"math\">3125 = 5 × 5 × 5 × 5 × 5 = <strong>5⁵</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Prime factorization and exponential notation</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q11_2_4_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_2_4_def')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Express each of the following as a product of prime factors only in exponential form:<br>(i) 108 × 192 &nbsp;&nbsp; (ii) 270 &nbsp;&nbsp; (iii) 729 × 64 &nbsp;&nbsp; (iv) 768</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) 108 × 192:</strong><br>\n            <span class=\"math\">108 = 2^2 × 3^3</span>, <span class=\"math\">192 = 2^6 × 3^1</span>.<br>\n            <span class=\"math\">108 × 192 = 2^{2+6} × 3^{3+1} = <strong>2⁸ × 3⁴</strong></span>.<br><br>\n            <strong>(ii) 270:</strong><br>\n            <span class=\"math\">270 = 2 × 135 = 2 × 3 × 45 = 2 × 3 × 3 × 15 = <strong>2 × 3³ × 5</strong></span>.<br><br>\n            <strong>(iii) 729 × 64:</strong><br>\n            <span class=\"math\">729 = 3^6</span>, <span class=\"math\">64 = 2^6</span>.<br>\n            Product = <span class=\"math\"><strong>2⁶ × 3⁶</strong></span>.<br><br>\n            <strong>(iv) 768:</strong><br>\n            <span class=\"math\">768 = 2^8 × 3 = <strong>2⁸ × 3</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Product of prime powers in exponential form</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q11_3_3_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_3_3_def')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Express the following numbers in standard scientific form:<br>(i) 5,00,00,000 &nbsp;&nbsp; (ii) 70,00,000 &nbsp;&nbsp; (iii) 3,18,65,00,000 &nbsp;&nbsp; (iv) 3,90,878</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            In standard form, a number is written as <span class=\"math\">m × 10^n</span> where <span class=\"math\">1 ≤ m < 10</span>:<br>\n            <strong>(i) 5,00,00,000 = <strong>5.0 × 10⁷</strong></strong>.<br>\n            <strong>(ii) 70,00,000 = <strong>7.0 × 10⁶</strong></strong>.<br>\n            <strong>(iii) 3,18,65,00,000 = <strong>3.1865 × 10⁹</strong></strong>.<br>\n            <strong>(iv) 3,90,878 = <strong>3.90878 × 10⁵</strong></strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Standard exponential scientific form</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\">\r\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\r\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\r\n    </div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">HOTS: Finding Unknown Exponent</div>\r\n        <div class=\"cbq-question\"><strong>Problem:</strong> Find the value of <span class=\"math\">x</span> in the equation: <span class=\"math\">(2/5)³ × (2/5)⁶ = (2/5)³ˣ</span>.</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <p>Using law <span class=\"math\">aᵐ × aⁿ = aᵐ⁺ⁿ</span> on LHS:<br>\r\n          <span class=\"math\">(2/5)³ ⁺ ⁶ = (2/5)³ˣ</span><br>\r\n          <span class=\"math\">(2/5)⁹ = (2/5)³ˣ</span>.</p>\r\n          <p>Equating exponents since bases are identical:<br>\r\n          <span class=\"math\">3x = 9 ⇒ x = 9/3 = <strong>3</strong></span>.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(10)\">← Chapter 10: Algebraic Expressions</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(12)\">Chapter 12: Symmetry →</button>\r\n  </div>\r\n</section>\r\n","12":"<section class=\"chapter-section\" id=\"ch12\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">12</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 12: Symmetry</h2>\r\n      <p>NCERT Exercise 12.1 to 12.3 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"concept-card\">\r\n    <div class=\"concept-header\">📌 Key Concepts &amp; Symmetry Properties Summary</div>\r\n    <ul class=\"concept-list\">\r\n      <li><strong>Line Symmetry:</strong> A figure has line symmetry if a line can be drawn dividing it into two identical halves that coincide exactly when folded along that line.</li>\r\n      <li><strong>Lines of Symmetry for Regular Polygons:</strong>\r\n        Each regular polygon of n sides has exactly n lines of symmetry:\r\n        <ul>\r\n          <li>Equilateral triangle: 3 lines</li>\r\n          <li>Square: 4 lines</li>\r\n          <li>Regular pentagon: 5 lines</li>\r\n          <li>Regular hexagon: 6 lines</li>\r\n          <li>Circle: Infinitely many lines (along any diameter)</li>\r\n        </ul>\r\n      </li>\r\n      <li><strong>Rotational Symmetry:</strong> When a figure rotated around a fixed point (centre of rotation) by an angle ≤ 360° looks exactly the same as in its original orientation.</li>\r\n      <li><strong>Order of Rotational Symmetry:</strong> The number of times a figure fits onto itself in one full 360° rotation:\r\n        Order = 360°/(Angle of rotation)\r\n      </li>\r\n      <li><strong>Dual Symmetry:</strong> Figures possessing both line symmetry and rotational symmetry of order > 1 (e.g. Equilateral triangle, square, rectangle, circle, and English letters H, I, O, X).</li>\r\n    </ul>\r\n  </div>\r\n\r\n  <!-- EXERCISE 12.1 -->\r\n  <div class=\"ex-div\">Exercise 12.1 (Line Symmetry)</div>\r\n\r\n  <div class=\"q-card\" id=\"q12_1_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_1_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">State the number of lines of symmetry for the following figures:<br>(a) An equilateral triangle<br>(b) An isosceles triangle<br>(c) A scalene triangle<br>(d) A square<br>(e) A rectangle<br>(f) A rhombus<br>(g) A parallelogram<br>(h) A quadrilateral<br>(i) A regular hexagon<br>(j) A circle</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) Equilateral Triangle:</strong> <strong>3 lines of symmetry</strong> (each altitude/median).<br>\r\n            <strong>(b) Isosceles Triangle:</strong> <strong>1 line of symmetry</strong> (bisector of vertex angle).<br>\r\n            <strong>(c) Scalene Triangle:</strong> <strong>0 lines of symmetry</strong> (none of the sides or angles are equal).<br>\r\n            <strong>(d) Square:</strong> <strong>4 lines of symmetry</strong> (2 diagonals + 2 perpendicular bisectors of opposite sides).<br>\r\n            <strong>(e) Rectangle:</strong> <strong>2 lines of symmetry</strong> (perpendicular bisectors of opposite sides).<br>\r\n            <strong>(f) Rhombus:</strong> <strong>2 lines of symmetry</strong> (along the two diagonals).<br>\r\n            <strong>(g) Parallelogram:</strong> <strong>0 lines of symmetry</strong> (in general, cannot be folded to coincide).<br>\r\n            <strong>(h) Quadrilateral:</strong> <strong>0 lines of symmetry</strong> (in general).<br>\r\n            <strong>(i) Regular Hexagon:</strong> <strong>6 lines of symmetry</strong> (3 joining opposite vertices + 3 joining midpoints of opposite sides).<br>\r\n            <strong>(j) Circle:</strong> <strong>Infinitely many lines of symmetry</strong> (any straight line through the centre / diameter).\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct geometric figure symmetry count</span><span class=\"marking-marks\">0.4 Mark each (4 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q12_1_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_1_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">What letters of the English alphabet have reflectional symmetry (i.e. symmetry related to mirror reflection) about:<br>(a) a vertical mirror<br>(b) a horizontal mirror<br>(c) both horizontal and vertical mirrors</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) Vertical Mirror Symmetry (Left-Right reflection):</strong><br>\r\n            Letters: <strong>A, H, I, M, O, T, U, V, W, X, Y</strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) Horizontal Mirror Symmetry (Top-Bottom reflection):</strong><br>\r\n            Letters: <strong>B, C, D, E, H, I, K, O, X</strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) Both Horizontal and Vertical Mirrors:</strong><br>\r\n            Letters in the intersection of both sets: <strong>H, I, O, X</strong>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): Vertical symmetry letters</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): Horizontal symmetry letters</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (c): Both vertical &amp; horizontal (H, I, O, X)</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 12.2 -->\r\n  <div class=\"ex-div\">Exercise 12.2 (Rotational Symmetry)</div>\r\n\r\n  <div class=\"q-card\" id=\"q12_2_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_2_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Give the order of the rotational symmetry and the angle of rotation for each of the following figures:<br>(a) Square<br>(b) Rectangle<br>(c) Rhombus<br>(d) Equilateral triangle<br>(e) Regular hexagon<br>(f) Circle</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) Square:</strong><br>\r\n            • Centre of rotation: Intersection of diagonals.<br>\r\n            • Angle of rotation: <span class=\"math\">360°/4 = <strong>90°</strong></span>.<br>\r\n            • Order of rotational symmetry = <strong>4</strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) Rectangle:</strong><br>\r\n            • Centre of rotation: Intersection of diagonals.<br>\r\n            • Angle of rotation: <span class=\"math\">360°/2 = <strong>180°</strong></span>.<br>\r\n            • Order of rotational symmetry = <strong>2</strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) Rhombus:</strong><br>\r\n            • Centre of rotation: Intersection of diagonals.<br>\r\n            • Angle of rotation: <span class=\"math\">360°/2 = <strong>180°</strong></span>.<br>\r\n            • Order of rotational symmetry = <strong>2</strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(d) Equilateral Triangle:</strong><br>\r\n            • Centre of rotation: Centroid (intersection of medians).<br>\r\n            • Angle of rotation: <span class=\"math\">360°/3 = <strong>120°</strong></span>.<br>\r\n            • Order of rotational symmetry = <strong>3</strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(e) Regular Hexagon:</strong><br>\r\n            • Centre of rotation: Centre of hexagon.<br>\r\n            • Angle of rotation: <span class=\"math\">360°/6 = <strong>60°</strong></span>.<br>\r\n            • Order of rotational symmetry = <strong>6</strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(f) Circle:</strong><br>\r\n            • Centre of rotation: Centre of circle.<br>\r\n            • Angle of rotation: <strong>Any angle θ</strong>.<br>\r\n            • Order of rotational symmetry = <strong>Infinitely many</strong>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each figure: Order and angle of rotation</span><span class=\"marking-marks\">0.5 Mark each (3 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q12_2_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_2_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Can we have a rotational symmetry of order more than 1 whose angle of rotation is:<br>(i) 45°?<br>(ii) 17°?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p><strong>Rule:</strong> A figure can have rotational symmetry if and only if the angle of rotation divides <span class=\"math\">360°</span> completely without a remainder.</p>\r\n          <div class=\"step\">\r\n            <strong>(i) Angle of rotation = 45°:</strong><br>\r\n            <span class=\"math\">360°/45° = 8</span> (an exact integer).<br>\r\n            <strong>Yes</strong>, we can have a rotational symmetry of order 8 (e.g. a regular octagon).\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(ii) Angle of rotation = 17°:</strong><br>\r\n            <span class=\"math\">360°/17° = 21.176...</span> (not an integer).<br>\r\n            <strong>No</strong>, since 360° is not divisible by 17°, a rotational symmetry of order more than 1 is not possible.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): Yes with division 360/45 = 8</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): No with divisibility justification</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 12.3 -->\r\n  <div class=\"ex-div\">Exercise 12.3 (Dual Symmetry)</div>\r\n\r\n  <div class=\"q-card\" id=\"q12_3_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q12_3_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Name any two figures that have both line symmetry and rotational symmetry.</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>1. A Square:</strong><br>\r\n            • Has 4 lines of symmetry.<br>\r\n            • Has rotational symmetry of order 4 (angle of rotation = 90°).\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>2. An Equilateral Triangle:</strong><br>\r\n            • Has 3 lines of symmetry.<br>\r\n            • Has rotational symmetry of order 3 (angle of rotation = 120°).<br>\r\n            <em>(A Circle or Regular Hexagon are also valid examples).</em>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct geometric figure with its dual symmetry properties</span><span class=\"marking-marks\">1 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n    <div class=\"q-card\" id=\"q12_1_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_1_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">State the number of lines of symmetry for the following figures:<br>(a) An equilateral triangle<br>(b) An isosceles triangle<br>(c) A scalene triangle<br>(d) A square<br>(e) A rectangle<br>(f) A rhombus<br>(g) A parallelogram<br>(h) A quadrilateral<br>(i) A regular hexagon<br>(j) A circle</div>\n      <div class=\"q-marks\">5 Marks (1/2 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Equilateral triangle:</strong> <strong>3 lines of symmetry</strong>.<br>\n            <strong>(b) Isosceles triangle:</strong> <strong>1 line of symmetry</strong>.<br>\n            <strong>(c) Scalene triangle:</strong> <strong>0 (no line of symmetry)</strong>.<br>\n            <strong>(d) Square:</strong> <strong>4 lines of symmetry</strong>.<br>\n            <strong>(e) Rectangle:</strong> <strong>2 lines of symmetry</strong>.<br>\n            <strong>(f) Rhombus:</strong> <strong>2 lines of symmetry</strong>.<br>\n            <strong>(g) Parallelogram:</strong> <strong>0 lines of symmetry</strong>.<br>\n            <strong>(h) Quadrilateral:</strong> <strong>0 lines of symmetry</strong>.<br>\n            <strong>(i) Regular hexagon:</strong> <strong>6 lines of symmetry</strong>.<br>\n            <strong>(j) Circle:</strong> <strong>Infinitely many lines of symmetry</strong> (any diameter).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct geometric count of lines of symmetry</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q12_3_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_3_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Can we have a rotational symmetry of order more than 1 whose angle of rotation is:<br>(i) 45°?<br>(ii) 17°?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <em>Rule: A figure has rotational symmetry of order &gt; 1 if and only if 360° is exactly divisible by the angle of rotation.</em><br>\n            <strong>(i) 45°:</strong><br>\n            <span class=\"math\">360° ÷ 45° = 8</span> (an exact whole number).<br>\n            <strong>Yes</strong>, a figure can have rotational symmetry of order <strong>8</strong> with angle of rotation 45°.<br>\n            <strong>(ii) 17°:</strong><br>\n            <span class=\"math\">360° ÷ 17° = 21.176...</span> (not an integer).<br>\n            <strong>No</strong>, a figure cannot have rotational symmetry of order more than 1 with an angle of 17°.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): Yes, 360/45 = 8</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): No, 360 is not divisible by 17</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q12_1_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_1_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">What letters of the English alphabet have reflectional symmetry (i.e., symmetry related to mirror reflection) about:<br>(a) a vertical mirror<br>(b) a horizontal mirror<br>(c) both horizontal and vertical mirrors</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Reflectional symmetry about a vertical mirror:</strong><br>\n            The letters are: <strong>A, H, I, M, O, T, U, V, W, X, Y</strong>.<br>\n            <strong>(b) Reflectional symmetry about a horizontal mirror:</strong><br>\n            The letters are: <strong>B, C, D, E, H, I, K, O, X</strong>.<br>\n            <strong>(c) Reflectional symmetry about both horizontal and vertical mirrors:</strong><br>\n            The letters having both symmetries are: <strong>H, I, O, X</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each category of symmetric alphabet letters listed</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q12_1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">The following figures have more than one line of symmetry. Such figures are said to have multiple lines of symmetry. Identify multiple lines of symmetry, if any, in: (a) equilateral triangle, (b) square, (c) rectangle, (d) rhombus.</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Equilateral Triangle:</strong> Has <strong>3 lines of symmetry</strong> (the 3 angle bisectors / medians from vertices to opposite sides).<br>\n            <strong>(b) Square:</strong> Has <strong>4 lines of symmetry</strong> (2 connecting midpoints of opposite sides and 2 along the diagonals).<br>\n            <strong>(c) Rectangle:</strong> Has <strong>2 lines of symmetry</strong> (connecting midpoints of opposite sides).<br>\n            <strong>(d) Rhombus:</strong> Has <strong>2 lines of symmetry</strong> (along the two diagonals).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct number and description of symmetry lines</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q12_1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Copy the figure given here. Take any one diagonal as a line of symmetry and shade a few more squares to make the figure symmetric about a diagonal. Is there more than one way to do that? Will the figure have more than one line of symmetry?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            1. <strong>Shading:</strong> Shading squares symmetrically across the diagonal mirror line ensures every shaded square at row r, column c reflects to column c, row r.<br>\n            2. <strong>More than one way?</strong> <strong>Yes</strong>, we can choose either the principal diagonal or the other diagonal as the mirror line, leading to different symmetric shaded patterns.<br>\n            3. <strong>Multiple lines of symmetry?</strong> <strong>Yes</strong>, if additional squares are shaded symmetrically about both diagonals and vertical/horizontal midlines, the resulting composite figure can possess 4 lines of symmetry.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Symmetric shading explanation across diagonal</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Answering whether multiple ways exist</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Answering multiple symmetry lines inquiry</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q12_1_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_1_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Copy the diagram and complete each shape to be symmetric about the mirror line(s).</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            To complete each figure symmetrically about the given mirror lines (dotted lines):<br>\n            1. Measure the perpendicular distance of each vertex of the half-shape from the mirror line.<br>\n            2. Plot corresponding points on the opposite side of the mirror line at the exact same distance.<br>\n            3. Join these reflected points with line segments identical in shape and orientation.<br>\n            When there are two perpendicular mirror lines, reflect the shape across the first line, then reflect both halves across the second mirror line to create a 4-fold symmetric closed figure.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct reflection and geometric completion</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q12_1_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_1_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">What letters of the English alphabet have reflectional symmetry (i.e., symmetry related to mirror reflection) about:<br>(a) a vertical mirror &nbsp;&nbsp; (b) a horizontal mirror &nbsp;&nbsp; (c) both horizontal and vertical mirrors?</div>\n      <div class=\"q-marks\">3 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Vertical mirror symmetry:</strong><br>\n            The letters symmetric about a vertical mirror line are:<br>\n            <strong>A, H, I, M, O, T, U, V, W, X, Y</strong>.<br><br>\n            <strong>(b) Horizontal mirror symmetry:</strong><br>\n            The letters symmetric about a horizontal mirror line are:<br>\n            <strong>B, C, D, E, H, I, K, O, X</strong>.<br><br>\n            <strong>(c) Both horizontal and vertical mirrors:</strong><br>\n            The letters having both vertical and horizontal lines of symmetry are:<br>\n            <strong>H, I, O, X</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing correct letters for each mirror orientation</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q12_3_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_3_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Draw, wherever possible, a rough sketch of:<br>(i) a triangle with both line and rotational symmetries of order more than 1<br>(ii) a triangle with only line symmetry and no rotational symmetry of order more than 1<br>(iii) a quadrilateral with a rotational symmetry of order more than 1 but not a line symmetry<br>(iv) a quadrilateral with line symmetry but not a rotational symmetry of order more than 1.</div>\n      <div class=\"q-marks\">4 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> <strong>Equilateral triangle:</strong> Has 3 lines of symmetry and rotational symmetry of order 3.<br>\n            <strong>(ii)</strong> <strong>Isosceles triangle:</strong> Has exactly 1 line of symmetry (bisector of vertical angle) and rotational symmetry of order only 1.<br>\n            <strong>(iii)</strong> <strong>Parallelogram (non-rectangle, non-rhombus):</strong> Has rotational symmetry of order 2 (turns onto itself at 180° and 360°) but has <strong>no line of symmetry</strong>.<br>\n            <strong>(iv)</strong> <strong>Isosceles trapezium or Kite:</strong> An isosceles trapezium has 1 line of symmetry (connecting midpoints of parallel sides) but only order 1 rotational symmetry. A kite has 1 line of symmetry along its main diagonal and order 1 rotational symmetry.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification and description of each geometric figure</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q12_3_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_3_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">If a figure has two or more lines of symmetry, should it have rotational symmetry of order more than 1?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Yes.</strong><br>\n            If a figure has two or more lines of symmetry intersecting at a central point, then successive reflections across these lines generate a rotation about their point of intersection.<br>\n            Specifically, if the angle between two adjacent intersecting lines of symmetry is <span class=\"math\">\\theta</span>, the figure has rotational symmetry with angle of rotation <span class=\"math\">2\\theta</span>.<br>\n            Since the number of lines of symmetry <span class=\"math\">n ≥ 2</span>, the order of rotational symmetry is at least equal to <span class=\"math\">n</span>, which is strictly <strong>more than 1</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conclusion 'Yes' with mathematical reasoning</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n    <div class=\"q-card\" id=\"q12_1_1_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_1_1_def')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Copy the figures with punched holes and find the axes of symmetry for square and rectangular punched sheets.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            The axis of symmetry is the fold line such that both punched holes coincide exactly when the sheet is folded along it:<br>\n            • If two holes lie vertically opposite on the top and bottom edge, the axis of symmetry is the <strong>horizontal midline</strong>.<br>\n            • If two holes lie horizontally opposite on the left and right edge, the axis of symmetry is the <strong>vertical midline</strong>.<br>\n            • If two holes lie at adjacent corners of a square, the axis of symmetry is the <strong>diagonal</strong> passing between them or the perpendicular bisector connecting them.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Symmetry axis identification through folding rule</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q12_1_3_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_1_3_def')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">In the following figures, the mirror line (i.e., the line of symmetry) is given as a dotted line. Complete each figure performing reflection in the dotted line: (a) square (b) triangle (c) rhombus (d) circle (e) pentagon (f) octagon. Also name the complete figure.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            Reflecting each half-shape across the dotted mirror line produces the complete symmetric closed polygon:<br>\n            • <strong>(a)</strong> Reflecting a rectangle/half-square yields a <strong>Square</strong>.<br>\n            • <strong>(b)</strong> Reflecting a right triangle across its altitude yields an <strong>Isosceles Triangle</strong>.<br>\n            • <strong>(c)</strong> Reflecting half a rhombus across its diagonal yields a <strong>Rhombus</strong>.<br>\n            • <strong>(d)</strong> Reflecting a semicircle across its diameter yields a complete <strong>Circle</strong>.<br>\n            • <strong>(e)</strong> Reflecting half a pentagon yields a regular <strong>Pentagon</strong>.<br>\n            • <strong>(f)</strong> Reflecting half an octagon yields a regular <strong>Octagon</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Reflection and naming the complete geometric polygon</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q12_1_7_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_1_7_def')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">State the number of lines of symmetry for the following figures:<br>(a) An equilateral triangle &nbsp;&nbsp; (b) An isosceles triangle &nbsp;&nbsp; (c) A scalene triangle<br>(d) A square &nbsp;&nbsp; (e) A rectangle &nbsp;&nbsp; (f) A rhombus &nbsp;&nbsp; (g) A parallelogram &nbsp;&nbsp; (h) A circle</div>\n      <div class=\"q-marks\">4 Marks (1/2 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            • <strong>(a) Equilateral triangle:</strong> <strong>3 lines of symmetry</strong>.<br>\n            • <strong>(b) Isosceles triangle:</strong> <strong>1 line of symmetry</strong>.<br>\n            • <strong>(c) Scalene triangle:</strong> <strong>0 lines of symmetry</strong>.<br>\n            • <strong>(d) Square:</strong> <strong>4 lines of symmetry</strong>.<br>\n            • <strong>(e) Rectangle:</strong> <strong>2 lines of symmetry</strong>.<br>\n            • <strong>(f) Rhombus:</strong> <strong>2 lines of symmetry</strong>.<br>\n            • <strong>(g) Parallelogram:</strong> <strong>0 lines of symmetry</strong>.<br>\n            • <strong>(h) Circle:</strong> <strong>Infinitely many lines of symmetry</strong> (any diameter).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Number of lines of symmetry for each figure</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q12_2_1_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_2_1_def')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Which of the following figures have rotational symmetry of order more than 1:<br>(a) Windmill &nbsp;&nbsp; (b) Equilateral triangle &nbsp;&nbsp; (c) Propeller with 3 blades &nbsp;&nbsp; (d) H-shape &nbsp;&nbsp; (e) Circle with 3 equally spaced spokes &nbsp;&nbsp; (f) Four-leaf clover?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            The order of rotational symmetry is the number of times a figure coincides with its original position during a 360° rotation:<br>\n            • <strong>(a) Windmill:</strong> Order 4 (rotates by 90°). Order > 1.<br>\n            • <strong>(b) Equilateral triangle:</strong> Order 3 (rotates by 120°). Order > 1.<br>\n            • <strong>(c) Propeller (3 blades):</strong> Order 3 (rotates by 120°). Order > 1.<br>\n            • <strong>(d) H-shape:</strong> Order 2 (rotates by 180°). Order > 1.<br>\n            • <strong>(e) Circle with 3 spokes:</strong> Order 3 (rotates by 120°). Order > 1.<br>\n            • <strong>(f) Four-leaf clover:</strong> Order 4 (rotates by 90°). Order > 1.<br><br>\n            <strong>All figures (a), (b), (c), (d), (e), and (f) have rotational symmetry of order more than 1.</strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Order calculation for each shape</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Final conclusion stating order > 1</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\">\r\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\r\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\r\n    </div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">Alphabet Symmetry Analysis</div>\r\n        <div class=\"cbq-question\"><strong>Problem:</strong> Name any two letters of the English alphabet that possess: (i) Both line symmetry and rotational symmetry, (ii) Only rotational symmetry of order > 1 but no line symmetry.</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <p><strong>(i) Both line and rotational symmetry:</strong><br>\r\n          Letters <strong>H, I, O, X</strong>.<br>\r\n          • Letter H has 2 lines of symmetry (1 vertical, 1 horizontal) and rotational symmetry of order 2 (rotates by 180°).<br>\r\n          • Letter O has infinitely many lines of symmetry and infinite rotational symmetry.</p>\r\n          <p><strong>(ii) Only rotational symmetry (no line symmetry):</strong><br>\r\n          Letters <strong>S, Z, N</strong>.<br>\r\n          • Letter S rotates by 180° onto itself (order 2), but cannot be folded along any line to coincide.<br>\r\n          • Letter Z rotates by 180° (order 2), but has no line of symmetry.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(11)\">← Chapter 11: Exponents &amp; Powers</button>\r\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(13)\">Chapter 13: Visualising Solid Shapes →</button>\r\n  </div>\r\n</section>\r\n","13":"<section class=\"chapter-section\" id=\"ch13\">\r\n  <div class=\"chapter-header\">\r\n    <div class=\"ch-badge\">13</div>\r\n    <div class=\"chapter-header-info\">\r\n      <h2>Chapter 13: Visualising Solid Shapes</h2>\r\n      <p>NCERT Exercise 13.1 to 13.3 — Complete Solutions as per CBSE Marking Scheme 2026-27</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"concept-card\">\r\n    <div class=\"concept-header\">📌 Key Concepts &amp; 3-D Solid Properties Summary</div>\r\n    <ul class=\"concept-list\">\r\n      <li><strong>3-Dimensional Shapes (Solids):</strong> Figures with length, breadth, and height/depth (e.g. Cube, Cuboid, Cylinder, Cone, Sphere, Prism, Pyramid).</li>\r\n      <li><strong>Polyhedrons:</strong> Solids formed entirely of polygonal planar regions called <strong>Faces</strong> (F). The line segments where faces meet are <strong>Edges</strong> (E). The points where edges meet are <strong>Vertices</strong> (V).</li>\r\n      <li><strong>Euler’s Formula:</strong> For any convex polyhedron:\r\n        F + V - E = 2\r\n      </li>\r\n      <li><strong>Net of a Solid:</strong> A 2-D outline skeleton on paper that can be folded along its edges to construct the 3-D solid shape.</li>\r\n      <li><strong>Visualising Cross-Sections:</strong>\r\n        <ul>\r\n          <li><em>Horizontal cut (parallel to base):</em> Slicing through the height.</li>\r\n          <li><em>Vertical cut (perpendicular to base):</em> Slicing through the cross-axis.</li>\r\n        </ul>\r\n      </li>\r\n    </ul>\r\n  </div>\r\n\r\n  <!-- EXERCISE 13.1 -->\r\n  <div class=\"ex-div\">Exercise 13.1 (Nets of 3-D Solids)</div>\r\n\r\n  <div class=\"q-card\" id=\"q13_1_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q13_1_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Identify the nets which can be used to make cubes (cut out copies of the nets and try it). How many faces does a cube have?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Properties of a Cube Net:</strong><br>\r\n            • A cube has exactly <strong>6 identical square faces</strong>, <strong>12 edges</strong>, and <strong>8 vertices</strong>.<br>\r\n            • In a valid cube net, no two folded squares overlap, and opposite faces never share a common edge in the net.<br>\r\n            • Standard valid nets include the \"T-shape\" (1-4-1 pattern), the cross-shape, and the step patterns (2-3-1 pattern).\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating cube has 6 faces</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying valid non-overlapping foldable nets</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q13_1_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q13_1_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Name the solid that each net can make:<br>(a) A net with 2 identical circular bases and 1 rectangular surface<br>(b) A net with 1 circular base and 1 sector of a circle<br>(c) A net with 1 square base and 4 triangular faces<br>(d) A net with 2 triangular bases and 3 rectangular faces</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) 2 circular bases + 1 rectangular lateral face:</strong> <strong>Cylinder</strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) 1 circular base + 1 sector:</strong> <strong>Cone</strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) 1 square base + 4 triangular faces meeting at apex:</strong> <strong>Square Pyramid</strong>.\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(d) 2 triangular bases + 3 rectangular faces:</strong> <strong>Triangular Prism</strong>.\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correctly identified 3-D solid</span><span class=\"marking-marks\">0.75 Mark each (3 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 13.2 -->\r\n  <div class=\"ex-div\">Exercise 13.2 (Isometric Sketches &amp; Dimension Combining)</div>\r\n\r\n  <div class=\"q-card\" id=\"q13_2_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q13_2_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">Three cubes each with 2 cm edge are placed side by side to form a cuboid. What would be the dimensions (length, breadth, and height) of this cuboid?</div>\r\n      <div class=\"q-marks\">2 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>Geometry Analysis:</strong><br>\r\n            Edge of each cube = <span class=\"math\">2 cm</span>.<br>\r\n            When 3 cubes are placed side by side in a row:<br>\r\n            • Length (<span class=\"math\">l</span>) = <span class=\"math\">2 + 2 + 2 = <strong>6 cm</strong></span>.<br>\r\n            • Breadth (<span class=\"math\">b</span>) remains unchanged = <span class=\"math\"><strong>2 cm</strong></span>.<br>\r\n            • Height (<span class=\"math\">h</span>) remains unchanged = <span class=\"math\"><strong>2 cm</strong></span>.\r\n          </div>\r\n          <p><strong>Conclusion:</strong> The dimensions of the resulting cuboid are <strong>6 cm × 2 cm × 2 cm</strong>.</p>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Length = 2 + 2 + 2 = 6 cm</span><span class=\"marking-marks\">1 Mark</span></div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Breadth = 2 cm, Height = 2 cm</span><span class=\"marking-marks\">1 Mark</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- EXERCISE 13.3 -->\r\n  <div class=\"ex-div\">Exercise 13.3 (Cross-Sections of Solids)</div>\r\n\r\n  <div class=\"q-card\" id=\"q13_3_1\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q13_3_1')\">\r\n      <div class=\"q-num\">Q1</div>\r\n      <div class=\"q-text\">What cross-section do you get when you give a: (i) vertical cut, (ii) horizontal cut to the following solids?<br>(a) A brick<br>(b) A round apple<br>(c) A die<br>(d) A circular pipe<br>(e) An ice cream cone</div>\r\n      <div class=\"q-marks\">4 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <div class=\"step\">\r\n            <strong>(a) A brick (Cuboid):</strong><br>\r\n            (i) Vertical cut: <strong>Rectangle</strong><br>\r\n            (ii) Horizontal cut: <strong>Rectangle</strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) A round apple (Sphere):</strong><br>\r\n            (i) Vertical cut: <strong>Circle</strong><br>\r\n            (ii) Horizontal cut: <strong>Circle</strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) A die (Cube):</strong><br>\r\n            (i) Vertical cut: <strong>Square</strong><br>\r\n            (ii) Horizontal cut: <strong>Square</strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(d) A circular pipe (Cylinder):</strong><br>\r\n            (i) Vertical cut (along axis): <strong>Rectangle</strong><br>\r\n            (ii) Horizontal cut (parallel to base): <strong>Circular ring</strong> (or Circle)\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(e) An ice cream cone (Cone):</strong><br>\r\n            (i) Vertical cut (through apex): <strong>Isosceles Triangle</strong><br>\r\n            (ii) Horizontal cut (parallel to base): <strong>Circle</strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each solid: Vertical and horizontal cut cross-section shape</span><span class=\"marking-marks\">0.8 Mark each (4 Marks total)</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"q-card\" id=\"q13_3_2\">\r\n    <div class=\"q-head\" onclick=\"toggleQ('q13_3_2')\">\r\n      <div class=\"q-num\">Q2</div>\r\n      <div class=\"q-text\">Verify Euler’s formula (F + V − E = 2) for:<br>(a) A Cuboid<br>(b) A Triangular Prism<br>(c) A Square Pyramid</div>\r\n      <div class=\"q-marks\">3 Marks</div>\r\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\r\n    </div>\r\n    <div class=\"q-answer\">\r\n      <div class=\"answer-box\">\r\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\r\n        <div class=\"answer-text\">\r\n          <p>Euler's formula: <span class=\"math\">F + V − E = 2</span>.</p>\r\n          <div class=\"step\">\r\n            <strong>(a) Cuboid:</strong><br>\r\n            • Faces (<span class=\"math\">F</span>) = 6<br>\r\n            • Vertices (<span class=\"math\">V</span>) = 8<br>\r\n            • Edges (<span class=\"math\">E</span>) = 12<br>\r\n            Verification: <span class=\"math\">F + V − E = 6 + 8 − 12 = 14 − 12 = <strong>2</strong></span>. <strong>Verified!</strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(b) Triangular Prism:</strong><br>\r\n            • Faces (<span class=\"math\">F</span>) = 5 (2 triangular + 3 rectangular)<br>\r\n            • Vertices (<span class=\"math\">V</span>) = 6<br>\r\n            • Edges (<span class=\"math\">E</span>) = 9<br>\r\n            Verification: <span class=\"math\">F + V − E = 5 + 6 − 9 = 11 − 9 = <strong>2</strong></span>. <strong>Verified!</strong>\r\n          </div>\r\n          <div class=\"step\">\r\n            <strong>(c) Square Pyramid:</strong><br>\r\n            • Faces (<span class=\"math\">F</span>) = 5 (1 square + 4 triangular)<br>\r\n            • Vertices (<span class=\"math\">V</span>) = 5 (1 apex + 4 base corners)<br>\r\n            • Edges (<span class=\"math\">E</span>) = 8 (4 base edges + 4 slant edges)<br>\r\n            Verification: <span class=\"math\">F + V − E = 5 + 5 − 8 = 10 − 8 = <strong>2</strong></span>. <strong>Verified!</strong>\r\n          </div>\r\n        </div>\r\n        <div class=\"marking-scheme\">\r\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\r\n          <div class=\"marking-row\"><span class=\"marking-key\">Each solid: F, V, E count and verification of F + V − E = 2</span><span class=\"marking-marks\">1 Mark each</span></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n    <div class=\"q-card\" id=\"q13_1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Match the nets with appropriate solids:<br>(a) Cylinder (tube with 2 circular lids)<br>(b) Square pyramid (square base with 4 triangles)<br>(c) Cube (6 congruent squares)<br>(d) Cone (sector with 1 circular base)</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Matching 3D Solids to their unfolded 2D Nets:</strong><br>\n            • <strong>(a) Cylinder:</strong> Matches net with one rectangular curved face and two identical circular bases.<br>\n            • <strong>(b) Square Pyramid:</strong> Matches net with one central square base and four surrounding triangular faces.<br>\n            • <strong>(c) Cube:</strong> Matches net consisting of 6 congruent squares in a cross or T-shape.<br>\n            • <strong>(d) Cone:</strong> Matches net consisting of a sector of a circle and one circular base.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct net matching</span><span class=\"marking-marks\">1/2 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q13_1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Here is an incomplete net for making a cube. Complete it in at least two different ways. Remember that a cube has six faces. How many are there in this net?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            1. <strong>Count of faces:</strong> The given incomplete net has <strong>3 square faces</strong>.<br>\n            2. Since a cube has 6 faces in total, <strong>3 more square faces</strong> must be added.<br>\n            3. <strong>Two different ways:</strong><br>\n            • <em>Way 1:</em> Form a \"T-shape\" or classic cross net with 4 squares in a central vertical column and 1 square extending on the left and 1 square on the right.<br>\n            • <em>Way 2:</em> Form a \"step\" or \"Z-shape\" (3-3 arrangement) where two rows of 3 squares each are offset by one unit.<br>\n            Both arrangements fold perfectly into a closed 6-faced cube without overlap.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating 3 existing faces and 3 required faces</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Two valid 6-faced cube net configurations</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q13_2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">The dimensions of a cuboid are 5 cm, 3 cm and 2 cm. Draw three different isometric sketches of this cuboid.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            On isometric dot paper, lines are drawn along the three 120° isometric axes representing Length (l), Breadth (b), and Height (h):<br>\n            • <strong>Sketch 1:</strong> Length = 5 units, Breadth = 3 units, Height = 2 units (cuboid resting on 5×3 face).<br>\n            • <strong>Sketch 2:</strong> Length = 5 units, Breadth = 2 units, Height = 3 units (cuboid resting on 5×2 face).<br>\n            • <strong>Sketch 3:</strong> Length = 3 units, Breadth = 2 units, Height = 5 units (cuboid resting on 3×2 face, standing tall).<br>\n            All 3 sketches show the exact same cuboid viewed from different orientations, with edge lengths scaled proportionally to isometric dots.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Three distinct orientations with accurate dimensions</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q13_2_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_2_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Two dice are placed side by side with 5 + 2 on top faces and 6 + 1. What would be the total on the face opposite to:<br>(a) 5 + 6 &nbsp;&nbsp; (b) 1 + 2?</div>\n      <div class=\"q-marks\">2 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            On standard dice, the sum of numbers on opposite faces is always 7.<br>\n            • Face opposite to 5 is <span class=\"math\">7 − 5 = 2</span>.<br>\n            • Face opposite to 6 is <span class=\"math\">7 − 6 = 1</span>.<br>\n            • Face opposite to 1 is <span class=\"math\">7 − 1 = 6</span>.<br>\n            • Face opposite to 2 is <span class=\"math\">7 − 2 = 5</span>.<br><br>\n            <strong>(a)</strong> Face opposite to (5 and 6) = <span class=\"math\">2 + 1 = <strong>3</strong></span>.<br>\n            <strong>(b)</strong> Face opposite to (1 and 2) = <span class=\"math\">6 + 5 = <strong>11</strong></span>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Opposite face rule and correct sum for (a) and (b)</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q13_4_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_4_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">A bulb is kept burning just above the following solids. Name the shape of the shadows obtained in each case:<br>(i) A ball &nbsp;&nbsp; (ii) A cylindrical pipe &nbsp;&nbsp; (iii) A book</div>\n      <div class=\"q-marks\">3 Marks (1 Mark each)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            When light falls from directly above onto the 3D solid, the 2D shadow cast on the floor represents its orthogonal/top projection:<br>\n            <strong>(i) A ball (spherical solid):</strong> The shadow obtained is a <strong>Circle</strong>.<br>\n            <strong>(ii) A cylindrical pipe:</strong> If standing vertical, shadow is a <strong>Circle / Circular ring</strong>; if placed horizontally, the shadow is a <strong>Line segment / Rectangle</strong>.<br>\n            <strong>(iii) A book (cuboid):</strong> The shadow cast directly below is a <strong>Rectangle</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct 2D shadow shape identification</span><span class=\"marking-marks\">1 Mark each</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n    <div class=\"q-card\" id=\"q13_1_1_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_1_1_def')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Identify the nets which can be used to make cubes among the given 6-square patterns.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            A valid cube net must consist of 6 connected squares such that folding along edges forms a closed cube without any faces overlapping:<br>\n            • <strong>Valid nets:</strong> Patterns (ii), (iii), (iv), and (vi) fold into complete closed cubes without overlapping faces.<br>\n            • <strong>Invalid nets:</strong> Patterns (i) and (v) cannot make a cube because some faces overlap, leaving one or more faces open.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correctly identifying valid cube folding nets</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q13_2_1_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_2_1_def')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Explain how isometric dot paper is used to make an isometric sketch of a 3D solid shape like a cuboid.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            On isometric dot paper, dots are arranged at the vertices of equilateral triangles, forming axes at 120° to each other:<br>\n            1. Draw the base edges along the slanted isometric axes proportional to the given length and breadth.<br>\n            2. Draw vertical line segments at the vertices equal to the height of the cuboid.<br>\n            3. Join the top endpoints to form the top face.<br>\n            In an isometric sketch, measurements are drawn to exact scale along the isometric axes, preserving proportional dimensions.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Isometric dot paper principles and sketching steps</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q13_3_1_def\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_3_1_def')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">What cross-sections do you get when you give a: (i) vertical cut (ii) horizontal cut to a solid sphere, cylinder, and cone?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            A cross-section is the 2D surface exposed when a solid is cut by a plane:<br>\n            • <strong>Sphere:</strong> Both vertical and horizontal cuts give a <strong>Circle</strong>.<br>\n            • <strong>Cylinder:</strong> A vertical cut gives a <strong>Rectangle</strong>; a horizontal cut gives a <strong>Circle</strong>.<br>\n            • <strong>Cone:</strong> A vertical cut through the apex gives a <strong>Triangle</strong>; a horizontal cut gives a <strong>Circle</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Cross-section shapes for each cut orientation</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\r\n  <div class=\"cbq-section\">\r\n    <div class=\"cbq-header\">\r\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\r\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\r\n    </div>\r\n    <div class=\"cbq-body\">\r\n      <div class=\"cbq-card\">\r\n        <div class=\"cbq-type\" style=\"color:#4f46e5;\">Euler's Formula Polyhedron Test</div>\r\n        <div class=\"cbq-question\"><strong>Problem:</strong> Can a polyhedron have 10 faces, 20 edges and 15 vertices? Justify your answer using Euler’s formula.</div>\r\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\r\n        <div class=\"cbq-answer\">\r\n          <p>Given parameters:<br>\r\n          Faces, <span class=\"math\">F = 10</span><br>\r\n          Edges, <span class=\"math\">E = 20</span><br>\r\n          Vertices, <span class=\"math\">V = 15</span>.</p>\r\n          <p>By Euler's Formula for any polyhedron:<br>\r\n          <span class=\"math\">F + V − E = 2</span>.</p>\r\n          <p>Substituting given values:<br>\r\n          <span class=\"math\">LHS = F + V − E = 10 + 15 − 20 = 25 − 20 = <strong>5</strong></span>.</p>\r\n          <p>Since <span class=\"math\">5 ≠ 2</span>, the given values violate Euler’s formula.</p>\r\n          <p><strong>Conclusion:</strong> <strong>No</strong>, a polyhedron cannot have 10 faces, 20 edges, and 15 vertices.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"ch-nav-btns\">\r\n    <button class=\"ch-nav-btn prev\" onclick=\"showChapter(12)\">← Chapter 12: Symmetry</button>\r\n    <button class=\"ch-nav-btn\" disabled style=\"opacity:.35;\">Next Chapter →</button>\r\n  </div>\r\n</section>\r\n"};
